import classNames from 'classnames';
import type { Node as ProseMirrorNode } from 'prosemirror-model';

import {
  getLayoutWrapperDataHook,
  LAYOUT_HANDLE,
} from './../../ricos-common-plugins/layout/data-hooks.js';
import { createResizeHandler } from './../../ricos-common-plugins/resizable/create-resize-handler.js';
import { TIPTAP_LAYOUT_CELL_TYPE, TIPTAP_LAYOUT_TYPE } from './../../ricos-content/index.js';
import type { ModalService } from './../../ricos-modals/index.js';
import type { Node as NodeOld } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';
import type { Gradient } from './../../ricos-types/color-palette-types.js';
import type { RicosPalette } from './../../ricos-types/index.js';
import type { ExtensionProps } from './../../ricos-types/tiptap.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import { getMoveIcon } from './../../_shared/drag-handle-icons.js';
import { getElementScale } from './../../_shared/get-element-scale.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { resolveBackwardCompatOverlay } from './../../_shared/resolve-backward-compat-overlay.js';
import { schemaGradientToCss } from './../../_shared/schema-gradient-to-css.js';
import { resolveDocumentColorToCss } from './../../_shared/theme-color-token.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../tiptap/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { Node as PmNode, ResolvedPos } from './../../tiptap/pm/model.js';
import { NodeSelection } from './../../tiptap/pm/state.js';
import { getContrastYIQ } from './../../wix-rich-content-common/Utils/color-utils.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';

import staticsStyles from '../statics/styles-scss.js';
import { setAttr, setChild, setClass, setStyleVar, setText } from './idempotent-dom.js';
import { isEditorOrModalActive } from './is-editor-or-modal-active.js';
import { layoutConverter } from './layout-converter.js';
import { getResolvedLayoutFillColor, getResolvedLayoutFillGradient } from './layout-fill.js';
import styles from './layouts-scss.js';
import {
  LAYOUT_DEFAULTS,
  MAX_CELLS,
  MAX_COLUMNS,
  MAX_VERTICAL_MARGIN,
  MIN_COL_SPAN,
} from './shared-with-viewer.js';
import type { LayoutExtensionStorage } from './shared.js';
import { balanceLayoutCells, findLayoutOfCell, getImageUrl } from './shared.js';

type LayoutNodeViewState = {
  columnTemplate: number[];
  isResizing: boolean;
  isDragging: boolean;
  invalid: 'none' | 'left' | 'right';
  dropCursorPosition: null | number;
  isDraggingOver: boolean;
};

type LayoutNodeViewOptions = {
  disableInteractions: boolean;
  breakoutRule: ExtensionProps['breakoutRule'];
  isMobile: boolean;
  colorPalette?: RicosPalette;
  modals?: ModalService;
};

export const layoutNodeView =
  ({
    disableInteractions,
    breakoutRule,
    isMobile,
    colorPalette,
    modals,
  }: LayoutNodeViewOptions): NodeViewRenderer =>
  ({ node, getPos, editor }) => {
    const state: LayoutNodeViewState = {
      columnTemplate: getGridTemplateColumns(node),
      isResizing: false,
      isDragging: false,
      invalid: 'none',
      dropCursorPosition: null,
      isDraggingOver: false,
    };
    const resizableHandlerCleanups: (() => void)[] = [];
    const layoutWrapper = document.createElement('div');
    layoutWrapper.setAttribute('data-layout-wrapper', '');
    layoutWrapper.setAttribute('data-hook', getLayoutWrapperDataHook(node.attrs.id));
    layoutWrapper.classList.add(styles.layoutWrapper);

    if (disableInteractions) {
      layoutWrapper.classList.add(styles.disabled);
    }

    const layoutStyle = document.createElement('style');
    layoutStyle.setAttribute('data-layout-style', node.attrs.id);
    layoutWrapper.append(layoutStyle);

    const layoutElement = document.createElement('div');

    // Wrap layoutElement in a container that will hold resize handles.
    // ProseMirror only manages contentDOM (layoutElement), so handles
    // attached to layoutContainer won't be removed during DOM reconciliation.
    const layoutContainer = document.createElement('div');
    layoutContainer.setAttribute('data-resize-container', '');
    layoutContainer.classList.add(styles.layoutContainer);
    layoutContainer.append(layoutElement);

    const hasBreakout = breakoutRule
      ? breakoutRule({
          node: layoutConverter.fromPm.convert(node.toJSON()) as NodeOld,
        }) === 'fullWidth'
      : false;

    if (hasBreakout) {
      layoutWrapper.classList.add(styles.breakoutMargin);
    }

    const breakoutWrapper = document.createElement('div');
    breakoutWrapper.setAttribute('data-breakout', 'normal');
    breakoutWrapper.append(layoutContainer);

    layoutWrapper.append(breakoutWrapper);

    const dropCursorElement = document.createElement('div');
    dropCursorElement.classList.add(styles.dropCursor);

    const setState = (newState: Partial<LayoutNodeViewState>) => {
      // We need to keep ref to state object as updates can be triggered by ProseMirror and by us manually. We also we
      // need to keep latest state values in event listeners avoiding closure issues
      const isStateEqual = Object.entries(newState).every(
        ([key, value]) => state[key as keyof LayoutNodeViewState] === value
      );
      if (isStateEqual) {
        return;
      }
      Object.assign(state, newState);

      updateLayoutView({
        layoutWrapper,
        layoutStyle,
        layoutElement,
        layoutContainer,
        breakoutWrapper,
        dropCursorElement,
        state,
        node,
        getPos,
        editor,
        resizableHandlerCleanups,
        isMobile,
        disableInteractions,
        colorPalette,
        modals,
      });
    };

    updateLayoutView({
      layoutWrapper,
      layoutStyle,
      layoutElement,
      layoutContainer,
      breakoutWrapper,
      dropCursorElement,
      state,
      node,
      getPos,
      editor,
      resizableHandlerCleanups,
      isMobile,
      disableInteractions,
      colorPalette,
      modals,
    });

    const runLayoutUpdate = () =>
      updateLayoutView({
        layoutWrapper,
        layoutStyle,
        layoutElement,
        layoutContainer,
        breakoutWrapper,
        dropCursorElement,
        state,
        node,
        getPos,
        editor,
        resizableHandlerCleanups,
        isMobile,
        disableInteractions,
        colorPalette,
        modals,
      });
    const onFocus = () => {
      runLayoutUpdate();
    };
    const onBlur = ({ event }: { event: FocusEvent }) => {
      // Skip update when focus moves to an element within the layout (e.g. cell handle, resize handle)
      if (event.relatedTarget && layoutWrapper.contains(event.relatedTarget as Node)) {
        return;
      }
      runLayoutUpdate();
    };
    editor.on('selectionUpdate', runLayoutUpdate);
    editor.on('focus', onFocus);
    editor.on('blur', onBlur);

    // Refresh chrome when a modal opens/closes — opening a settings modal blurs
    // the editor before the modal mount, and we want the selection to stay
    // visible while the modal is up. The modal service's pub/sub wiring is
    // attached after the editor is constructed, so defer to a microtask.
    let modalSubsCancelled = false;
    let modalSubs: { cancel: () => void }[] = [];
    queueMicrotask(() => {
      if (modalSubsCancelled || !modals) {
        return;
      }
      modalSubs = [modals.onModalOpened(runLayoutUpdate), modals.onModalClosed(runLayoutUpdate)];
    });

    const removeFocusListeners = () => {
      editor.off('selectionUpdate', runLayoutUpdate);
      editor.off('focus', onFocus);
      editor.off('blur', onBlur);
      modalSubsCancelled = true;
      modalSubs.forEach(s => s.cancel());
    };

    const cleanups = disableInteractions
      ? [removeFocusListeners]
      : [
          removeFocusListeners,
          attachCellResizeHandler({ layoutElement, state, editor, setState }),
          attachCellDragHandler({ layoutElement, editor, setState }),
          attachLayoutEventHandlers({
            layoutWrapper,
            layoutElement,
            editor,
            setState,
          }),
        ];

    return {
      dom: layoutWrapper,
      contentDOM: layoutElement,
      update: (newNode: PmNode) => {
        if (newNode.type !== node.type) {
          return false;
        }
        if (!state.isResizing) {
          state.columnTemplate = getGridTemplateColumns(newNode);
        }
        // oxlint-disable-next-line no-param-reassign
        node = newNode;
        updateLayoutView({
          layoutWrapper,
          layoutStyle,
          layoutElement,
          layoutContainer,
          breakoutWrapper,
          dropCursorElement,
          state,
          node: newNode,
          getPos,
          editor,
          resizableHandlerCleanups,
          isMobile,
          disableInteractions,
          colorPalette,
          modals,
        });
        return true;
      },
      ignoreMutation: (mutation: MutationRecord | { type: 'selection'; target: Node }) => {
        const isMutatingLayoutStyle = mutation.target === layoutStyle;
        const isMutatingDataAttribute =
          mutation.type === 'attributes' && mutation.attributeName?.startsWith('data-');
        const isMutatingLayoutAttribute =
          mutation.target === layoutElement && mutation.type === 'attributes';
        const isMutatingLayoutWrapperAttribute =
          mutation.target === layoutWrapper && mutation.type === 'attributes';
        const isMutatingLayoutWrapperChildren =
          mutation.target === layoutWrapper && mutation.type === 'childList';
        const isMutatingDropCursor = mutation.target === dropCursorElement;
        // Ignore mutations to breakout wrapper
        const isMutatingBreakoutWrapper = mutation.target === breakoutWrapper;
        // Ignore mutations to layout container (resize handles are attached here)
        const isMutatingLayoutContainer = mutation.target === layoutContainer;

        return (
          isMutatingLayoutStyle ||
          isMutatingDataAttribute ||
          isMutatingLayoutAttribute ||
          isMutatingLayoutWrapperAttribute ||
          isMutatingLayoutWrapperChildren ||
          isMutatingDropCursor ||
          isMutatingBreakoutWrapper ||
          isMutatingLayoutContainer
        );
      },
      destroy: () => {
        cleanups.forEach(cleanup => cleanup());
        resizableHandlerCleanups.forEach(cleanup => cleanup());
        resizableHandlerCleanups.length = 0;
      },
    };
  };

const attachResizeHandlers = ({
  layoutContainer,
  layoutWrapper,
  editor,
  node,
  resizableHandlerCleanups,
}: Pick<NodeViewRendererProps, 'editor' | 'node'> & {
  layoutContainer: HTMLDivElement;
  layoutWrapper: HTMLDivElement;
  resizableHandlerCleanups: (() => void)[];
}) => {
  const minWidth = 200;

  const cleanupHorizontalResizeHandler = createResizeHandler({
    resizeElement: layoutContainer,
    isEnabled: true,
    getMinWidth: () => minWidth,
    getMaxWidth: () => {
      const nodeContainer = layoutContainer.closest('[data-breakout="normal"]') as HTMLElement;
      const nodeContentStyles = window.getComputedStyle(nodeContainer);
      const paddingStart = parseInt(nodeContentStyles.paddingInlineStart) || 0;
      const paddingEnd = parseInt(nodeContentStyles.paddingInlineEnd) || 0;

      return Math.max(minWidth, nodeContainer.clientWidth - paddingStart - paddingEnd);
    },
    enable: { left: true, right: true },
    lockAspectRatio: false,
    setMaxWidthAsPercentage: true,
    alignment: 'CENTER',
    onResize: () => {
      // Visual update during resize is handled by CSS variable --ricos-internal-resize-width
      // Editor state is updated only in onResizeStop to avoid lag
    },
    onResizeStop: ({ width, isMaxWidth }) => {
      editor
        .chain()
        .setContainerWidth(node.attrs.id, isMaxWidth ? null : width)
        .run();
    },
  });
  resizableHandlerCleanups.push(cleanupHorizontalResizeHandler);

  // Create vertical resize handler. Both top and bottom margins are linked
  // (change together). The handle sits on the layout's "free" edge:
  //  - footer banner (BOTTOM) → top edge (where it meets the content above)
  //  - top banner / regular layout → bottom edge
  const isFooterBanner = node.attrs.banner?.position === 'BOTTOM';
  const cleanupVerticalResize = createVerticalMarginResizeHandler({
    layoutWrapper,
    position: isFooterBanner ? 'top' : 'bottom',
    minPadding: 0,
    onResize: (newPadding: number) => {
      editor
        .chain()
        .updateNodeAttrsById(node.attrs.id, {
          backdropPaddingTop: newPadding,
          backdropPaddingBottom: newPadding,
        })
        .run();
    },
  });
  resizableHandlerCleanups.push(cleanupVerticalResize);
};

const updateLayoutView = ({
  layoutWrapper,
  layoutStyle,
  layoutElement,
  layoutContainer,
  breakoutWrapper,
  dropCursorElement,
  state,
  node,
  getPos,
  editor,
  resizableHandlerCleanups,
  isMobile,
  disableInteractions,
  colorPalette,
  modals,
}: Pick<NodeViewRendererProps, 'node' | 'getPos' | 'editor'> & {
  layoutWrapper: HTMLDivElement;
  layoutStyle: HTMLStyleElement;
  layoutElement: HTMLDivElement;
  layoutContainer: HTMLDivElement;
  breakoutWrapper: HTMLDivElement;
  dropCursorElement: HTMLDivElement;
  state: LayoutNodeViewState;
  resizableHandlerCleanups: (() => void)[];
  isMobile: boolean;
  disableInteractions: boolean;
  colorPalette?: RicosPalette;
  modals?: ModalService;
}) => {
  const { $to, $from } = editor.state.selection;
  const pos = getPos();
  const layoutEnd = pos + node.nodeSize;
  const isSelected = pos === $from.pos && layoutEnd === $to.pos;
  const isInSelection = pos >= $from.pos && layoutEnd <= $to.pos;
  const inLayout = isInLayout($to, node.attrs.id);
  const isCellSelected = isCellInLayoutSelected($to, $from, node.attrs.id, editor);
  // While a modal is open the editor blurs, but the user is still acting on
  // this layout — keep chrome visible only when it is the strict NodeSelection
  // target. Cursor-in-layout / range-covers-layout / cell-selected chrome
  // requires real editor focus.
  const shouldShowActiveLayoutStyles =
    editor.view.hasFocus() || (isEditorOrModalActive(editor.view, modals) && isSelected);
  const scopeValue = `${node.attrs.id}-${node.attrs.responsivenessBreakpoint}-${node.attrs.responsivenessBehaviour}`;
  const isWrapping = node.attrs.responsivenessBehaviour === 'WRAP';
  const isBanner = !!node.attrs.banner;
  // Show side resize handles when layout is selected, a cell is selected, cursor is inside the layout, or during column resize
  const shouldShowResize =
    shouldShowActiveLayoutStyles &&
    (isSelected || isInSelection || isCellSelected || inLayout || state.isResizing);

  // Resize handler lifecycle (transition-only).
  const hasResizeHandlers = resizableHandlerCleanups.length > 0;
  if (hasResizeHandlers && !shouldShowResize) {
    resizableHandlerCleanups.forEach(cleanup => cleanup());
    resizableHandlerCleanups.length = 0;
  } else if (shouldShowResize && !hasResizeHandlers && !disableInteractions) {
    attachResizeHandlers({
      layoutContainer,
      layoutWrapper,
      editor,
      node,
      resizableHandlerCleanups,
    });
  }

  // Drag handle (creation-only; subsequent runs just update its data-hook).
  const existingDragHandleWrapper = breakoutWrapper.querySelector(
    '[data-layout-drag-handle-wrapper]'
  ) as HTMLDivElement | null;
  if (!isBanner && !existingDragHandleWrapper) {
    createLayoutDragHandle({ breakoutWrapper, layoutElement, nodeId: node.attrs.id, editor });
  } else if (isBanner && existingDragHandleWrapper) {
    existingDragHandleWrapper.remove();
  } else if (!isBanner && existingDragHandleWrapper) {
    const existingDragHandle = existingDragHandleWrapper.querySelector(
      '[data-layout-handle]'
    ) as HTMLButtonElement | null;
    if (existingDragHandle) {
      setAttr(existingDragHandle, 'data-hook', `${LAYOUT_HANDLE}-${node.attrs.id}`);
    }
  }

  // layoutWrapper: classes, data attributes.
  layoutWrapper.classList.toggle(styles.withVerticalResize, shouldShowResize);
  setAttr(
    layoutWrapper,
    'data-layout-banner',
    isBanner ? (node.attrs.banner?.position === 'BOTTOM' ? 'bottom' : 'top') : null
  );

  // layoutWrapper: refresh data-hook so it tracks the node id across updates.
  setAttr(layoutWrapper, 'data-hook', getLayoutWrapperDataHook(node.attrs.id));

  // layoutElement: data attributes, class set, column template var.
  setAttr(layoutElement, 'data-layout-container', node.attrs.id);
  setAttr(layoutElement, 'data-layout-scope', scopeValue);
  setStyleVar(
    layoutElement,
    '--ricos-internal-layout-column-template',
    formatGridTemplateColumns(state.columnTemplate)
  );
  setClass(
    layoutElement,
    classNames({
      [styles.layout]: true,
      [styles.designOnLayout]: !node.attrs.designTarget || node.attrs.designTarget === 'LAYOUT',
      [styles.designOnCell]: node.attrs.designTarget === 'CELL',
      [styles.mobile]: isMobile,
      [styles.draggingOver]: state.isDraggingOver || state.dropCursorPosition !== null,
      [styles.invalidLeft]: state.invalid === 'left',
      [styles.invalidRight]: state.invalid === 'right',
      [styles.resizing]: state.isResizing,
      [styles.dragging]: state.isDragging,
      [styles.layoutSelected]: shouldShowActiveLayoutStyles && isInSelection,
      [styles.inLayout]: shouldShowActiveLayoutStyles && inLayout,
      [styles.bannerMargin]: node.attrs.banner,
    })
  );

  // layoutContainer: custom width.
  const customWidth = node.attrs.containerData?.width?.custom;
  setStyleVar(
    layoutContainer,
    '--ricos-internal-layout-width',
    customWidth ? `${customWidth}px` : null
  );

  // layoutStyle: responsive container query CSS.
  const maxWidth = node.attrs.responsivenessBreakpoint
    ? parseInt(node.attrs.responsivenessBreakpoint, 10)
    : LAYOUT_DEFAULTS.responsivenessBreakpoint;
  const styleContent = `
    [data-layout-scope="${scopeValue}"].${styles.layout} {
      --ricos-internal-layout-display: ${isWrapping ? 'flex' : 'grid'};
      --ricos-internal-layout-justify-content: ${isWrapping ? 'center' : 'auto'};
      --ricos-internal-layout-grid-template: grid-template-columns: minmax(0, 1fr);
      --ricos-internal-layout-cell-min-width: ${
        isWrapping
          ? `${Math.floor(node.attrs.responsivenessBreakpoint / node.childCount)}px`
          : '100%'
      };
      --ricos-internal-layout-cell-height: ${isWrapping ? 'auto' : '100%'};
    }
    [data-layout-scope="${scopeValue}"] .${styles.resizeHandler} {
      display: none;
    }
  `;
  setText(
    layoutStyle,
    `
    @supports not (contain: inline-size) {
      @media only screen and (max-width: ${maxWidth}px) {
        ${styleContent}
      }
    }

    @container (width < ${maxWidth}px) {
      ${styleContent}
    }
  `
  );

  // dropCursor: presence + position.
  const showDropCursor = state.dropCursorPosition !== null;
  setStyleVar(
    dropCursorElement,
    '--ricos-internal-layout-drop-cursor-position',
    showDropCursor ? `${state.dropCursorPosition}px` : null
  );
  setChild(layoutWrapper, dropCursorElement, showDropCursor);

  // Background fill (gradient OR color OR none).
  const backgroundGradient = getResolvedLayoutFillGradient(
    node.attrs.background,
    node.attrs.backgroundColor
  );
  const backgroundColorValue = getResolvedLayoutFillColor(
    node.attrs.background,
    node.attrs.backgroundColor
  );
  applyFill(layoutElement, {
    gradient: backgroundGradient,
    color: backgroundColorValue,
    gradientVar: '--ricos-internal-layout-background-gradient',
    colorVar: '--ricos-internal-layout-background-color',
    colorPalette,
  });

  // Background image.
  applyImage(layoutElement, node.attrs.backgroundImage, '--ricos-internal-layout-background-image');

  // Background image overlay (only visible when image present): gradient > color-with-opacity.
  applyImageOverlay(layoutElement, {
    image: node.attrs.backgroundImage,
    gradient: backgroundGradient,
    color: backgroundColorValue,
    overlayVar: '--ricos-internal-layout-background-overlay',
  });

  // Border + radius + gap on layoutElement.
  setStyleVar(
    layoutElement,
    '--ricos-internal-layout-border-color',
    node.attrs.borderColor
      ? (resolveDocumentColorToCss(node.attrs.borderColor) ?? node.attrs.borderColor)
      : null
  );
  setStyleVar(
    layoutElement,
    '--ricos-internal-layout-border-width',
    node.attrs.borderColor ? `${node.attrs.borderWidth}px` : null
  );
  setStyleVar(
    layoutElement,
    '--ricos-internal-layout-border-radius',
    node.attrs.borderRadius ? `${node.attrs.borderRadius}px` : null
  );
  // NB: existing code wrote `--ricos-internal-layout-vertical-gap` only on removal,
  // and `--ricos-internal-layout-gap` only on set. Preserved as-is to avoid behavior change.
  setStyleVar(
    layoutElement,
    '--ricos-internal-layout-gap',
    typeof node.attrs.gap === 'number' ? `${node.attrs.gap}px` : null
  );
  if (typeof node.attrs.gap !== 'number') {
    setStyleVar(layoutElement, '--ricos-internal-layout-vertical-gap', null);
  }

  // Backdrop fill (gradient OR color OR none).
  const backdropGradient = getResolvedLayoutFillGradient(
    node.attrs.backdrop,
    node.attrs.backdropColor
  );
  const backdropColorValue = getResolvedLayoutFillColor(
    node.attrs.backdrop,
    node.attrs.backdropColor
  );
  applyFill(layoutWrapper, {
    gradient: backdropGradient,
    color: backdropColorValue,
    gradientVar: '--ricos-internal-layout-backdrop-gradient',
    colorVar: '--ricos-internal-layout-backdrop-color',
    colorPalette,
  });

  // Backdrop image.
  applyImage(layoutWrapper, node.attrs.backdropImage, '--ricos-internal-layout-backdrop-image');

  // Backdrop padding.
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-backdrop-padding-top',
    node.attrs.backdropPaddingTop ? `${node.attrs.backdropPaddingTop}px` : null
  );
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-backdrop-padding-bottom',
    node.attrs.backdropPaddingBottom ? `${node.attrs.backdropPaddingBottom}px` : null
  );

  // Backdrop image overlay (only visible when image present): gradient > color-with-opacity.
  applyImageOverlay(layoutWrapper, {
    image: node.attrs.backdropImage,
    gradient: backdropGradient,
    color: backdropColorValue,
    overlayVar: '--ricos-internal-layout-backdrop-overlay',
  });

  // Cell padding (4-side, with css-shorthand-style fallbacks: cellPadding[i] || [i-2] || [0]).
  const cellPadding =
    node.attrs.cellPadding && node.attrs.cellPadding.length > 0 ? node.attrs.cellPadding : null;
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-cell-padding-top',
    cellPadding ? `${cellPadding[0]}px` : null
  );
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-cell-padding-right',
    cellPadding ? `${cellPadding[1] ?? cellPadding[0]}px` : null
  );
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-cell-padding-bottom',
    cellPadding ? `${cellPadding[2] ?? cellPadding[0]}px` : null
  );
  setStyleVar(
    layoutWrapper,
    '--ricos-internal-layout-cell-padding-left',
    cellPadding ? `${cellPadding[3] ?? cellPadding[1] ?? cellPadding[0]}px` : null
  );

  // Cell vertical alignment.
  const verticalAlignment =
    node.attrs.cellVerticalAlignment === 'TOP'
      ? 'flex-start'
      : node.attrs.cellVerticalAlignment === 'BOTTOM'
        ? 'flex-end'
        : node.attrs.cellVerticalAlignment
          ? 'center'
          : null;
  setStyleVar(layoutWrapper, '--ricos-internal-layout-cell-vertical-alignment', verticalAlignment);
};

type ApplyFillArgs = {
  gradient: ReturnType<typeof getResolvedLayoutFillGradient>;
  color: ReturnType<typeof getResolvedLayoutFillColor>;
  gradientVar: string;
  colorVar: string;
  colorPalette?: RicosPalette;
};

// Apply a fill (gradient OR solid color) to an element via CSS variables.
// Mirrors the original three-way precedence: gradient > color > none.
const applyFill = (
  el: HTMLElement,
  { gradient, color, gradientVar, colorVar, colorPalette }: ApplyFillArgs
) => {
  setStyleVar(el, gradientVar, gradient ? schemaGradientToCss(gradient as Gradient) : null);
  setStyleVar(
    el,
    colorVar,
    !gradient && color ? (resolveDocumentColorToCss(color) ?? color) : null
  );
  setStyleVar(
    el,
    '--ricos-internal-selection-color-tuple',
    !gradient && color && color !== TRANSPARENT_HEX_COLOR
      ? getContrastYIQ(color, colorPalette) === 'black'
        ? '0, 0, 0'
        : '255, 255, 255'
      : null
  );
};

// Apply an optional background/backdrop image to an element via CSS variables.
const applyImage = (
  el: HTMLElement,
  image: PmNode['attrs']['backgroundImage'] | undefined,
  varPrefix: string
) => {
  const imageUrl = image
    ? (image.media?.src.url ?? (image.media?.src.id && getImageUrl(image.media)))
    : null;
  setStyleVar(el, `${varPrefix}-src`, imageUrl ? `url(${imageUrl})` : null);
  setStyleVar(el, `${varPrefix}-opacity`, image?.opacity ? `${image.opacity}%` : null);
  setStyleVar(el, `${varPrefix}-scaling`, image?.scaling ? image.scaling.toLowerCase() : null);
  setStyleVar(
    el,
    `${varPrefix}-position`,
    image?.position ? image.position.toLowerCase().split('_').join(' ') : null
  );
  // Blur is independent of any color overlay — both layers stack.
  setStyleVar(el, `${varPrefix}-blur`, image?.blur ? `blur(${image.blur}px)` : null);
};

type ApplyImageOverlayArgs = {
  image: PmNode['attrs']['backgroundImage'] | undefined;
  gradient: ReturnType<typeof getResolvedLayoutFillGradient>;
  color: ReturnType<typeof getResolvedLayoutFillColor>;
  overlayVar: string;
};

// Apply a color/gradient overlay to a background/backdrop image. Only set when an image is present.
// `image.overlay` (new model) is authoritative when present; otherwise the legacy `background`/
// `backdrop` fill is rendered through the image's opacity. Gradient takes precedence over color.
const applyImageOverlay = (
  el: HTMLElement,
  { image, gradient, color, overlayVar }: ApplyImageOverlayArgs
) => {
  let overlay: string | null = null;
  if (image) {
    if (image.overlay) {
      overlay =
        image.overlay.type === 'GRADIENT'
          ? schemaGradientToCss(image.overlay.gradient as Gradient)
          : (resolveDocumentColorToCss(image.overlay.color) ?? image.overlay.color);
    } else if (gradient) {
      overlay = schemaGradientToCss(gradient as Gradient);
    } else if (color) {
      overlay = resolveBackwardCompatOverlay(
        resolveDocumentColorToCss(color) ?? color,
        image.opacity ?? 100,
        100
      );
    }
  }
  setStyleVar(el, overlayVar, overlay);
};

const getGridTemplateColumns = (node: PmNode) => {
  const cols: number[] = [];

  node.content.forEach(cell => {
    if ((cell.type.name as unknown as Node_Type) === Node_Type.LAYOUT_CELL) {
      cols.push(cell.attrs.colSpan);
    }
  });

  return cols;
};

const formatGridTemplateColumns = (colSpans: number[]) => {
  return colSpans.map(col => `minmax(0, ${col}fr)`).join(' ');
};

type LayoutDragHandleProps = {
  breakoutWrapper: HTMLElement;
  layoutElement: HTMLElement;
  nodeId: string;
  editor: NodeViewRendererProps['editor'];
};

const createLayoutDragHandle = ({
  breakoutWrapper,
  layoutElement,
  nodeId,
  editor,
}: LayoutDragHandleProps): (() => void) => {
  // Create drag handle wrapper with contenteditable=false to prevent selection
  const layoutDragHandleWrapper = document.createElement('div');
  layoutDragHandleWrapper.setAttribute('contenteditable', 'false');
  layoutDragHandleWrapper.setAttribute('data-layout-drag-handle-wrapper', '');
  layoutDragHandleWrapper.classList.add(styles.layoutHandlerWrapper);

  // Create the drag handle button
  const layoutDragHandle = document.createElement('button');
  layoutDragHandle.setAttribute('data-drag-handle', '');
  layoutDragHandle.setAttribute('data-layout-handle', '');
  layoutDragHandle.setAttribute('data-hook', `${LAYOUT_HANDLE}-${nodeId}`);
  layoutDragHandle.setAttribute('type', 'button');
  layoutDragHandle.classList.add(styles.layoutHandler);
  layoutDragHandle.innerHTML = getMoveIcon();

  // Click handler for selecting layout
  const handleClick = () => {
    const layoutId = layoutElement.getAttribute('data-layout-container');
    if (layoutId) {
      editor.chain().selectLayout(layoutId).focus().run();
    }
  };

  layoutDragHandle.addEventListener('click', handleClick);
  layoutDragHandleWrapper.append(layoutDragHandle);
  breakoutWrapper.append(layoutDragHandleWrapper);

  // Return cleanup function
  return () => {
    layoutDragHandle.removeEventListener('click', handleClick);
    if (layoutDragHandleWrapper.parentNode === breakoutWrapper) {
      breakoutWrapper.removeChild(layoutDragHandleWrapper);
    }
  };
};

type VerticalMarginResizeHandlerProps = {
  layoutWrapper: HTMLElement;
  position: 'top' | 'bottom';
  minPadding: number;
  onResize: (newPadding: number) => void;
};

const createVerticalMarginResizeHandler = ({
  layoutWrapper,
  position,
  minPadding,
  onResize,
}: VerticalMarginResizeHandlerProps): (() => void) => {
  // Create the resize handle element
  const handle = document.createElement('div');
  handle.className = position === 'top' ? staticsStyles.handlerTop : staticsStyles.handlerBottom;
  handle.setAttribute('data-hook', `ricos-resize-handler-${position}`);

  // Ensure layoutWrapper has position: relative for absolute positioning
  const originalPosition = layoutWrapper.style.position;
  if (!originalPosition || originalPosition === 'static') {
    layoutWrapper.style.position = 'relative';
  }

  layoutWrapper.appendChild(handle);

  let startY = 0;
  let startPadding = 0;
  let currentPointerId: number | null = null;

  const removePointerListeners = () => {
    handle.removeEventListener('pointermove', handlePointerMove);
    handle.removeEventListener('pointerup', handlePointerUp);
    handle.removeEventListener('pointercancel', handlePointerUp);
    handle.removeEventListener('lostpointercapture', handleLostPointerCapture);
  };

  /**
   * End the resize: release capture, remove listeners, commit final padding, clear state.
   * When clientY is provided (normal pointerup), final padding is computed from delta.
   * When not provided (lostpointercapture or pointerId mismatch), padding is read from current computed style.
   */
  const finishResize = (clientY?: number) => {
    if (currentPointerId === null) {
      return;
    }

    if (handle.hasPointerCapture(currentPointerId)) {
      handle.releasePointerCapture(currentPointerId);
    }

    removePointerListeners();

    let newPadding: number;
    if (clientY !== undefined) {
      const deltaY = clientY - startY;
      const adjustedDelta = position === 'top' ? -deltaY : deltaY;
      newPadding = Math.round(
        Math.max(minPadding, Math.min(MAX_VERTICAL_MARGIN, startPadding + adjustedDelta * 0.55))
      );
    } else {
      const computedStyle = window.getComputedStyle(layoutWrapper);
      const paddingProp = position === 'top' ? 'paddingTop' : 'paddingBottom';
      const computed = parseInt(computedStyle[paddingProp], 10);
      newPadding = !isNaN(computed)
        ? Math.max(minPadding, Math.min(MAX_VERTICAL_MARGIN, computed))
        : minPadding;
    }

    layoutWrapper.style.setProperty(
      '--ricos-internal-layout-backdrop-padding-top',
      `${newPadding}px`
    );
    layoutWrapper.style.setProperty(
      '--ricos-internal-layout-backdrop-padding-bottom',
      `${newPadding}px`
    );

    onResize(newPadding);
    currentPointerId = null;
  };

  const handleLostPointerCapture = (event: PointerEvent) => {
    if (currentPointerId === null || event.pointerId !== currentPointerId) {
      return;
    }
    finishResize();
  };

  const handlePointerDown = (event: PointerEvent) => {
    if (event.button !== 0) {
      return;
    }
    event.preventDefault();
    event.stopPropagation();

    currentPointerId = event.pointerId;
    startY = event.clientY;

    // Read current padding from computed style - this always reflects the actual rendered value
    const computedStyle = window.getComputedStyle(layoutWrapper);
    const paddingProp = position === 'top' ? 'paddingTop' : 'paddingBottom';
    const computed = parseInt(computedStyle[paddingProp], 10);
    startPadding = !isNaN(computed) ? computed : 0;

    handle.setPointerCapture(event.pointerId);
    handle.addEventListener('pointermove', handlePointerMove);
    handle.addEventListener('pointerup', handlePointerUp);
    handle.addEventListener('pointercancel', handlePointerUp);
    handle.addEventListener('lostpointercapture', handleLostPointerCapture);
  };

  const handlePointerMove = (event: PointerEvent) => {
    if (currentPointerId === null || currentPointerId !== event.pointerId) {
      return;
    }

    const deltaY = event.clientY - startY;
    // For top handle, dragging up (negative deltaY) should increase padding
    // For bottom handle, dragging down (positive deltaY) should increase padding
    const adjustedDelta = position === 'top' ? -deltaY : deltaY;
    const newPadding = Math.round(
      Math.max(minPadding, Math.min(MAX_VERTICAL_MARGIN, startPadding + adjustedDelta * 0.55))
    );

    // Update visual feedback immediately via CSS variables (both top and bottom for linked margins)
    layoutWrapper.style.setProperty(
      '--ricos-internal-layout-backdrop-padding-top',
      `${newPadding}px`
    );
    layoutWrapper.style.setProperty(
      '--ricos-internal-layout-backdrop-padding-bottom',
      `${newPadding}px`
    );
  };

  const handlePointerUp = (event: PointerEvent) => {
    if (currentPointerId === null) {
      return;
    }
    if (currentPointerId !== event.pointerId) {
      // Mismatch: still clean up so we don't leave capture/listeners stuck
      finishResize();
      return;
    }

    finishResize(event.clientY);
  };

  handle.addEventListener('pointerdown', handlePointerDown);

  // Return cleanup function
  return () => {
    if (currentPointerId !== null && handle.hasPointerCapture(currentPointerId)) {
      handle.releasePointerCapture(currentPointerId);
    }
    removePointerListeners();
    handle.removeEventListener('pointerdown', handlePointerDown);

    if (handle.parentNode === layoutWrapper) {
      layoutWrapper.removeChild(handle);
    }

    if (!originalPosition || originalPosition === 'static') {
      layoutWrapper.style.position = originalPosition || '';
    }
  };
};

const isInLayout = ($pos: ResolvedPos, nodeId: string) => {
  const layoutNode = findParentNodeClosestToPos(
    $pos,
    node => node.type?.name === TIPTAP_LAYOUT_TYPE
  )?.node;

  return layoutNode?.attrs.id === nodeId;
};

const isCellInLayoutSelected = (
  $to: ResolvedPos,
  $from: ResolvedPos,
  layoutId: string,
  editor: NodeViewRendererProps['editor']
): boolean => {
  // Check if a cell node is selected (NodeSelection)
  const selection = editor.state.selection;
  if (!(selection instanceof NodeSelection)) {
    return false;
  }

  const selectedNode = selection.node;
  if (selectedNode?.type.name !== TIPTAP_LAYOUT_CELL_TYPE) {
    return false;
  }

  // Check if this cell belongs to this layout
  const layoutNode = findParentNodeClosestToPos(
    $from,
    node => node.type?.name === TIPTAP_LAYOUT_TYPE
  )?.node;

  return layoutNode?.attrs.id === layoutId;
};

const getCellParent = (node: ProseMirrorNode, cellId: string): ProseMirrorNode | null => {
  let parent: ProseMirrorNode | null = null;
  node.descendants((child, _pos, par) => {
    if (child.attrs.id === cellId) {
      parent = par;
    }
  });

  return parent;
};

const getCellIndex = (node: PmNode, cellId: string) => {
  let index = -1;

  node.content.forEach((cell, _offset, i) => {
    if (cell.attrs.id === cellId) {
      index = i;
    }
  });

  return index;
};

const isDraggingCell = (editor: NodeViewRendererProps['editor']) => {
  const slice = editor.view.dragging?.slice;

  if (!slice) {
    return false;
  }

  return (
    slice.openStart === 0 &&
    slice.openEnd === 0 &&
    slice.content.childCount === 1 &&
    editor.view.dragging?.slice.content.firstChild?.type.name === TIPTAP_LAYOUT_CELL_TYPE
  );
};

const attachCellResizeHandler = ({
  layoutElement,
  state,
  editor,
  setState,
}: Pick<NodeViewRendererProps, 'editor'> & {
  layoutElement: HTMLElement;
  state: LayoutNodeViewState;
  setState: (state: Partial<LayoutNodeViewState>) => void;
}) => {
  const onPointerDown = (event: PointerEvent) => {
    if (event.button !== 0) {
      return;
    }
    const dragHandle: HTMLElement | null = (event.target as HTMLElement)?.closest(
      '[data-layout-cell-resize-handle]'
    );

    if (!dragHandle || !event.currentTarget) {
      return;
    }

    const cellNodeId = dragHandle.dataset.layoutCellResizeHandle;

    if (!cellNodeId) {
      logInvariant(
        Error(
          'Cell resize prevented. No cell id found! Make sure to add the data-layout-cell-resize-handle attribute to the drag handle'
        )
      );
      return;
    }
    event.preventDefault();

    // Set resizing state immediately to hide the blue selection overlay
    setState({ isResizing: true });

    const layoutNode = getCellParent(editor.state.doc, cellNodeId);

    if (!layoutNode) {
      logInvariant(Error('Cell resize prevented. Draggable cell has no parent!'));
      return;
    }

    const index = getCellIndex(layoutNode, cellNodeId);
    const currentOffset = event.clientX;
    const parentRect = (event.currentTarget as HTMLElement).getBoundingClientRect();
    const fractionInPixels = parentRect.width / MAX_COLUMNS;
    const minColumnWidth = fractionInPixels * MIN_COL_SPAN;
    const columnTemplateInFractionsByPixel = state.columnTemplate.map(
      col => col * fractionInPixels
    );

    // Clear any existing selection when starting resize
    window.getSelection()?.removeAllRanges();

    // Prevent any selection from starting during resize
    const preventSelection = (e: Event) => {
      e.preventDefault();
    };
    document.addEventListener('selectstart', preventSelection);

    setState({
      columnTemplate: columnTemplateInFractionsByPixel,
      isResizing: true,
    });

    const onDrag = (event: PointerEvent) => {
      event.preventDefault();
      let invalid: 'none' | 'left' | 'right' = 'none';

      const offset = currentOffset - event.clientX;

      const newTemplate = [...columnTemplateInFractionsByPixel];
      newTemplate[index] = columnTemplateInFractionsByPixel[index] + offset;
      newTemplate[index - 1] = columnTemplateInFractionsByPixel[index - 1] - offset;

      if (newTemplate[index] < minColumnWidth) {
        const diff = minColumnWidth - newTemplate[index];
        newTemplate[index] = minColumnWidth;
        newTemplate[index - 1] -= diff;
        invalid = 'right';
      }

      if (newTemplate[index - 1] < minColumnWidth) {
        const diff = minColumnWidth - newTemplate[index - 1];
        newTemplate[index - 1] = minColumnWidth;
        newTemplate[index] -= diff;
        invalid = 'left';
      }

      if (newTemplate.some(col => col < minColumnWidth)) {
        setState({ invalid });
        return;
      }

      setState({
        columnTemplate: newTemplate,
        invalid,
      });
    };

    const stopDrag = (event: PointerEvent) => {
      event.preventDefault();

      // Remove selection prevention listener
      document.removeEventListener('selectstart', preventSelection);

      // Clear any text selection that occurred during resize
      window.getSelection()?.removeAllRanges();

      const templateInFractions = state.columnTemplate.map(col => {
        return Math.round(col / fractionInPixels);
      });

      const diff = MAX_COLUMNS - templateInFractions.reduce((acc, val) => acc + val, 0);
      templateInFractions[index] += diff;

      editor
        .chain()
        .setCellsColSpan(layoutNode.attrs.id, templateInFractions)
        .selectLayout(layoutNode.attrs.id)
        .focus()
        .run();

      setState({
        invalid: 'none',
        isResizing: false,
        columnTemplate: templateInFractions,
      });

      window.removeEventListener('pointerup', stopDrag);
      window.removeEventListener('pointermove', onDrag);
    };

    window.addEventListener('pointerup', stopDrag);
    window.addEventListener('pointermove', onDrag);
  };

  layoutElement.addEventListener('pointerdown', onPointerDown);

  return () => {
    layoutElement.removeEventListener('pointerdown', onPointerDown);
  };
};

const attachCellDragHandler = ({
  layoutElement,
  editor,
  setState,
}: Pick<NodeViewRendererProps, 'editor'> & {
  layoutElement: HTMLElement;
  setState: (state: Partial<LayoutNodeViewState>) => void;
}) => {
  const onDragStart = (event: DragEvent) => {
    const raw = event.target;
    const element = raw instanceof Element ? raw : raw instanceof Text ? raw.parentElement : null;
    if (!element) {
      return;
    }

    // if (element.closest('[data-layout-cell-content]')) {
    //   return;
    // }

    const cellElement = element.closest('[data-layout-cell]') as HTMLElement | null;
    const cellNodeId = cellElement?.getAttribute('data-layout-cell');
    if (!cellNodeId || !cellElement) {
      return;
    }

    // Drags from inner draggable nodes (buttons, images, etc.) bubble through here too.
    // Only treat this as a cell drag when the cell itself is the closest draggable element.
    const draggableAncestor = element.closest('[draggable="true"]');
    if (draggableAncestor !== cellElement) {
      return;
    }

    editor.commands.selectCell(cellNodeId);
    event.dataTransfer?.setDragImage(cellElement, 0, 0);

    // Capture the source layout now, while the cell is still inside it. When the
    // cell is dropped outside any layout it ends up orphaned; cell-normalizing
    // uses this to re-wrap it in a layout that keeps the source styling and to
    // remove the now-drained source layout. Keyed by layout id (preserved across
    // the drop) rather than cell id (regenerated on the card-paste path).
    const sourceLayout = findLayoutOfCell(editor.state.doc, cellNodeId);
    (editor.storage[TIPTAP_LAYOUT_TYPE] as LayoutExtensionStorage).draggedCellSourceLayout =
      sourceLayout
        ? {
            layoutId: sourceLayout.node.attrs.id,
            attrs: sourceLayout.node.attrs,
            // Only the source layout that held this cell *alone* should be removed
            // after the drop. A multi-cell source keeps its remaining cell(s).
            wasOnlyCell: sourceLayout.node.childCount === 1,
          }
        : null;
  };

  // This is heavily based on prosemirror-view `drop` event. We only need this because PM-View can't
  // handle position resolving for vertical content.
  // https://github.com/ProseMirror/prosemirror-view/blob/0954f523ee0a193f7db3992702e6a3979ade89b8/src/input.ts#L702
  const onDrop = (event: DragEvent) => {
    if (!isDraggingCell(editor) || !event.target) {
      return;
    }
    event.stopPropagation();
    setState({ dropCursorPosition: null, isDraggingOver: false });
    const view = editor.view;
    const dragging = view.dragging;
    const slice = dragging?.slice;
    view.dragging = null;

    if (!slice) {
      logInvariant(Error('Cell Drag prevented. PM view has no dragging slice'));
      return;
    }

    const sourceCell = slice.content.firstChild;
    const sourceCellId = sourceCell?.attrs.id;
    const eventPos = view.posAtDOM(event.target as HTMLElement, 0);
    const $eventPos = view.state.doc.resolve(eventPos);
    if (!eventPos || !sourceCellId) {
      logInvariant(Error('Cell Drag prevented. Cannot resolve event position or source cell id'));
      return;
    }

    const layoutNode = findParentNodeClosestToPos(
      $eventPos,
      node => node.type?.name === TIPTAP_LAYOUT_TYPE
    )?.node;

    if (!layoutNode) {
      logInvariant(Error('Cell Drag prevented. Cannot resolve target layout node'));
      return;
    }

    const cellIndexInSourceLayout = getCellIndex(layoutNode, sourceCellId);
    const isCellMovedToOtherLayout = cellIndexInSourceLayout === -1;
    if (layoutNode.childCount >= MAX_CELLS && isCellMovedToOtherLayout) {
      return;
    }

    const { node: cellNode, pos: cellPos } = findParentNodeClosestToPos(
      $eventPos,
      node => node.type?.name === TIPTAP_LAYOUT_CELL_TYPE
    ) ?? { node: null, pos: -1 };

    if (!cellNode || (layoutNode.childCount === 1 && layoutNode.firstChild === sourceCell)) {
      return;
    }

    const layout = event.currentTarget as HTMLElement;
    const layoutRect = layout.getBoundingClientRect();
    const cell = (event.target as HTMLElement).closest('[data-layout-cell]');

    if (!cell) {
      logInvariant(Error('Cell Drag prevented. Cannot find cell element'));
      return;
    }

    const mouseXInLayout = event.clientX - layoutRect.left;
    const cellRect = cell.getBoundingClientRect();

    const insertPos =
      mouseXInLayout < cellRect.left - layoutRect.left + cellRect.width / 2
        ? cellPos
        : cellPos + cellNode?.nodeSize;

    if (!insertPos) {
      logInvariant(Error('Cell Drag prevented. Cannot resolve insert position'));
      return;
    }

    event.preventDefault();

    const tr = view.state.tr;
    // @ts-expect-error
    const { node } = dragging;

    if (node) {
      node.replace(tr);
    } else {
      tr.deleteSelection();
    }

    const pos = tr.mapping.map(insertPos);
    const beforeInsert = tr.doc;

    if (!slice.content.firstChild) {
      return;
    }

    tr.replaceRangeWith(pos, pos, slice.content.firstChild);

    if (tr.doc.eq(beforeInsert)) {
      return;
    }

    const $pos = tr.doc.resolve(pos);

    tr.setSelection(new NodeSelection($pos));

    if (sourceCellId) {
      const sourceLayoutNode = findLayoutOfCell(view.state.doc, sourceCellId);
      if (sourceLayoutNode) {
        // If cell was moved to another layout, balance the cells in the source layout
        const sourceLayoutInNewTr = findNodeById(tr, sourceLayoutNode.node.attrs.id).pop();
        if (sourceLayoutInNewTr && isCellMovedToOtherLayout) {
          balanceLayoutCells(tr, sourceLayoutInNewTr.node, sourceLayoutInNewTr.pos);
        }
      }

      // If cell was moved to another layout, balance the cells in the target layout
      const targetLayoutNode = findLayoutOfCell(tr.doc, sourceCellId);
      if (targetLayoutNode && isCellMovedToOtherLayout) {
        balanceLayoutCells(tr, targetLayoutNode.node, targetLayoutNode.pos);
      }
    }

    view.focus();
    view.dispatch(tr);
  };

  const onDragOver = (event: DragEvent) => {
    setState({
      isDraggingOver: true,
    });

    if (!isDraggingCell(editor)) {
      return;
    }

    const layout = event.currentTarget as HTMLElement;
    const layoutWrapper = layout.closest('[data-layout-wrapper]');

    if (!layoutWrapper) {
      return;
    }

    const scale = getElementScale(layout);
    const layoutWrapperRect = layoutWrapper.getBoundingClientRect();
    const cellDropAreas = [...layout.querySelectorAll('[data-layout-cell]')].reduce(
      (acc, cell, index) => {
        const rect = cell.getBoundingClientRect();
        const prevCell = acc[acc.length - 1];
        const left = rect.left - layoutWrapperRect.left;
        return [
          ...acc,
          {
            left: index === 0 ? left : left - (left - prevCell.right) / 2,
            right: rect.right - layoutWrapperRect.left,
            width: rect.width,
          },
        ];
      },
      [] as { left: number; right: number; width: number }[]
    );
    const mouseXInLayout = event.clientX - layoutWrapperRect.left;
    const cellInsideIndex = cellDropAreas.findIndex(cell => {
      return mouseXInLayout > cell.left && mouseXInLayout < cell.right;
    });

    if (cellInsideIndex === -1) {
      return;
    }

    const cellInside = cellDropAreas[cellInsideIndex];
    const dropIndex =
      mouseXInLayout < cellInside.left + cellInside.width / 2
        ? cellInsideIndex
        : cellInsideIndex + 1;

    setState({
      dropCursorPosition:
        (dropIndex >= cellDropAreas.length
          ? cellDropAreas[cellDropAreas.length - 1].right
          : cellDropAreas[dropIndex].left) / scale.scaleX,
    });
  };

  const onDragLeave = (event: DragEvent) => {
    if ((event.currentTarget as HTMLElement).contains(event.relatedTarget as HTMLElement)) {
      return;
    }

    setState({
      dropCursorPosition: null,
      isDraggingOver: false,
    });
  };

  layoutElement.addEventListener('dragstart', onDragStart);
  layoutElement.addEventListener('drop', onDrop);
  layoutElement.addEventListener('dragover', onDragOver);
  layoutElement.addEventListener('dragleave', onDragLeave);

  return () => {
    layoutElement.removeEventListener('dragstart', onDragStart);
    layoutElement.removeEventListener('drop', onDrop);
    layoutElement.removeEventListener('dragover', onDragOver);
    layoutElement.removeEventListener('dragleave', onDragLeave);
  };
};

const attachLayoutEventHandlers = ({
  layoutWrapper,
  layoutElement,
  editor,
  setState,
}: Pick<NodeViewRendererProps, 'editor'> & {
  layoutWrapper: HTMLElement;
  layoutElement: HTMLElement;
  setState: (state: Partial<LayoutNodeViewState>) => void;
}) => {
  const onClick = (event: MouseEvent) => {
    const raw = event.target;
    const element = raw instanceof Element ? raw : raw instanceof Text ? raw.parentElement : null;
    if (
      element?.closest('[data-layout-cell]') ||
      element?.closest('[data-layout-drag-handle-wrapper]') ||
      element?.closest('[data-resize-handle]')
    ) {
      return;
    }
    const layoutId = layoutElement.getAttribute('data-layout-container');
    if (layoutId) {
      editor.chain().selectLayout(layoutId).focus().run();
    }
  };

  const onDragStart = (event: DragEvent) => {
    const raw = event.target;
    const element = raw instanceof Element ? raw : raw instanceof Text ? raw.parentElement : null;
    const cell = element?.closest('[data-layout-cell]');
    const layoutId = layoutElement.getAttribute('data-layout-container');

    if (cell) {
      return;
    }

    // Prevent dragging banner layouts - they should stay at their edge
    if (layoutWrapper.hasAttribute('data-layout-banner')) {
      event.preventDefault();
      return;
    }

    if (layoutId) {
      editor.commands.selectLayout(layoutId);
    }
    event.dataTransfer?.setDragImage(layoutElement, 0, 0);
    setState({ isDragging: true });

    const removeDragging = () => {
      setState({ isDragging: false });
      window.removeEventListener('pointerup', removeDragging);
    };

    window.addEventListener('pointerup', removeDragging);
  };

  layoutWrapper.addEventListener('click', onClick);
  layoutWrapper.addEventListener('dragstart', onDragStart);

  return () => {
    layoutWrapper.removeEventListener('click', onClick);
    layoutWrapper.removeEventListener('dragstart', onDragStart);
  };
};
