import {
  Box,
  Divider,
  FieldSet,
  FormField,
  IconButton,
  Input,
  Text,
  ToggleButton,
} from '@wix/design-system';
import {
  ChevronDownSmall,
  ChevronUpSmall,
  IndividualPaddingsSmall,
  LayoutSplitSmall,
  MoveSmall,
  PaddingBottomSmall,
  PaddingHorizontalSmall,
  PaddingLeftSmall,
  PaddingRightSmall,
  PaddingTopSmall,
  PaddingVerticalSmall,
  WrapSmall,
} from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { ZIndexContext } from './../../../ricos-context/index.js';
import { RicosContext } from './../../../ricos-context/ricos-context.js';
import type { LayoutData_ResponsivenessBehaviour } from './../../../ricos-schema/next-schema/index.js';
import type { LogBiFn } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import type { PmLayoutNode } from './../../../_shared/pm-node-types.js';
import { TogglesWithLabel } from './../../../_shared/toggles-with-label.js';
import {
  InputWithSlider,
  NumberInputWithLabel,
  usePanelContainerElement,
} from './../../../ui-components/index.js';

import {
  LAYOUT_SETTINGS_GAP,
  LAYOUT_SETTINGS_MODAL_ID,
  LAYOUT_SETTINGS_PADDING_BOTTOM,
  LAYOUT_SETTINGS_PADDING_HORIZONTAL,
  LAYOUT_SETTINGS_PADDING_LEFT,
  LAYOUT_SETTINGS_PADDING_RIGHT,
  LAYOUT_SETTINGS_PADDING_TOGGLE_INDIVIDUAL,
  LAYOUT_SETTINGS_PADDING_TOP,
  LAYOUT_SETTINGS_PADDING_VERTICAL,
  LAYOUT_SETTINGS_RESPONSIVENESS_BEHAVIOUR_STACK,
  LAYOUT_SETTINGS_RESPONSIVENESS_BEHAVIOUR_WRAP,
  LAYOUT_SETTINGS_RESPONSIVENESS_BREAKPOINT_INPUT,
  LAYOUT_SETTINGS_RESPONSIVENESS_HEADER_TOGGLE,
  LAYOUT_SETTINGS_VERTICAL_MARGIN,
  LAYOUT_SETTINGS_VERTICAL_MARGIN_BOTTOM,
  LAYOUT_SETTINGS_VERTICAL_MARGIN_TOGGLE_INDIVIDUAL,
  LAYOUT_SETTINGS_VERTICAL_MARGIN_TOP,
} from '../data-hooks.js';
import { LAYOUT_DEFAULTS, MAX_VERTICAL_MARGIN } from '../shared-with-viewer.js';

interface LayoutTabProps {
  pmNodeAttrs: PmLayoutNode['attrs'];
  patchPmNodeAttrs: (attrs: Partial<PmLayoutNode['attrs']>) => void;
  nodeId: string;
}

export const LayoutTab: FC<LayoutTabProps> = ({ pmNodeAttrs, patchPmNodeAttrs, nodeId }) => {
  const { t } = useContext(RicosContext);
  const [responsivenessExpanded, setResponsivenessExpanded] = useState(
    pmNodeAttrs.responsivenessBehaviour !== LAYOUT_DEFAULTS.responsivenessBehaviour ||
      pmNodeAttrs.responsivenessBreakpoint !== LAYOUT_DEFAULTS.responsivenessBreakpoint
  );

  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const containerEl = usePanelContainerElement();

  const logBi = useBiNext({ modalId: LAYOUT_SETTINGS_MODAL_ID, pluginId: 'layout', nodeId });
  const padding = pmNodeAttrs.cellPadding ?? [...LAYOUT_DEFAULTS.cellPadding];
  const onPaddingChange = (cellPadding: number[]) => {
    patchPmNodeAttrs({ cellPadding });
  };

  return (
    <Box direction="vertical" overflow="auto">
      <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
        <Box paddingBottom="SP1">
          <Text size="small" weight="bold">
            {t('Layout_SettingsModal_Tab_Layout_Spacing_Label')}
          </Text>
        </Box>

        <Box direction="vertical" gap="SP2">
          <FormField inputWidth="100%">
            <FieldSet
              alignment="center"
              legend={t('Layout_SettingsModal_Tab_Layout_Gaps_Label')}
              infoContent={t('Layout_SettingsModal_Tab_Layout_Gaps_Tooltip')}
              infoTooltipProps={{ appendTo: containerEl, zIndex }}
            >
              <Box direction="horizontal" paddingRight="SP1" width="50%">
                <InputWithSlider
                  value={pmNodeAttrs.gap ?? LAYOUT_DEFAULTS.gap}
                  dataHook={LAYOUT_SETTINGS_GAP}
                  onChange={value => {
                    logBi({ dataHook: LAYOUT_SETTINGS_GAP, value });
                    patchPmNodeAttrs({ gap: value });
                  }}
                  zIndex={zIndex}
                  prefix={
                    <Input.Affix>
                      <MoveSmall />
                    </Input.Affix>
                  }
                  suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                  min={0}
                  max={100}
                />
              </Box>
            </FieldSet>
          </FormField>

          <PaddingFieldWithLabel
            logBi={logBi}
            label={t('Layout_SettingsModal_Tab_Layout_Padding_Label')}
            infoContent={t('Layout_SettingsModal_Tab_Layout_Padding_Tooltip')}
            padding={padding}
            onChange={onPaddingChange}
          />

          <VerticalMarginWithLabel
            logBi={logBi}
            label={t('Layout_SettingsModal_Tab_Layout_VerticalMargin_Label')}
            infoContent={t('Layout_SettingsModal_Tab_Layout_VerticalMargin_Tooltip')}
            marginTop={pmNodeAttrs.backdropPaddingTop ?? LAYOUT_DEFAULTS.backdropPaddingTop}
            marginBottom={
              pmNodeAttrs.backdropPaddingBottom ?? LAYOUT_DEFAULTS.backdropPaddingBottom
            }
            isBanner={!!pmNodeAttrs.banner}
            onChange={(marginTop, marginBottom) => {
              patchPmNodeAttrs({
                backdropPaddingTop: marginTop,
                backdropPaddingBottom: marginBottom,
              });
            }}
          />
        </Box>
      </Box>

      <Divider />

      <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
        <Box
          paddingBottom={responsivenessExpanded ? 'SP1' : undefined}
          direction="horizontal"
          align="space-between"
          verticalAlign="middle"
        >
          <Text size="small" weight="bold">
            {t('Layout_SettingsModal_Tab_Layout_Responsivness_Label')}
          </Text>
          <IconButton
            size="small"
            skin="dark"
            priority="tertiary"
            onClick={() => {
              setResponsivenessExpanded(prev => !prev);
              logBi({
                dataHook: LAYOUT_SETTINGS_RESPONSIVENESS_HEADER_TOGGLE,
                value: !responsivenessExpanded,
              });
            }}
            dataHook={LAYOUT_SETTINGS_RESPONSIVENESS_HEADER_TOGGLE}
          >
            {responsivenessExpanded ? <ChevronUpSmall /> : <ChevronDownSmall />}
          </IconButton>
        </Box>

        {responsivenessExpanded && (
          <>
            <TogglesWithLabel<LayoutData_ResponsivenessBehaviour>
              label={t('Layout_SettingsModal_Tab_Layout_Responsivness_Behaviour_Label')}
              infoContent={t('Layout_SettingsModal_Tab_Layout_Responsivness_Behaviour_Tooltip')}
              value={pmNodeAttrs.responsivenessBehaviour || LAYOUT_DEFAULTS.responsivenessBehaviour}
              options={[
                {
                  label: t('Layout_SettingsModal_Tab_Layout_Responsivness_Behaviour_Stack'),
                  value: 'STACK',
                  icon: <LayoutSplitSmall height="100%" />,
                  dataHook: LAYOUT_SETTINGS_RESPONSIVENESS_BEHAVIOUR_STACK,
                },
                {
                  label: t('Layout_SettingsModal_Tab_Layout_Responsivness_Behaviour_Wrap'),
                  value: 'WRAP',
                  icon: <WrapSmall height="100%" />,
                  dataHook: LAYOUT_SETTINGS_RESPONSIVENESS_BEHAVIOUR_WRAP,
                },
              ]}
              onChange={value => patchPmNodeAttrs({ responsivenessBehaviour: value })}
            />

            <NumberInputWithLabel
              label={t('Layout_SettingsModal_Tab_Layout_Responsivness_Breakpoint_Label')}
              infoContent={t('Layout_SettingsModal_Tab_Layout_Responsivness_Breakpoint_Tooltip')}
              dataHook={LAYOUT_SETTINGS_RESPONSIVENESS_BREAKPOINT_INPUT}
              suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
              value={
                pmNodeAttrs.responsivenessBreakpoint ?? LAYOUT_DEFAULTS.responsivenessBreakpoint
              }
              min={0}
              max={1200}
              onChange={value => patchPmNodeAttrs({ responsivenessBreakpoint: value })}
              logBi={logBi}
              zIndex={zIndex}
              tooltipAppendTo={containerEl}
            />
          </>
        )}
      </Box>
    </Box>
  );
};

type VerticalMarginFieldWithLabelProps = {
  logBi: LogBiFn;
  label: string;
  infoContent: string;
  marginTop: number;
  marginBottom: number;
  isBanner?: boolean;
  onChange: (marginTop: number, marginBottom: number) => void;
};

const VerticalMarginWithLabel: React.FC<VerticalMarginFieldWithLabelProps> = ({
  logBi,
  label,
  infoContent,
  marginTop,
  marginBottom,
  isBanner = false,
  onChange,
}) => {
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const containerEl = usePanelContainerElement();

  // For banners, always use directional mode (both margins change together)
  const [mode, setMode] = useState<'individual' | 'directional'>(() => {
    if (isBanner || marginTop === marginBottom) {
      return 'directional';
    }
    return 'individual';
  });

  // Force directional mode for banners
  const effectiveMode = isBanner ? 'directional' : mode;

  return (
    <Box direction="vertical">
      <FormField inputWidth="100%">
        <FieldSet
          alignment="center"
          legend={label}
          infoContent={infoContent}
          infoTooltipProps={{ appendTo: containerEl, zIndex }}
          suffix={
            // Hide toggle button for banner layouts - they always use directional mode
            isBanner ? undefined : (
              <Box width="24px" height="24px" align="center" verticalAlign="middle">
                <ToggleButton
                  border
                  labelValue={t(
                    'Layout_SettingsModal_Tab_Layout_VerticalMargin_ToggleInidividual_Tooltip'
                  )}
                  size="tiny"
                  tooltipProps={{ appendTo: containerEl, zIndex }}
                  selected={mode === 'individual'}
                  onClick={() => {
                    setMode(() => (mode === 'individual' ? 'directional' : 'individual'));
                    logBi({
                      dataHook: LAYOUT_SETTINGS_VERTICAL_MARGIN_TOGGLE_INDIVIDUAL,
                      value: mode === 'individual' ? 'directional' : 'individual',
                    });
                    if (mode === 'individual') {
                      onChange(marginTop, marginTop);
                    }
                  }}
                  dataHook={LAYOUT_SETTINGS_VERTICAL_MARGIN_TOGGLE_INDIVIDUAL}
                >
                  <IndividualPaddingsSmall />
                </ToggleButton>
              </Box>
            )
          }
        >
          {(() => {
            switch (effectiveMode) {
              case 'individual':
                return (
                  <Box direction="horizontal" gap="SP2">
                    <InputWithSlider
                      value={marginTop}
                      onChange={value => {
                        onChange(value, marginBottom);
                        logBi({
                          dataHook: LAYOUT_SETTINGS_VERTICAL_MARGIN_TOP,
                          value,
                        });
                      }}
                      dataHook={LAYOUT_SETTINGS_VERTICAL_MARGIN_TOP}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingTopSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={MAX_VERTICAL_MARGIN}
                    />
                    <InputWithSlider
                      value={marginBottom}
                      onChange={value => {
                        onChange(marginTop, value);
                        logBi({
                          dataHook: LAYOUT_SETTINGS_VERTICAL_MARGIN_BOTTOM,
                          value,
                        });
                      }}
                      dataHook={LAYOUT_SETTINGS_VERTICAL_MARGIN_BOTTOM}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingBottomSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={MAX_VERTICAL_MARGIN}
                    />
                  </Box>
                );
              case 'directional':
                return (
                  <Box direction="horizontal" paddingRight="SP1" width="50%">
                    <InputWithSlider
                      value={marginTop}
                      onChange={value => {
                        onChange(value, value);
                        logBi({
                          dataHook: LAYOUT_SETTINGS_VERTICAL_MARGIN,
                          value,
                        });
                      }}
                      dataHook={LAYOUT_SETTINGS_VERTICAL_MARGIN}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingVerticalSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={MAX_VERTICAL_MARGIN}
                    />
                  </Box>
                );
              default:
                return null;
            }
          })()}
        </FieldSet>
      </FormField>
    </Box>
  );
};

type PaddingFieldWithLabelProps = {
  logBi: LogBiFn;
  label: string;
  infoContent: string;
  padding: number[];
  onChange: (padding: number[]) => void;
};

const PaddingFieldWithLabel: React.FC<PaddingFieldWithLabelProps> = ({
  logBi,
  label,
  infoContent,
  padding,
  onChange,
}) => {
  const { t } = useContext(RicosContext);
  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const containerEl = usePanelContainerElement();

  const paddingTop = padding[0];
  const paddingRight = padding[1];
  const paddingBottom = padding[2];
  const paddingLeft = padding[3];

  const [mode, setMode] = useState<'individual' | 'directional'>(() => {
    if (paddingLeft === paddingRight && paddingTop === paddingBottom) {
      return 'directional';
    }
    return 'individual';
  });

  return (
    <Box direction="vertical">
      <FormField inputWidth="100%">
        <FieldSet
          alignment="center"
          legend={label}
          infoContent={infoContent}
          infoTooltipProps={{ appendTo: containerEl, zIndex }}
          suffix={
            <Box width="24px" height="24px" align="center" verticalAlign="middle">
              <ToggleButton
                border
                labelValue={t('Layout_SettingsModal_Tab_Layout_Padding_ToggleIndividual')}
                size="tiny"
                tooltipProps={{ appendTo: containerEl, zIndex }}
                selected={mode === 'individual'}
                onClick={() => {
                  setMode(() => (mode === 'individual' ? 'directional' : 'individual'));
                  logBi({
                    dataHook: LAYOUT_SETTINGS_PADDING_TOGGLE_INDIVIDUAL,
                    value: mode === 'individual' ? 'directional' : 'individual',
                  });
                  if (mode === 'individual') {
                    onChange([paddingTop, paddingLeft, paddingTop, paddingLeft]);
                  }
                }}
                dataHook={LAYOUT_SETTINGS_PADDING_TOGGLE_INDIVIDUAL}
              >
                <IndividualPaddingsSmall />
              </ToggleButton>
            </Box>
          }
        >
          {(() => {
            switch (mode) {
              case 'individual':
                return (
                  <Box direction="vertical" gap="SP1">
                    <Box direction="horizontal" gap="SP2">
                      <InputWithSlider
                        value={paddingLeft}
                        onChange={value => {
                          onChange([paddingTop, paddingRight, paddingBottom, value]);
                          logBi({
                            dataHook: LAYOUT_SETTINGS_PADDING_LEFT,
                            value,
                          });
                        }}
                        dataHook={LAYOUT_SETTINGS_PADDING_LEFT}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingLeftSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                      <InputWithSlider
                        value={paddingTop}
                        onChange={value => {
                          onChange([value, paddingRight, paddingBottom, paddingLeft]);
                          logBi({
                            dataHook: LAYOUT_SETTINGS_PADDING_TOP,
                            value,
                          });
                        }}
                        dataHook={LAYOUT_SETTINGS_PADDING_TOP}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingTopSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                    </Box>
                    <Box direction="horizontal" gap="SP2">
                      <InputWithSlider
                        value={paddingRight}
                        onChange={value => {
                          onChange([paddingTop, value, paddingBottom, paddingLeft]);
                          logBi({
                            dataHook: LAYOUT_SETTINGS_PADDING_RIGHT,
                            value,
                          });
                        }}
                        dataHook={LAYOUT_SETTINGS_PADDING_RIGHT}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingRightSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                      <InputWithSlider
                        value={paddingBottom}
                        onChange={value => {
                          onChange([paddingTop, paddingRight, value, paddingLeft]);
                          logBi({
                            dataHook: LAYOUT_SETTINGS_PADDING_BOTTOM,
                            value,
                          });
                        }}
                        dataHook={LAYOUT_SETTINGS_PADDING_BOTTOM}
                        zIndex={zIndex}
                        prefix={
                          <Input.Affix>
                            <PaddingBottomSmall />
                          </Input.Affix>
                        }
                        suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                        min={0}
                        max={100}
                      />
                    </Box>
                  </Box>
                );
              case 'directional':
                return (
                  <Box direction="horizontal" gap="SP2">
                    <InputWithSlider
                      value={paddingLeft}
                      onChange={value => {
                        onChange([paddingTop, value, paddingTop, value]);
                        logBi({
                          dataHook: LAYOUT_SETTINGS_PADDING_HORIZONTAL,
                          value,
                        });
                      }}
                      dataHook={LAYOUT_SETTINGS_PADDING_HORIZONTAL}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingHorizontalSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={100}
                    />
                    <InputWithSlider
                      value={paddingTop}
                      onChange={value => {
                        onChange([value, paddingRight, value, paddingRight]);
                        logBi({
                          dataHook: LAYOUT_SETTINGS_PADDING_VERTICAL,
                          value,
                        });
                      }}
                      dataHook={LAYOUT_SETTINGS_PADDING_VERTICAL}
                      zIndex={zIndex}
                      prefix={
                        <Input.Affix>
                          <PaddingVerticalSmall />
                        </Input.Affix>
                      }
                      suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
                      min={0}
                      max={100}
                    />
                  </Box>
                );
              default:
                return null;
            }
          })()}
        </FieldSet>
      </FormField>
    </Box>
  );
};
