import type { ImageComponentData, RICOS_LAYOUT_TYPE } from './../../ricos-content/index.js';
import type { PluginServices } from './../../ricos-plugins/editor-plugins.js';
import type { BackgroundImage } from './../../ricos-schema/next-schema/index.js';
import type { PublicCommands } from './../../ricos-types/index.js';
import { logInvariant } from './../../_shared/log-invariant.js';
import { createImageFileSelectionFn } from './../../_shared/media-manager/create-image-file-selection-fn.js';
import type { PickMediaFn } from './../../_shared/media/pick-media.js';
import type { PickMediaImageData, PublicPickMedia } from './../../_shared/media/public-pick-media.js';
import type { PmLayoutNode } from './../../_shared/pm-node-types.js';
import { upload } from './../../_shared/upload/upload.js';

import type { LayoutEditorConfig } from './shared.js';

export const getImagePickMedia = ({
  services,
  config,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'editorProps' | 'wixInstance' | 'modals'
  >;
  config: LayoutEditorConfig;
}): PickMediaFn | PublicPickMedia['pickImage'] => {
  const { handleFileUpload } = config;
  const editorPickMedia = services.editorProps.pickMedia?.pickImage;
  const devPickMedia = services.devService().pickMedia;
  const handleFileSelection =
    services.devService().handleFileSelection ??
    config.handleFileSelection ??
    createImageFileSelectionFn(services);

  return devPickMedia
    ? devPickMedia
    : editorPickMedia
      ? editorPickMedia
      : handleFileSelection
        ? async () => {
            try {
              const data = await new Promise<ImageComponentData>((resolve, reject) =>
                handleFileSelection(
                  ({ data }) => resolve(Array.isArray(data) ? data[0] : data),
                  {
                    multiple: false,
                  },
                  reject
                )
              );
              return { type: 'ready-media' as const, media: [data] };
            } catch {
              return { type: 'cancel' as const };
            }
          }
        : async ({ mimeType }: { mimeType: string }) => {
            const files =
              (await services.uploadService?.selectFiles({ accept: mimeType, multiple: false })) ??
              [];
            return { type: 'file' as const, file: files, customUploadFn: handleFileUpload };
          };
};

type BackgroundAttributeKeys<T> = {
  [K in keyof Required<T>]: Required<T>[K] extends BackgroundImage ? K : never;
}[keyof Required<T>];

const getLayoutAttributes = <
  T extends PmLayoutNode['attrs'],
  A extends BackgroundAttributeKeys<T>,
>({
  uploadData,
  componentData,
  attributeKey,
}: {
  componentData: T;
  uploadData: ImageComponentData | PickMediaImageData;
  attributeKey: A;
}) => {
  const backgroundImage = componentData?.[attributeKey] as BackgroundImage;
  return {
    ...componentData,
    [attributeKey]: {
      ...backgroundImage,
      media: {
        src: 'src' in uploadData ? uploadData.src : { id: uploadData.file_name },
        width: uploadData.width,
        height: uploadData.height,
      },
      opacity: backgroundImage?.opacity ?? 100,
      scaling: backgroundImage?.scaling ?? 'COVER',
      position: backgroundImage?.position ?? 'CENTER',
    },
    loading: componentData.loading
      ? { ...componentData.loading, [attributeKey]: false }
      : undefined,
  } satisfies T;
};

export const handleLayoutImageUpload = async <
  NT extends typeof RICOS_LAYOUT_TYPE,
  PT extends PmLayoutNode['attrs'],
  A extends BackgroundAttributeKeys<PT>,
>({
  services,
  config,
  publicCommands,
  nodeId,
  nodeType,
  attributeKey,
}: {
  services: Pick<
    PluginServices,
    'devService' | 'uploadService' | 'editorProps' | 'wixInstance' | 'modals'
  >;
  config: LayoutEditorConfig;
  publicCommands: PublicCommands;
  nodeId: string;
  nodeType: NT;
  attributeKey: A;
}) => {
  const mimeType = 'image/*';
  const pickMedia = getImagePickMedia({ services, config });

  const result = await pickMedia({ mimeType, multiple: false });

  switch (result.type) {
    case 'ready-media': {
      const data = result.media[0] as ImageComponentData | PickMediaImageData;
      const componentData: PT = publicCommands?.getBlockComponentData(nodeId);
      const updatedData = getLayoutAttributes({
        componentData,
        uploadData: data,
        attributeKey,
      });

      publicCommands?.setBlock(nodeId, nodeType, {
        ...updatedData,
        loading: componentData.loading
          ? { ...componentData.loading, [attributeKey]: false }
          : undefined,
      });
      return;
    }
    case 'file': {
      const file = result.file[0];
      if (file) {
        const trackBi = services.uploadService?.trackUploadBi(nodeType, file.size, file.name);

        try {
          const url = URL.createObjectURL(file);
          await Promise.resolve();
          const componentData = publicCommands?.getBlockComponentData(nodeId);

          publicCommands?.setBlock(nodeId, nodeType, {
            ...componentData,
            loading: componentData.loading
              ? { ...componentData.loading, [attributeKey]: true }
              : { [attributeKey]: true },
          });

          trackBi?.start();
          const uploadFn = result.customUploadFn || config.handleFileUpload;

          if (!uploadFn) {
            logInvariant(Error('No upload function provided'));
            throw new Error('No upload function provided');
          }

          const uploadedFile = await upload(uploadFn, file);

          const updatedData = getLayoutAttributes({
            componentData: publicCommands?.getBlockComponentData(nodeId) as PT,
            uploadData: uploadedFile.data as any,
            attributeKey,
          });

          publicCommands?.setBlock(nodeId, nodeType, updatedData);

          URL.revokeObjectURL(url as string);
          trackBi?.success();
        } catch (error: any) {
          const componentData = publicCommands?.getBlockComponentData(nodeId);
          publicCommands?.setBlock(nodeId, nodeType, {
            ...componentData,
            error,
            loading: componentData.loading
              ? { ...componentData.loading, [attributeKey]: false }
              : undefined,
          });

          trackBi?.error(error);
          services.uploadService?.notifyError(error);
        }
      } else {
        console.error('No file selected');
      }
      return;
    }
    case 'cancel': {
      services.modals.notifyExternalModalClosed();
      return;
    }
    default: {
      console.error('Unhandeled media picker result:', result);
      return;
    }
  }
};
