import { Box, Divider, Text, Thumbnail } from '@wix/design-system';
import React, { useContext } from 'react';

import { useConverters } from './../../../pm-converters/context.js';
import { RICOS_LAYOUT_TYPE } from './../../../ricos-content/index.js';
import { EditorContext, ModalServiceContext, RicosContext } from './../../../ricos-context/index.js';
import type { RicosDocument } from './../../../ricos-schema/next-schema/index.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { Panel, PanelHeader } from './../../../ui-components/index.js';

import {
  INSERT_LAYOUT_MODAL,
  INSERT_LAYOUT_MODAL_PRESET,
  INSERT_LAYOUT_MODAL_THREE_COLUMNS,
  INSERT_LAYOUT_MODAL_TWO_COLUMNS,
} from '../data-hooks.js';
import { convertPresetToLayoutData, createBlankLayoutData } from '../shared.js';
import { ThreeColumns } from './icons/three-columns.js';
import { TwoColumns } from './icons/two-columns.js';
import { createLayoutPresetContent } from './presets/create-layout-preset-content.js';

export const LAYOUT_INSERT_MODAL_ID = 'layout-insert-modal';

const usePresets = () => {
  const { t } = React.useContext(RicosContext);

  return React.useMemo(() => createLayoutPresetContent(t), [t]);
};

export const LayoutInsertModal: React.FC = () => {
  const { t, isMobile } = React.useContext(RicosContext);
  const { getPublicCommands } = useContext(EditorContext);
  const modalService = React.useContext(ModalServiceContext) || {};
  const converters = useConverters();
  const presets = usePresets();
  const logBi = useBiNext({ pluginId: 'layout', modalId: LAYOUT_INSERT_MODAL_ID });

  const closeModal = () => modalService.closeModal(LAYOUT_INSERT_MODAL_ID);

  const onLayoutSelected = (colCount: number) => {
    getPublicCommands().insertBlockWithBlankLines(
      RICOS_LAYOUT_TYPE,
      createBlankLayoutData(colCount),
      { updateSelection: 'text', skipBlankLineBefore: false, skipBlankLineAfter: false }
    );
    closeModal();
  };

  const onPresetSelected = (content: RicosDocument) => {
    const data = convertPresetToLayoutData(content, converters);
    if (data) {
      getPublicCommands().insertBlockWithBlankLines(RICOS_LAYOUT_TYPE, data, {
        updateSelection: 'text',
      });
    }
    closeModal();
  };

  return (
    <Panel
      dataHook={INSERT_LAYOUT_MODAL}
      closeButtonProps={{ onClick: closeModal }}
      height="fit-content"
      width={isMobile ? undefined : '300px'}
      maxHeight={576}
    >
      <PanelHeader title={t('Layout_InsertModal_Header_Title')} />

      <Box overflowY="auto" direction="vertical">
        <Box
          direction="vertical"
          paddingTop="SP4"
          paddingBottom="SP4"
          paddingLeft="SP4"
          paddingRight="SP4"
        >
          <Box paddingBottom="SP4">
            <Text size="small" weight="bold">
              {t('Layout_InsertModal_Section_Blank')}
            </Text>
          </Box>

          <Box direction="horizontal" align="space-between">
            <LayoutThumbnail
              title={t('Layout_InsertModal_2Columns')}
              aria-label={t('Layout_InsertModal_2Columns')}
              dataHook={INSERT_LAYOUT_MODAL_TWO_COLUMNS}
              image={<TwoColumns />}
              onClick={() => {
                logBi({ dataHook: INSERT_LAYOUT_MODAL_TWO_COLUMNS });
                onLayoutSelected(2);
              }}
            />
            <LayoutThumbnail
              title={t('Layout_InsertModal_3Columns')}
              aria-label={t('Layout_InsertModal_3Columns')}
              dataHook={INSERT_LAYOUT_MODAL_THREE_COLUMNS}
              image={<ThreeColumns />}
              onClick={() => {
                logBi({ dataHook: INSERT_LAYOUT_MODAL_THREE_COLUMNS });
                onLayoutSelected(3);
              }}
            />
          </Box>
        </Box>

        <Divider />

        <Box
          direction="vertical"
          paddingTop="SP4"
          paddingBottom="SP4"
          paddingLeft="SP4"
          paddingRight="SP4"
        >
          <Box paddingBottom="SP4">
            <Text size="small" weight="bold">
              {t('Layout_InsertModal_Section_Presets')}
            </Text>
          </Box>

          <Box direction="horizontal" align="space-between" flexWrap="wrap">
            {presets.map(({ id, image, createContentFn }) => (
              <LayoutThumbnail
                key={id}
                dataHook={INSERT_LAYOUT_MODAL_PRESET}
                image={image}
                onClick={() => {
                  logBi({ dataHook: INSERT_LAYOUT_MODAL_PRESET, value: id });
                  if (createContentFn) {
                    onPresetSelected(createContentFn());
                  }
                }}
              />
            ))}
          </Box>
        </Box>
      </Box>
    </Panel>
  );
};

const LayoutThumbnail: React.FC<React.ComponentProps<typeof Thumbnail>> = props => {
  return (
    <Thumbnail
      height={120}
      width={117}
      size="tiny"
      contentAlignment="center"
      textPosition="outside"
      {...props}
    />
  );
};
