import { TIPTAP_LAYOUT_CELL_TYPE, TIPTAP_LAYOUT_TYPE, generateId } from './../../ricos-content/index.js';
import { TOP_LEVEL_NODES } from './../../_shared/top-level-nodes.js';
import type { EditorState } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey, TextSelection } from './../../tiptap/pm/state.js';
import { findWrapping } from './../../tiptap/pm/transform.js';
import type { Editor } from './../../tiptap/react/index.js';

import { LAYOUT_DEFAULTS, MAX_COLUMNS, MIN_COL_SPAN } from './shared-with-viewer.js';
import type { LayoutExtensionStorage } from './shared.js';
import { balanceLayoutCells } from './shared.js';

// A LAYOUT only ever sits directly under the doc or a card wrapper (CARD /
// CARD_HEADER / CARD_CONTENT / CARD_FOOTER) and never nests inside another
// layout. So when hunting for layouts we only need to descend into those
// wrappers — pruning everything else keeps the walk off the whole (text-heavy)
// content subtree on every transaction.
const canContainLayout = (typeName: string): boolean =>
  (TOP_LEVEL_NODES as readonly string[]).includes(typeName);

export const createCellNormalizingTransactionPlugin = (editor: Editor) => {
  return new Plugin({
    key: new PluginKey('normalize-cell'),
    appendTransaction: (_, oldState: EditorState, newState: EditorState) => {
      if (newState.doc.eq(oldState.doc) && newState.selection.eq(oldState.selection)) {
        return;
      }

      const tr = newState.tr;

      const storage = editor.storage[TIPTAP_LAYOUT_TYPE] as LayoutExtensionStorage | undefined;
      const draggedSource = storage?.draggedCellSourceLayout ?? null;

      // Collect the layouts to remove first, then delete from last to first so
      // earlier positions stay valid (deleting in-iteration would shift them).
      // A plain top-level `forEach` would miss layouts nested inside a card, so
      // we descend — but only into the wrappers that can hold a layout (see
      // `canContainLayout`), pruning the rest of the tree.
      const layoutsToRemove: { from: number; to: number }[] = [];
      tr.doc.descendants((node, pos) => {
        if (node.type.name !== TIPTAP_LAYOUT_TYPE) {
          // Keep descending only through doc/card wrappers; prune everything else.
          return canContainLayout(node.type.name);
        }
        // Transient empty layout: a single cell with no children at all.
        const isTransientEmpty = node.childCount === 1 && node.firstChild?.childCount === 0;
        // Drained drag source: the layout whose *only* cell was just dragged out.
        // PM refills it with an empty cell to satisfy its `cell{1,6}` schema, so
        // `isTransientEmpty` misses it — match it by id and drop it once it holds
        // no text. Gated on `wasOnlyCell`: a multi-cell source keeps its remaining
        // cell(s) (whose empty paragraphs would otherwise read as "no text").
        const isDrainedDragSource =
          draggedSource !== null &&
          draggedSource.wasOnlyCell &&
          node.attrs.id === draggedSource.layoutId &&
          node.textContent.length === 0;
        if (isTransientEmpty || isDrainedDragSource) {
          layoutsToRemove.push({ from: pos, to: pos + node.nodeSize });
        }
        // Layouts never nest, so there's nothing layout-shaped deeper to find.
        return false;
      });
      for (let i = layoutsToRemove.length - 1; i >= 0; i--) {
        tr.deleteRange(layoutsToRemove[i].from, layoutsToRemove[i].to);
      }

      // `descendants` walks a snapshot of the doc taken now, but the branches
      // below mutate `tr` (wrap/insert) and so shift the live document. Map
      // each snapshot position through the steps added since this point before
      // using it, otherwise later positions go stale and `setNodeAttribute`
      // throws "No node at attribute step's position" (e.g. when a single drop
      // requires several fixups in one pass).
      const baseStep = tr.mapping.maps.length;
      const mapPos = (pos: number) => tr.mapping.slice(baseStep).map(pos);

      tr.doc.descendants((node, pos, parent) => {
        // All CELLS must be wrapped in a LAYOUT
        if (
          node.type.name === TIPTAP_LAYOUT_CELL_TYPE &&
          parent?.type.name !== TIPTAP_LAYOUT_TYPE
        ) {
          const $from = tr.doc.resolve(mapPos(pos));
          const $to = tr.doc.resolve(mapPos(pos + node.nodeSize));
          const nodeRange = $from.blockRange($to);

          // A cell dropped outside any layout carries the styling of the layout
          // it was dragged out of (captured at drag start). Re-wrap it with those
          // attrs; otherwise seed from the shared defaults — the node spec
          // defaults every styling attr to null, so wrapping with only an id
          // would yield an unstyled layout (no gap/padding/alignment).
          //
          // An orphaned cell only ever appears via a cell drag-out, so applying
          // the pending source attrs to it (without matching ids — they may have
          // been regenerated by card-paste) is safe.
          const layoutAttrs = draggedSource
            ? // `banner` is reset: a banner is a unique full-width layout, so a
              // dragged-out cell must not become a second one.
              { ...draggedSource.attrs, banner: null, id: generateId() }
            : {
                ...LAYOUT_DEFAULTS,
                cellPadding: [...LAYOUT_DEFAULTS.cellPadding],
                id: generateId(),
              };

          const wrapping =
            nodeRange &&
            findWrapping(nodeRange, newState.schema.nodes[TIPTAP_LAYOUT_TYPE], layoutAttrs);

          if (!wrapping) {
            return;
          }

          tr.wrap(nodeRange, wrapping);
        }

        // All CELLS must have valid colSpan
        if (
          node.type.name === TIPTAP_LAYOUT_CELL_TYPE &&
          parent?.type.name === TIPTAP_LAYOUT_TYPE &&
          node.attrs.colSpan === null
        ) {
          const colSpans: number[] = [];
          parent.content.forEach(child => colSpans.push(child.attrs.colSpan ?? 0));
          const totalColSpan = colSpans.reduce((acc, curr) => acc + curr, 0);
          const remainingColumns = MAX_COLUMNS - totalColSpan;

          tr.setNodeAttribute(mapPos(pos), 'colSpan', remainingColumns);
        }

        // All empty CELLS must have an empty paragraph
        if (
          node.type.name === TIPTAP_LAYOUT_CELL_TYPE &&
          parent?.type.name === TIPTAP_LAYOUT_TYPE &&
          node.childCount === 0
        ) {
          const paragraphNode = newState.schema.nodes.PARAGRAPH.create({
            id: generateId(),
          });
          const insertPos = mapPos(pos) + 1;
          tr.insert(insertPos, paragraphNode);
          const textPos = insertPos + 1;
          tr.setSelection(TextSelection.create(tr.doc, textPos));
        }
      });

      tr.doc.forEach((node, pos) => {
        // All CELLS must not exceed the maximum number of columns
        if (node.type.name === TIPTAP_LAYOUT_TYPE) {
          const colSpans: number[] = [];
          node.content.forEach(child => colSpans.push(child.attrs.colSpan ?? 0));
          const allColSpansValid = colSpans.every(colSpan => colSpan >= MIN_COL_SPAN);
          const colSpansSum = colSpans.reduce((acc, curr) => acc + curr, 0);

          if (colSpansSum !== MAX_COLUMNS || !allColSpansValid) {
            balanceLayoutCells(tr, node, pos);
          }
        }
      });

      // The drop is a doc-changing transaction; once it has been normalized the
      // captured source layout has served its purpose. Clear it so a later,
      // unrelated orphaned cell can't inherit stale styling. Selection-only
      // transactions (e.g. selectCell during dragstart) leave the doc unchanged
      // and keep the capture alive until the actual drop.
      if (draggedSource && storage && !newState.doc.eq(oldState.doc)) {
        storage.draggedCellSourceLayout = null;
      }

      return tr;
    },
  });
};
