import { TIPTAP_LAYOUT_CELL_TYPE, TIPTAP_LAYOUT_TYPE } from './../../ricos-content/index.js';
import { findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { NodeSelection, Selection } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';
import { Decoration, DecorationSet } from './../../tiptap/pm/view.js';

export const layoutSelectionDecorationPlugin = () => {
  return new Plugin({
    key: new PluginKey('layout-selection-decoration'),
    props: {
      decorations(state) {
        const { $from, $to } = state.selection;
        const layoutNode = findParentNodeClosestToPos(
          $from,
          node => node.type?.name === TIPTAP_LAYOUT_TYPE
        )?.node;
        const decorations: Decoration[] = [];

        // We don't really care what decoration to set here. This is needed only because PM doesn't
        // trigger `update` for node views on selection change as it thinks nothing changed. Adding
        // decorations for helps to force it.
        state.doc.forEach((node, pos) => {
          if (node === layoutNode) {
            decorations.push(
              Decoration.node(pos, pos + node.nodeSize, {
                'data-layout-selection': '',
              })
            );
          }
        });

        if (
          isNodeSelection(state.selection) &&
          state.selection.node.type.name === TIPTAP_LAYOUT_CELL_TYPE
        ) {
          decorations.push(
            Decoration.node($from.pos, $to.pos, {
              'data-layout-cell-selection': '',
            })
          );
        }

        return DecorationSet.create(state.doc, decorations);
      },
    },
  });
};

const isNodeSelection = (selection: Selection): selection is NodeSelection => {
  return 'node' in selection;
};
