import { Box, Divider, Input, Text } from '@wix/design-system';
import { LayoutFullSmall, LayoutTwoColumnsSplitSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useRef } from 'react';

import { LAYOUT_DEFAULTS } from './../../../ricos-common-plugins/layout/shared-with-viewer.js';
import { RICOS_LAYOUT_TYPE } from './../../../ricos-content/index.js';
import {
  EditorContext,
  ModalServiceContext,
  RicosContext,
  UploadContext,
  ZIndexContext,
  useDevService,
} from './../../../ricos-context/index.js';
import type { LayoutData_DesignTarget } from './../../../ricos-schema/next-schema/index.js';
import { useTheme } from './../../../ricos-styles/theme-provider.js';
import type { Gradient } from './../../../ricos-types/color-palette-types.js';
import { useBiNext } from './../../../_shared/bi-context-provider/bi-context-provider.js';
import { TRANSPARENT_HEX_COLOR } from './../../../_shared/colors.js';
import type { PmLayoutNode } from './../../../_shared/pm-node-types.js';
import { useWixInstanceService } from './../../../_shared/request-service-provider/wix-instance-context.js';
import { resolveColorToDisplayHex } from './../../../_shared/resolve-color-to-display-hex.js';
import { resolveImageOverlay } from './../../../_shared/resolve-image-overlay.js';
import { schemaGradientToCss } from './../../../_shared/schema-gradient-to-css.js';
import { useEditorProps } from './../../../_shared/some-editor-props-context.js';
import { TogglesWithLabel } from './../../../_shared/toggles-with-label.js';
import { combineHexWithOpacity, getOpacityFromHex } from './../../../wix-rich-content-common/index.js';
import {
  ColorWithOpacityInput,
  NumberInputWithLabel,
  ToggleButton,
  usePanelContainerElement,
} from './../../../ui-components/index.js';
import { findNodeById } from './../../../tiptap-editor/helpers/index.js';

import {
  CELL_SETTINGS_COLOR_PICKER_MODAL_ID,
  LAYOUT_SETTINGS_BACKDROP_COLOR_INPUT,
  LAYOUT_SETTINGS_BACKDROP_COLOR_PICKER,
  LAYOUT_SETTINGS_BACKDROP_BLUR_INPUT,
  LAYOUT_SETTINGS_BACKDROP_IMAGE_VIEWER,
  LAYOUT_SETTINGS_BACKDROP_POSITION_SELECT,
  LAYOUT_SETTINGS_BACKDROP_SCALING_SELECT,
  LAYOUT_SETTINGS_BACKDROP_TOGGLE,
  LAYOUT_SETTINGS_BACKDROP_TYPE_TOGGLE,
  LAYOUT_SETTINGS_BACKGROUND_COLOR_INPUT,
  LAYOUT_SETTINGS_BACKGROUND_COLOR_PICKER,
  LAYOUT_SETTINGS_BACKGROUND_BLUR_INPUT,
  LAYOUT_SETTINGS_BACKGROUND_IMAGE_VIEWER,
  LAYOUT_SETTINGS_BACKGROUND_POSITION_SELECT,
  LAYOUT_SETTINGS_BACKGROUND_SCALING_SELECT,
  LAYOUT_SETTINGS_BACKGROUND_TYPE_TOGGLE,
  LAYOUT_SETTINGS_BORDER_COLOR_INPUT,
  LAYOUT_SETTINGS_BORDER_COLOR_PICKER,
  LAYOUT_SETTINGS_BORDER_RADIUS_INPUT,
  LAYOUT_SETTINGS_BORDER_WIDTH_INPUT,
  LAYOUT_SETTINGS_DESIGN_TARGET_CELL,
  LAYOUT_SETTINGS_DESIGN_TARGET_LAYOUT,
  LAYOUT_SETTINGS_MODAL_ID,
} from '../data-hooks.js';
import { handleLayoutImageUpload } from '../handle-layout-image-upload.js';
import {
  clearTransparentLayoutFill,
  getLayoutFillPatch,
  getResolvedLayoutFillColor,
  hasVisibleLayoutFill,
  resolveLayoutFill,
  toLayoutFill,
  type LayoutFill,
  type LayoutFillKey,
} from '../layout-fill.js';
import { BackgroundSection } from '../shared-settings-components/background-section.js';
import { LayoutColorPicker } from '../shared-settings-components/layout-color-picker.js';
import { DEFAULT_BACKDROP_VERTICAL_SPACING, type LayoutEditorConfig } from '../shared.js';

interface DesignTabProps {
  pmNodeAttrs: PmLayoutNode['attrs'];
  patchPmNodeAttrs: (attrs: Partial<PmLayoutNode['attrs']>) => void;
  nodeId: string;
  config: LayoutEditorConfig;
}

export const DesignTab: FC<DesignTabProps> = ({
  pmNodeAttrs,
  patchPmNodeAttrs,
  nodeId,
  config,
}) => {
  const { t, isMobile } = useContext(RicosContext);

  const { getPublicCommands, adapter } = useContext(EditorContext);
  const wixInstance = useWixInstanceService();
  const editorProps = useEditorProps();
  const { uploadService } = useContext(UploadContext);

  const devService = useDevService();
  const containerEl = usePanelContainerElement();

  const zIndexService = useContext(ZIndexContext);
  const zIndex = zIndexService.getZIndex('DIALOG');
  const modalService = useContext(ModalServiceContext);
  const theme = useTheme();
  const currentBackground = resolveLayoutFill(pmNodeAttrs.background, pmNodeAttrs.backgroundColor);
  const currentBackdrop = resolveLayoutFill(pmNodeAttrs.backdrop, pmNodeAttrs.backdropColor);

  // Read fresh node attrs at the moment of patching. The `pmNodeAttrs` prop is captured
  // per React render; when a user makes several rapid edits to nested image fields (e.g.
  // blur → scaling), the second callback can close over a stale `pmNodeAttrs.backgroundImage`
  // and overwrite the first change. Reading from the live editor state avoids that drop.
  const getFreshAttrs = (): PmLayoutNode['attrs'] => {
    const tr = adapter.tiptapEditor.view.state.tr;
    const fresh = findNodeById(tr, nodeId)[0]?.node.attrs as PmLayoutNode['attrs'] | undefined;
    return fresh ?? pmNodeAttrs;
  };

  const logBi = useBiNext({
    modalId: LAYOUT_SETTINGS_MODAL_ID,
    pluginId: 'layout',
    nodeId,
  });

  const [showBackdropSection, setShowBackdropSection] = React.useState(() => {
    const hasBackdropPadding = pmNodeAttrs.backdropPaddingTop || pmNodeAttrs.backdropPaddingBottom;
    return !!(
      pmNodeAttrs.backdropImage ||
      hasVisibleLayoutFill(currentBackdrop) ||
      hasBackdropPadding
    );
  });
  const [prevBackdrop, setPrevBackdrop] = React.useState<LayoutFill>(currentBackdrop);
  const [prevBackdropImage, setPrevBackdropImage] = React.useState(pmNodeAttrs.backdropImage);
  const [prevBackdropPaddingTop] = React.useState(pmNodeAttrs.backdropPaddingTop);
  const [prevBackdropPaddingBottom] = React.useState(pmNodeAttrs.backdropPaddingBottom);
  const backgroundColorPickerRef = useRef<HTMLDivElement>(null);
  const backdropColorPickerRef = useRef<HTMLDivElement>(null);
  const borderColorPickerRef = useRef<HTMLDivElement>(null);

  const openColorPicker = (
    colorType: 'backgroundColor' | 'borderColor' | 'backdropColor',
    referenceElement: HTMLDivElement,
    fallbackColor?: string
  ) => {
    const modalId = CELL_SETTINGS_COLOR_PICKER_MODAL_ID;
    const allowGradient = colorType === 'backgroundColor' || colorType === 'backdropColor';

    modalService.togglePluginPanel({
      id: modalId,
      Component: LayoutColorPicker,
      componentProps: {
        modalId,
        nodeId,
        referenceElement,
        colorType,
        fallbackColor,
        onValueSelected: onValueChange(colorType),
        allowGradient,
      },
      isMobile,
      positioning: {
        referenceElement,
        placement: 'left',
      },
      type: undefined,
      onClickOutside: {
        on: 'pointerup',
        handler: () => {},
      },
      focusReturnElement: referenceElement ?? undefined,
    });
  };

  // Only true on the first overlay color pick (no existing overlay yet). Subsequent
  // edits — opacity slider, picking a new color — must trust the incoming value.
  const hasNoExistingOverlay = (bgKey: LayoutFillKey) => {
    const fresh = getFreshAttrs();
    // New model: the overlay lives on the image. Legacy: it was the fill color.
    if (fresh[bgKey === 'background' ? 'backgroundImage' : 'backdropImage']?.overlay) {
      return false;
    }
    const legacyColor = fresh[bgKey === 'background' ? 'backgroundColor' : 'backdropColor'];
    const overlayColor = getResolvedLayoutFillColor(fresh[bgKey], legacyColor ?? undefined);
    return !overlayColor || overlayColor === TRANSPARENT_HEX_COLOR;
  };

  const onValueChange =
    (colorType: 'backgroundColor' | 'borderColor' | 'backdropColor') =>
    (value: { color?: string; gradient?: Gradient } | undefined) => {
      // Auto-set overlay alpha to 50% on the first overlay color pick when an image exists.
      const applyOverlayAutoAlpha = (v: typeof value) => {
        if (v?.color && !v.gradient && getOpacityFromHex(v.color) === 100) {
          return { ...v, color: combineHexWithOpacity(v.color, 50) ?? v.color };
        }
        return v;
      };

      const freshAttrs = getFreshAttrs();
      if (colorType === 'backgroundColor') {
        const hasImage = !!freshAttrs.backgroundImage;
        const adjusted =
          hasImage && hasNoExistingOverlay('background') ? applyOverlayAutoAlpha(value) : value;
        // With an image, the picked color/gradient is the overlay (new model); otherwise the base fill.
        patchPmNodeAttrs(
          hasImage
            ? {
                backgroundImage: { ...freshAttrs.backgroundImage, overlay: toLayoutFill(adjusted) },
              }
            : getLayoutFillPatch('background', toLayoutFill(adjusted))
        );
      } else if (colorType === 'backdropColor') {
        const hasImage = !!freshAttrs.backdropImage;
        const adjusted =
          hasImage && hasNoExistingOverlay('backdrop') ? applyOverlayAutoAlpha(value) : value;
        patchPmNodeAttrs(
          hasImage
            ? { backdropImage: { ...freshAttrs.backdropImage, overlay: toLayoutFill(adjusted) } }
            : getLayoutFillPatch('backdrop', toLayoutFill(adjusted))
        );
      } else {
        const currentBorderWidth = pmNodeAttrs.borderWidth ?? LAYOUT_DEFAULTS.borderWidth;
        const borderWidthUpdate = currentBorderWidth === 0 ? { borderWidth: 1 } : {};
        patchPmNodeAttrs({
          borderColor: value?.color ?? TRANSPARENT_HEX_COLOR,
          ...borderWidthUpdate,
        });
      }
    };

  const onColorChange =
    (colorType: 'backgroundColor' | 'borderColor' | 'backdropColor') =>
    (color: string | undefined) =>
      onValueChange(colorType)(color ? { color } : undefined);

  const onBgImageRequest = async (key: 'backgroundImage' | 'backdropImage') => {
    await handleLayoutImageUpload({
      services: {
        devService,
        uploadService: uploadService!,
        editorProps,
        wixInstance,
        modals: modalService,
      },
      config,
      publicCommands: getPublicCommands(),
      nodeId,
      nodeType: RICOS_LAYOUT_TYPE,
      attributeKey: key,
    });
  };
  const onBgImageRemove = (key: 'backgroundImage' | 'backdropImage') =>
    patchPmNodeAttrs({ [key]: undefined });
  const onBackgroundChange = (
    newValue: Parameters<React.ComponentProps<typeof BackgroundSection>['onChange']>[0],
    key: 'backgroundImage' | 'backdropImage'
  ) => {
    const bgKey = key === 'backgroundImage' ? 'background' : 'backdrop';
    const freshAttrs = getFreshAttrs();
    const currentImage = freshAttrs[key];

    // Auto-50% only applies on the FIRST overlay color pick when an image exists; once an
    // overlay color is set, treat slider and color-picker writes as user intent (no override).
    const hasImage = !!currentImage;
    const shouldAutoAlpha = hasImage && hasNoExistingOverlay(bgKey);
    const colorValue =
      'color' in newValue &&
      newValue.color &&
      shouldAutoAlpha &&
      getOpacityFromHex(newValue.color) === 100
        ? (combineHexWithOpacity(newValue.color, 50) ?? newValue.color)
        : 'color' in newValue
          ? newValue.color
          : undefined;
    // With an image, the picked color is the overlay (new model); otherwise the base fill.
    const colorPatch =
      'color' in newValue
        ? hasImage
          ? { [key]: { ...currentImage, overlay: toLayoutFill({ color: colorValue }) } }
          : getLayoutFillPatch(bgKey, toLayoutFill({ color: colorValue }))
        : undefined;

    patchPmNodeAttrs({
      ...colorPatch,
      ...('image' in newValue && { [key]: newValue.image }),
      ...('imageScaling' in newValue &&
        currentImage && {
          [key]: {
            ...currentImage,
            scaling: newValue.imageScaling,
          },
        }),
      ...('imagePosition' in newValue &&
        currentImage && {
          [key]: {
            ...currentImage,
            position: newValue.imagePosition,
          },
        }),
      ...('imageBlur' in newValue &&
        currentImage && {
          [key]: {
            ...currentImage,
            blur: newValue.imageBlur,
          },
        }),
    });
  };
  const onBorderWidthChange = (width: number | undefined) =>
    patchPmNodeAttrs({ borderWidth: width ?? 0 });
  const onBorderRadiusChange = (radius: number | undefined) =>
    patchPmNodeAttrs({ borderRadius: radius ?? 0 });

  // With an image present the picker reflects the image overlay (new model `image.overlay`, or the
  // legacy fill through the opacity shim); without an image it reflects the base fill directly.
  const backgroundFillGradient =
    currentBackground?.type === 'GRADIENT' ? currentBackground.gradient : undefined;
  const themeBackgroundColor = resolveColorToDisplayHex(
    'var(--ricos-custom-layout-background-color)',
    containerEl
  );
  const rawBackgroundColor =
    (currentBackground?.type === 'COLOR' ? currentBackground.color : undefined) ??
    themeBackgroundColor;
  const backgroundOverlay = pmNodeAttrs.backgroundImage
    ? resolveImageOverlay(pmNodeAttrs.backgroundImage, {
        gradient: backgroundFillGradient,
        color: rawBackgroundColor,
      })
    : { gradient: backgroundFillGradient, color: rawBackgroundColor };
  const backgroundGradient = backgroundOverlay?.gradient
    ? schemaGradientToCss(backgroundOverlay.gradient, theme.colorPalette)
    : undefined;
  const backgroundColorValue = backgroundOverlay?.color;

  const backdropFillGradient =
    currentBackdrop?.type === 'GRADIENT' ? currentBackdrop.gradient : undefined;
  const themeBackdropColor = resolveColorToDisplayHex(
    'var(--ricos-custom-layout-backdrop-color)',
    containerEl
  );
  const rawBackdropColor =
    (currentBackdrop?.type === 'COLOR' ? currentBackdrop.color : undefined) ?? themeBackdropColor;
  const backdropOverlay = pmNodeAttrs.backdropImage
    ? resolveImageOverlay(pmNodeAttrs.backdropImage, {
        gradient: backdropFillGradient,
        color: rawBackdropColor,
      })
    : { gradient: backdropFillGradient, color: rawBackdropColor };
  const backdropGradient = backdropOverlay?.gradient
    ? schemaGradientToCss(backdropOverlay.gradient, theme.colorPalette)
    : undefined;
  const backdropColorValue = backdropOverlay?.color ?? rawBackdropColor;

  return (
    <Box direction="vertical" overflow="auto">
      <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
        <Box paddingBottom="SP1">
          <Text size="small" weight="bold">
            {t('Layout_SettingsModal_Tab_Design_Background_Label')}
          </Text>
        </Box>
        <BackgroundSection
          imageLoading={pmNodeAttrs.loading?.backgroundImage}
          image={pmNodeAttrs.backgroundImage}
          imageScaling={pmNodeAttrs.backgroundImage?.scaling ?? 'CONTAIN'}
          imagePosition={pmNodeAttrs.backgroundImage?.position ?? 'CENTER'}
          imageBlur={pmNodeAttrs.backgroundImage?.blur ?? 0}
          color={backgroundColorValue ?? TRANSPARENT_HEX_COLOR}
          gradient={backgroundGradient}
          onChange={newValue => onBackgroundChange(newValue, 'backgroundImage')}
          openColorPicker={() => {
            openColorPicker(
              'backgroundColor',
              backgroundColorPickerRef.current!,
              backgroundColorValue
            );
            logBi({ dataHook: LAYOUT_SETTINGS_BACKGROUND_COLOR_PICKER });
          }}
          colorPickerRef={backgroundColorPickerRef}
          backgroundTypeToggleDataHook={LAYOUT_SETTINGS_BACKGROUND_TYPE_TOGGLE}
          colorDataHook={LAYOUT_SETTINGS_BACKGROUND_COLOR_INPUT}
          colorPickerDataHook={LAYOUT_SETTINGS_BACKGROUND_COLOR_PICKER}
          imageDataHook={LAYOUT_SETTINGS_BACKGROUND_IMAGE_VIEWER}
          imageScalingDataHook={LAYOUT_SETTINGS_BACKGROUND_SCALING_SELECT}
          imagePositionDataHook={LAYOUT_SETTINGS_BACKGROUND_POSITION_SELECT}
          imageBlurDataHook={LAYOUT_SETTINGS_BACKGROUND_BLUR_INPUT}
          onImageRequest={() => onBgImageRequest('backgroundImage')}
          onImageRemove={() => onBgImageRemove('backgroundImage')}
          logBi={logBi}
        />

        <ColorWithOpacityInput
          label={t('Layout_SettingsModal_Tab_Design_Container_BorderColor')}
          fill={{
            type: 'color',
            color: pmNodeAttrs.borderColor ?? TRANSPARENT_HEX_COLOR,
            onChange: onColorChange('borderColor'),
            allowTransparent: true,
          }}
          onColorPress={() => openColorPicker('borderColor', borderColorPickerRef.current!)}
          colorPickerRef={borderColorPickerRef}
          inputDataHook={LAYOUT_SETTINGS_BORDER_COLOR_INPUT}
          fillPreviewDataHook={LAYOUT_SETTINGS_BORDER_COLOR_PICKER}
          zIndex={zIndex}
          logBi={logBi}
        />

        <NumberInputWithLabel
          label={t('Layout_SettingsModal_Tab_Design_Container_BorderWidth')}
          dataHook={LAYOUT_SETTINGS_BORDER_WIDTH_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={pmNodeAttrs.borderWidth ?? LAYOUT_DEFAULTS.borderWidth}
          min={0}
          max={15}
          onChange={onBorderWidthChange}
          logBi={logBi}
          zIndex={zIndex}
        />

        <NumberInputWithLabel
          label={t('Layout_SettingsModal_Tab_Design_Container_BorderRadius')}
          dataHook={LAYOUT_SETTINGS_BORDER_RADIUS_INPUT}
          suffix={<Input.Affix>{t('Common_Units_PX')}</Input.Affix>}
          value={pmNodeAttrs.borderRadius ?? LAYOUT_DEFAULTS.borderRadius}
          min={0}
          max={30}
          onChange={onBorderRadiusChange}
          logBi={logBi}
          zIndex={zIndex}
        />

        <TogglesWithLabel<LayoutData_DesignTarget>
          label={t('Layout_SettingsModal_Tab_Layout_Design_Target_Label')}
          value={pmNodeAttrs.designTarget || LAYOUT_DEFAULTS.designTarget}
          options={[
            {
              label: t('Layout_SettingsModal_Tab_Layout_Design_Target_Cell'),
              value: 'LAYOUT',
              icon: <LayoutFullSmall height="100%" />,
              dataHook: LAYOUT_SETTINGS_DESIGN_TARGET_LAYOUT,
            },
            {
              label: t('Layout_SettingsModal_Tab_Layout_Design_Target_Layout'),
              value: 'CELL',
              icon: <LayoutTwoColumnsSplitSmall height="100%" />,
              dataHook: LAYOUT_SETTINGS_DESIGN_TARGET_CELL,
            },
          ]}
          onChange={value => patchPmNodeAttrs({ designTarget: value })}
        />
      </Box>

      <Divider />

      <Box direction="vertical" padding="SP4" paddingTop="SP3" paddingBottom="SP3" gap="SP2">
        <Box paddingBottom="SP1">
          <Text size="small" weight="bold">
            {t('Layout_SettingsModal_Tab_Design_Backdrop_Label')}
          </Text>
        </Box>

        <ToggleButton
          checked={showBackdropSection}
          title={t('Layout_SettingsModal_Tab_Design_Backdrop_Toggle_Label')}
          size="small"
          dataHook={LAYOUT_SETTINGS_BACKDROP_TOGGLE}
          onChange={() => {
            setShowBackdropSection(prev => !prev);

            if (!showBackdropSection) {
              patchPmNodeAttrs({
                ...getLayoutFillPatch('backdrop', clearTransparentLayoutFill(prevBackdrop)),
                backdropPaddingTop: prevBackdropPaddingTop || DEFAULT_BACKDROP_VERTICAL_SPACING,
                backdropPaddingBottom:
                  prevBackdropPaddingBottom || DEFAULT_BACKDROP_VERTICAL_SPACING,
                backdropImage: prevBackdropImage,
              });
              return;
            }

            setPrevBackdrop(currentBackdrop);
            setPrevBackdropImage(pmNodeAttrs.backdropImage);
            patchPmNodeAttrs({
              ...getLayoutFillPatch('backdrop', undefined),
              backdropImage: undefined,
              backdropPaddingTop: undefined,
              backdropPaddingBottom: undefined,
            });
          }}
          infoContent={t('Layout_SettingsModal_Tab_Design_Backdrop_Toggle_Tooltip')}
          tooltipAppendTo={containerEl}
        />

        {showBackdropSection && (
          <BackgroundSection
            imageLoading={pmNodeAttrs.loading?.backdropImage}
            image={pmNodeAttrs.backdropImage}
            imageScaling={pmNodeAttrs.backdropImage?.scaling ?? 'CONTAIN'}
            imagePosition={pmNodeAttrs.backdropImage?.position ?? 'CENTER'}
            imageBlur={pmNodeAttrs.backdropImage?.blur ?? 0}
            color={backdropColorValue ?? TRANSPARENT_HEX_COLOR}
            gradient={backdropGradient}
            onChange={newValue => onBackgroundChange(newValue, 'backdropImage')}
            openColorPicker={() => {
              openColorPicker('backdropColor', backdropColorPickerRef.current!, backdropColorValue);
              logBi({ dataHook: LAYOUT_SETTINGS_BACKDROP_COLOR_PICKER });
            }}
            colorPickerRef={backdropColorPickerRef}
            backgroundTypeToggleDataHook={LAYOUT_SETTINGS_BACKDROP_TYPE_TOGGLE}
            colorDataHook={LAYOUT_SETTINGS_BACKDROP_COLOR_INPUT}
            colorPickerDataHook={LAYOUT_SETTINGS_BACKDROP_COLOR_PICKER}
            imageDataHook={LAYOUT_SETTINGS_BACKDROP_IMAGE_VIEWER}
            imageScalingDataHook={LAYOUT_SETTINGS_BACKDROP_SCALING_SELECT}
            imagePositionDataHook={LAYOUT_SETTINGS_BACKDROP_POSITION_SELECT}
            imageBlurDataHook={LAYOUT_SETTINGS_BACKDROP_BLUR_INPUT}
            onImageRequest={() => onBgImageRequest('backdropImage')}
            onImageRemove={() => onBgImageRemove('backdropImage')}
            logBi={logBi}
          />
        )}
      </Box>
    </Box>
  );
};
