// Idempotent DOM writers: each only mutates when the value actually changes.
//
// Why: `setAttribute`/`setProperty`/`textContent =`/`classList.value =` queue a
// MutationRecord even when the new value is identical to the current one. In
// node views that re-project on every selection update, those redundant writes
// fire ProseMirror's MutationObserver, which propagates re-renders into nested
// node views. Routing every DOM write through these helpers makes the projection
// safe to call on every event without thrashing.

export const setAttr = (el: Element, name: string, value: string | null) => {
  const current = el.getAttribute(name);
  if (value === null) {
    if (current !== null) {
      el.removeAttribute(name);
    }
  } else if (current !== value) {
    el.setAttribute(name, value);
  }
};

export const setStyleVar = (el: HTMLElement, name: string, value: string | null) => {
  const current = el.style.getPropertyValue(name);
  if (value === null) {
    if (current !== '') {
      el.style.removeProperty(name);
    }
  } else if (current !== value) {
    el.style.setProperty(name, value);
  }
};

export const setText = (el: Node, value: string) => {
  if (el.textContent !== value) {
    el.textContent = value;
  }
};

export const setClass = (el: Element, value: string) => {
  if (el.className !== value) {
    el.className = value;
  }
};

export const setChild = (parent: Element, child: Node, shouldBePresent: boolean) => {
  const isPresent = child.parentNode === parent;
  if (shouldBePresent) {
    if (!isPresent) {
      parent.appendChild(child);
    }
  } else if (isPresent) {
    parent.removeChild(child);
  }
};
