import {
  TIPTAP_CARD_CONTENT_TYPE,
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_FIGURE_TYPE,
  TIPTAP_IMAGE_TYPE,
  TIPTAP_LAYOUT_CELL_TYPE,
  TIPTAP_LAYOUT_TYPE,
  generateId,
} from './../../ricos-content/index.js';
import { Node_Type } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import type { LayoutData_Banner, VerticalAlignment } from './../../ricos-schema/next-schema/index.js';
import type { ExtensionProps, RicosExtension } from './../../ricos-types/index.js';
import type { PmFigureNode } from './../../_shared/pm-node-types.js';
import { type NodeConfig, type NodeWithPos, findParentNodeClosestToPos } from './../../tiptap/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import { NodeSelection } from './../../tiptap/pm/state.js';
import type { EditorView } from './../../tiptap/pm/view.js';
import { findNodeById } from './../../tiptap-editor/helpers/index.js';
import type { TiptapAdapterServices } from './../../tiptap-editor/initialize-tiptap-adapter.js';
import { createRicosNodeExtension } from './../../tiptap-extensions/index.js';

import {
  createBannerDropPreventionPlugin,
  isAfterLastFooterCell,
  isBeforeFirstBannerCell,
} from './banner-drop-prevention-plugin.js';
import { createBannerUniquenessPlugin } from './banner-uniqueness-plugin.js';
import { createCellNormalizingTransactionPlugin } from './cell-normalizing.js';
import { getLayoutFillHtmlAttrs, parseLayoutFillHtmlAttr } from './layout-fill.js';
import { layoutNodeView } from './layout-node-view.js';
import { layoutSelectionDecorationPlugin } from './layout-selection-decorator.js';
import { LAYOUT_DEFAULTS, MAX_CELLS } from './shared-with-viewer.js';
import type { LayoutExtensionStorage } from './shared.js';
import { balanceLayoutCells, findParentCardId, tryParseJson } from './shared.js';

/**
 * Checks if all cells in a layout node contain only empty paragraphs
 */
const areAllCellsEmpty = (layoutNodeWithPos: NodeWithPos): boolean => {
  let allEmpty = true;

  layoutNodeWithPos.node.content.forEach(cell => {
    cell.content.forEach(child => {
      // Check if it's a paragraph with no content
      if (child.type.name !== Node_Type.PARAGRAPH || child.textContent.length > 0) {
        allEmpty = false;
      }
    });
  });

  return allEmpty;
};

declare module './../../tiptap/core' {
  interface Commands<ReturnType> {
    [TIPTAP_LAYOUT_TYPE]: {
      selectLayout: (nodeId: string) => ReturnType;
      balanceLayoutCells: (nodeId: string) => ReturnType;
      setCellsColSpan: (nodeId: string, colSpans: number[]) => ReturnType;
      setLayoutCellsVerticalAlignment: (
        layoutNodeId: string,
        verticalAlignment: VerticalAlignment
      ) => ReturnType;
      setContainerWidth: (layoutNodeId: string, width: number | null) => ReturnType;
      setLayoutBanner: (layoutNodeId: string, banner: LayoutData_Banner | undefined) => ReturnType;
    };
  }
}

export const layoutExtension = createRicosNodeExtension({
  name: TIPTAP_LAYOUT_TYPE,
  groups: ['custom-styles', 'shortcuts-enabled'],
  type: 'html-node',
  reconfigure: (
    config: NodeConfig,
    _extensions: RicosExtension[],
    props: ExtensionProps,
    settings: Record<string, unknown>,
    services: TiptapAdapterServices
  ) => {
    return {
      ...config,
      draggable: !services.context.isMobile,
      addOptions: () => {
        return {
          isMobile: services.context.isMobile,
          converters: services.converters,
          ...settings,
          ...config,
          breakoutRule: props.breakoutRule,
          theme: services.editorProps?.theme,
          modals: services.modals,
        };
      },
    };
  },
  createExtensionConfig() {
    return {
      name: this.name,
      isolating: true,
      group: 'block',
      selectable: true,
      draggable: true,
      addStorage(): LayoutExtensionStorage {
        return { draggedCellSourceLayout: null };
      },
      extendNodeSchema: () => {
        return {
          // We need to disable default drop cursor for layouts as this is handled by layout itself
          disableDropCursor: (editorView: EditorView, pos: { pos: number; inside: number }) => {
            // Disable drop cursor before the first cell of a banner layout or after the last cell of a footer layout
            const $pos = editorView.state.doc.resolve(pos.pos);
            if (isBeforeFirstBannerCell($pos) || isAfterLastFooterCell($pos)) {
              return true;
            }

            if (pos.inside > 0) {
              const layoutNode = findParentNodeClosestToPos(
                editorView.state.doc.resolve(pos.inside),
                node => node.type?.name === TIPTAP_LAYOUT_TYPE
              )?.node;

              const isDraggingCell =
                editorView.dragging?.slice.content.firstChild?.type.name ===
                TIPTAP_LAYOUT_CELL_TYPE;

              if (layoutNode && isDraggingCell) {
                const dropCursorView: { scheduleRemoval: (timer: number) => void } =
                  // @ts-ignore TODO: find better way to remove scheduled cursor maybe we should fork it?
                  editorView.pluginViews.find(view => view.constructor.name === 'DropCursorView');

                if (dropCursorView) {
                  // When drop cursor is disabled, it will still be visible for 5000ms. It's hard
                  // coded in the drop cursor plugin, so we need a hack to remove it immediately to
                  // prevent multiple drop cursors from being visible at the same time.
                  dropCursorView.scheduleRemoval(0);
                }
                return true;
              }
              return false;
            }

            return false;
          },
        };
      },
      content: `${TIPTAP_LAYOUT_CELL_TYPE}{1,${MAX_CELLS}}`,
      parseHTML() {
        return [
          {
            tag: 'div[data-layout-container]',
            getAttrs: (node: HTMLElement) => {
              const backgroundAttrs = parseLayoutFillHtmlAttr(
                node.getAttribute('data-layout-background'),
                node.getAttribute('data-layout-background-color'),
                LAYOUT_DEFAULTS.backgroundColor
              );
              const backgroundImage =
                tryParseJson(node.getAttribute('data-layout-background-image')) ||
                LAYOUT_DEFAULTS.backgroundImage;
              const borderColor =
                node.getAttribute('data-layout-border-color') || LAYOUT_DEFAULTS.borderColor;
              const borderWidth = Number(
                node.getAttribute('data-layout-border-width') ?? LAYOUT_DEFAULTS.borderWidth
              );
              const borderRadius = Number(
                node.getAttribute('data-layout-border-radius') ?? LAYOUT_DEFAULTS.borderRadius
              );
              const backdropAttrs = parseLayoutFillHtmlAttr(
                node.getAttribute('data-layout-backdrop'),
                node.getAttribute('data-layout-backdrop-color'),
                LAYOUT_DEFAULTS.backdropColor
              );
              const backdropImage =
                tryParseJson(node.getAttribute('data-layout-backdrop-image')) ||
                LAYOUT_DEFAULTS.backdropImage;
              const backdropPaddingTop = Number(
                node.getAttribute('data-layout-backdrop-padding-top') ??
                  LAYOUT_DEFAULTS.backdropPaddingTop
              );
              const backdropPaddingBottom = Number(
                node.getAttribute('data-layout-backdrop-padding-bottom') ??
                  LAYOUT_DEFAULTS.backdropPaddingBottom
              );
              const gap = Number(node.getAttribute('data-layout-gap') ?? LAYOUT_DEFAULTS.gap);
              const responsivenessBehaviour =
                node.getAttribute('data-layout-responsiveness-behaviour') ||
                LAYOUT_DEFAULTS.responsivenessBehaviour;
              const responsivenessBreakpoint =
                node.getAttribute('data-layout-responsiveness-breakpoint') ||
                LAYOUT_DEFAULTS.responsivenessBreakpoint;
              const cellPadding = (
                node.getAttribute('data-layout-cell-padding') ??
                LAYOUT_DEFAULTS.cellPadding.join(' ')
              )
                .split(' ')
                .map(Number);
              const cellVerticalAlignment =
                node.getAttribute('data-layout-cell-vertical-alignment') ||
                LAYOUT_DEFAULTS.cellVerticalAlignment;
              const banner =
                tryParseJson(node.getAttribute('data-layout-banner')) || LAYOUT_DEFAULTS.banner;
              const designTarget =
                node.getAttribute('data-layout-design-target') || LAYOUT_DEFAULTS.designTarget;
              return {
                background: backgroundAttrs.fill,
                backgroundColor: backgroundAttrs.legacyColor,
                backgroundImage,
                borderColor,
                borderWidth,
                borderRadius,
                backdrop: backdropAttrs.fill,
                backdropColor: backdropAttrs.legacyColor,
                backdropImage,
                backdropPaddingTop,
                backdropPaddingBottom,
                gap,
                cellPadding,
                cellVerticalAlignment,
                responsivenessBehaviour,
                responsivenessBreakpoint,
                banner,
                designTarget,
              };
            },
          },
        ];
      },
      renderHTML({ node }) {
        return [
          'div',
          {
            'data-layout-container': true,
            ...getLayoutFillHtmlAttrs({
              fill: node.attrs.background,
              legacyColor: node.attrs.backgroundColor,
              fillKey: 'background',
            }),
            ...(node.attrs.backgroundImage
              ? { 'data-layout-background-image': JSON.stringify(node.attrs.backgroundImage) }
              : {}),
            ...(node.attrs.borderColor
              ? { 'data-layout-border-color': node.attrs.borderColor }
              : {}),
            ...(node.attrs.borderWidth
              ? { 'data-layout-border-width': node.attrs.borderWidth }
              : {}),
            ...(node.attrs.borderRadius
              ? { 'data-layout-border-radius': node.attrs.borderRadius }
              : {}),
            ...getLayoutFillHtmlAttrs({
              fill: node.attrs.backdrop,
              legacyColor: node.attrs.backdropColor,
              fillKey: 'backdrop',
            }),
            ...(node.attrs.backdropImage
              ? { 'data-layout-backdrop-image': JSON.stringify(node.attrs.backdropImage) }
              : {}),
            ...(node.attrs.backdropPaddingTop
              ? { 'data-layout-backdrop-padding-top': node.attrs.backdropPaddingTop }
              : {}),
            ...(node.attrs.backdropPaddingBottom
              ? { 'data-layout-backdrop-padding-bottom': node.attrs.backdropPaddingBottom }
              : {}),
            ...(node.attrs.gap ? { 'data-layout-gap': node.attrs.gap } : {}),
            ...(node.attrs.responsivenessBehaviour
              ? { 'data-layout-responsiveness-behaviour': node.attrs.responsivenessBehaviour }
              : {}),
            ...(node.attrs.responsivenessBreakpoint
              ? { 'data-layout-responsiveness-breakpoint': node.attrs.responsivenessBreakpoint }
              : {}),
            ...(node.attrs.cellPadding
              ? { 'data-layout-cell-padding': node.attrs.cellPadding.join(' ') }
              : {}),
            ...(node.attrs.cellVerticalAlignment
              ? { 'data-layout-cell-vertical-alignment': node.attrs.cellVerticalAlignment }
              : {}),
            ...(node.attrs.banner
              ? { 'data-layout-banner': JSON.stringify(node.attrs.banner) }
              : {}),
            ...(node.attrs.designTarget
              ? { 'data-layout-design-target': node.attrs.designTarget }
              : {}),
          },
          0,
        ];
      },
      addNodeView() {
        return layoutNodeView({
          disableInteractions:
            this.options.isMobile ||
            (!this.options.showInToolbars && !this.options.showInQuickActions),
          breakoutRule: this.options.breakoutRule,
          isMobile: this.options.isMobile,
          colorPalette: this.options.theme?.colorPalette,
          modals: this.options.modals,
        });
      },
      addAttributes: () => ({
        containerData: null,
        background: null,
        backgroundColor: null,
        backgroundImage: null,
        borderColor: null,
        borderWidth: null,
        borderRadius: null,
        backdrop: null,
        backdropColor: null,
        backdropImage: null,
        backdropPaddingTop: null,
        backdropPaddingBottom: null,
        gap: null,
        cellPadding: null,
        cellVerticalAlignment: null,
        responsivenessBehaviour: null,
        responsivenessBreakpoint: null,
        designTarget: null,
        banner: null,
        loading: false,
        error: null,
      }),
      addCommands() {
        return {
          selectLayout:
            (nodeId: string) =>
            ({ commands, tr }) => {
              const nodeWithPos = findNodeById(tr, nodeId)[0];
              return commands.setNodeSelection(nodeWithPos.pos);
            },
          balanceLayoutCells:
            (nodeId: string) =>
            ({ tr, dispatch }) => {
              const { node, pos } = findNodeById(tr, nodeId)[0];

              balanceLayoutCells(tr, node, pos);

              if (dispatch) {
                return dispatch(tr);
              }

              return true;
            },
          setCellsColSpan:
            (nodeId: string, colSpans: number[]) =>
            ({ tr, dispatch }) => {
              const { node, pos } = findNodeById(tr, nodeId)[0];

              node?.forEach((_child, childPos, index) => {
                tr.setNodeAttribute(pos + childPos + 1, 'colSpan', colSpans[index]);
              });

              if (dispatch) {
                return dispatch(tr);
              }

              return true;
            },
          setLayoutCellsVerticalAlignment:
            (layoutNodeId: string, verticalAlignment: VerticalAlignment) =>
            ({ tr, dispatch }) => {
              const layoutNode = findNodeById(tr, layoutNodeId)[0];

              tr.setNodeAttribute(layoutNode.pos, 'cellVerticalAlignment', verticalAlignment);

              if (dispatch) {
                return dispatch(tr);
              }

              return true;
            },
          setContainerWidth:
            (layoutNodeId: string, width: number | null) =>
            ({ tr, dispatch }) => {
              const layoutNode = findNodeById(tr, layoutNodeId)[0];

              tr.setNodeAttribute(
                layoutNode.pos,
                'containerData',
                width === null
                  ? null
                  : {
                      width: { custom: width.toString() },
                    }
              );

              if (dispatch) {
                return dispatch(tr);
              }

              return true;
            },
          setLayoutBanner:
            (layoutNodeId: string, banner: LayoutData_Banner | undefined) =>
            ({ tr, chain }) => {
              const layoutNodeWithPos = findNodeById(tr, layoutNodeId)[0];
              if (!layoutNodeWithPos) {
                return false;
              }

              const cardId = findParentCardId(tr.doc, layoutNodeWithPos.pos);
              const currentAttrs = layoutNodeWithPos.node.attrs;

              if (banner) {
                const isTop = banner.position === 'TOP';
                const newAttrs = {
                  ...currentAttrs,
                  banner: { position: banner.position, origin: 'LAYOUT' as const },
                  backdropColor: undefined,
                };

                const layoutContent = layoutNodeWithPos.node.content.toJSON();
                const layoutNode = {
                  type: TIPTAP_LAYOUT_TYPE,
                  attrs: newAttrs,
                  content: layoutContent,
                };

                // Inside a card, banners live in dedicated PM child nodes:
                // - TOP    → CARD_HEADER (created if missing, replaced if present)
                // - BOTTOM → CARD_FOOTER (created if missing, replaced if present)
                // Re-select the layout afterward so the layout toolbar stays
                // the active toolbar — otherwise the cursor lands inside a
                // cell and whatever plugin sits there hijacks the floating toolbar.
                if (cardId) {
                  const wrapperType = isTop ? TIPTAP_CARD_HEADER_TYPE : TIPTAP_CARD_FOOTER_TYPE;
                  return chain()
                    .deleteNode(layoutNodeId)
                    .command(({ tr: chainTr }) => {
                      const card = findNodeById(chainTr, cardId)[0];
                      if (!card) {
                        return false;
                      }

                      let wrapperNode: PmNode | undefined;
                      let wrapperPos = -1;
                      card.node.forEach((child, offset) => {
                        if (child.type.name === wrapperType && !wrapperNode) {
                          wrapperNode = child;
                          wrapperPos = card.pos + 1 + offset;
                        }
                      });

                      const newWrapper = chainTr.doc.type.schema.nodeFromJSON({
                        type: wrapperType,
                        content: [layoutNode],
                      });

                      if (wrapperNode) {
                        chainTr.replaceWith(
                          wrapperPos,
                          wrapperPos + wrapperNode.nodeSize,
                          newWrapper
                        );
                      } else if (isTop) {
                        // Insert at the very start of CARD's content, before
                        // CARD_CONTENT (and any existing CARD_FOOTER).
                        chainTr.insert(card.pos + 1, newWrapper);
                      } else {
                        // Insert at the very end of CARD's content, just before
                        // CARD's closing token.
                        const cardEndInner = card.pos + card.node.nodeSize - 1;
                        chainTr.insert(cardEndInner, newWrapper);
                      }
                      return true;
                    })
                    .selectLayout(layoutNodeId)
                    .run();
                }

                // No parent card: insert at doc edges as a regular layout.
                return chain()
                  .deleteNode(layoutNodeId)
                  .command(({ tr: chainTr, commands }) => {
                    const insertPos = isTop ? 0 : chainTr.doc.content.size;
                    return commands.insertContentAt(insertPos, layoutNode);
                  })
                  .selectLayout(layoutNodeId)
                  .run();
              }

              // When disabling banner, check if we should revert to image
              const currentBanner = currentAttrs.banner as LayoutData_Banner | undefined;
              const backdropImage = currentAttrs.backdropImage;
              const isTop = currentBanner?.position === 'TOP';

              if (
                currentBanner?.origin === 'IMAGE' &&
                backdropImage?.media &&
                areAllCellsEmpty(layoutNodeWithPos)
              ) {
                const imageContent: PmFigureNode = {
                  type: TIPTAP_FIGURE_TYPE,
                  attrs: { id: generateId() },
                  content: [
                    {
                      type: TIPTAP_IMAGE_TYPE,
                      attrs: {
                        id: generateId(),
                        image: {
                          src: backdropImage.media.src,
                          width: backdropImage.media.width,
                          height: backdropImage.media.height,
                        },
                        link: null,
                        disableExpand: null,
                        altText: null,
                        disableDownload: null,
                        decorative: null,
                        containerData: {
                          width: { size: 'CONTENT' },
                          alignment: 'CENTER',
                          textWrap: true,
                        },
                        loading: null,
                        loadingPercentage: null,
                        tempData: null,
                        error: null,
                        styles: null,
                      },
                    },
                    {
                      type: Node_Type.CAPTION,
                      attrs: {
                        id: generateId(),
                        textStyle: {},
                        styleDefaults: { paddingTop: '16px', paddingBottom: '16px' },
                      },
                      content: [],
                    },
                  ],
                };

                // Inside a CARD_HEADER / CARD_FOOTER wrapper: delete the wrapper
                // (which also removes the layout) and insert the image at the
                // start of CARD_CONTENT (TOP) or the end (BOTTOM) — same scope
                // the layout originally lived in, so it doesn't drift to the
                // next card.
                if (cardId) {
                  const $layoutPos = tr.doc.resolve(layoutNodeWithPos.pos);
                  const wrapperType = isTop ? TIPTAP_CARD_HEADER_TYPE : TIPTAP_CARD_FOOTER_TYPE;
                  const isInCardWrapper = $layoutPos.parent.type.name === wrapperType;

                  if (isInCardWrapper) {
                    return chain()
                      .command(({ tr: chainTr }) => {
                        const card = findNodeById(chainTr, cardId)[0];
                        if (!card) {
                          return false;
                        }

                        let wrapperStart = -1;
                        let wrapperSize = -1;
                        card.node.forEach((child, offset) => {
                          if (child.type.name === wrapperType && wrapperStart === -1) {
                            wrapperStart = card.pos + 1 + offset;
                            wrapperSize = child.nodeSize;
                          }
                        });
                        if (wrapperStart === -1) {
                          return false;
                        }

                        chainTr.delete(wrapperStart, wrapperStart + wrapperSize);

                        const cardAfter = findNodeById(chainTr, cardId)[0];
                        if (!cardAfter) {
                          return false;
                        }

                        let cardContentTarget = -1;
                        cardAfter.node.forEach((child, offset) => {
                          if (
                            child.type.name === TIPTAP_CARD_CONTENT_TYPE &&
                            cardContentTarget === -1
                          ) {
                            const innerStart = cardAfter.pos + 1 + offset + 1;
                            const innerEnd = cardAfter.pos + 1 + offset + child.nodeSize - 1;
                            cardContentTarget = isTop ? innerStart : innerEnd;
                          }
                        });
                        if (cardContentTarget === -1) {
                          return false;
                        }

                        const figureNode = chainTr.doc.type.schema.nodeFromJSON(imageContent);
                        chainTr.insert(cardContentTarget, figureNode);
                        return true;
                      })
                      .run();
                  }
                }

                // Layout is at doc top-level (or not wrapped) — fall back to the
                // legacy doc-edge insertion.
                return chain()
                  .deleteNode(layoutNodeId)
                  .command(({ tr: chainTr, commands }) => {
                    const insertPos = isTop ? 0 : chainTr.doc.content.size;
                    return commands.insertContentAt(insertPos, imageContent);
                  })
                  .run();
              }

              // Demoting a banner inside a card: move the layout out of its
              // wrapper (CARD_HEADER for top banner / CARD_FOOTER for footer)
              // and back into CARD_CONTENT, removing the empty wrapper.
              // Padding is preserved as-is — banner attachment is independent
              // of the layout's padding settings.
              if (currentBanner && cardId) {
                const $layoutPos = tr.doc.resolve(layoutNodeWithPos.pos);
                const wrapperType =
                  currentBanner.position === 'TOP'
                    ? TIPTAP_CARD_HEADER_TYPE
                    : TIPTAP_CARD_FOOTER_TYPE;
                const isInCardWrapper = $layoutPos.parent.type.name === wrapperType;

                if (isInCardWrapper) {
                  const layoutContent = layoutNodeWithPos.node.content.toJSON();
                  const demotedLayout = {
                    type: TIPTAP_LAYOUT_TYPE,
                    attrs: {
                      ...currentAttrs,
                      banner: undefined,
                    },
                    content: layoutContent,
                  };

                  return chain()
                    .command(({ tr: chainTr }) => {
                      const card = findNodeById(chainTr, cardId)[0];
                      if (!card) {
                        return false;
                      }

                      let wrapperStart = -1;
                      let wrapperSize = -1;
                      card.node.forEach((child, offset) => {
                        if (child.type.name === wrapperType && wrapperStart === -1) {
                          wrapperStart = card.pos + 1 + offset;
                          wrapperSize = child.nodeSize;
                        }
                      });
                      if (wrapperStart === -1) {
                        return false;
                      }

                      chainTr.delete(wrapperStart, wrapperStart + wrapperSize);

                      const cardAfter = findNodeById(chainTr, cardId)[0];
                      if (!cardAfter) {
                        return false;
                      }

                      // Top banners get re-inserted at the start of CARD_CONTENT,
                      // footers at the end.
                      let cardContentTarget = -1;
                      cardAfter.node.forEach((child, offset) => {
                        if (
                          child.type.name === TIPTAP_CARD_CONTENT_TYPE &&
                          cardContentTarget === -1
                        ) {
                          const cardContentInnerStart = cardAfter.pos + 1 + offset + 1;
                          const cardContentInnerEnd =
                            cardAfter.pos + 1 + offset + child.nodeSize - 1;
                          cardContentTarget =
                            currentBanner.position === 'TOP'
                              ? cardContentInnerStart
                              : cardContentInnerEnd;
                        }
                      });
                      if (cardContentTarget === -1) {
                        return false;
                      }

                      const layoutPmNode = chainTr.doc.type.schema.nodeFromJSON(demotedLayout);
                      chainTr.insert(cardContentTarget, layoutPmNode);
                      return true;
                    })
                    .selectLayout(layoutNodeId)
                    .run();
                }
              }

              // Default: clear the banner attribute. Padding is left untouched
              // so it persists across banner toggles. Re-select the layout so
              // the toolbar stays active.
              return chain()
                .updateNodeAttrsById(layoutNodeId, { banner: undefined })
                .selectLayout(layoutNodeId)
                .run();
            },
        };
      },
      addKeyboardShortcuts() {
        const deleteEmptyLayout = () => {
          const { state, view } = this.editor;
          const { selection } = state;

          let layoutNode;
          let layoutPos;

          // Check if a layout node is selected (node selection)
          if (
            selection instanceof NodeSelection &&
            selection.node.type.name === TIPTAP_LAYOUT_TYPE
          ) {
            layoutNode = selection.node;
            layoutPos = selection.from;
          } else if (selection.empty) {
            // Check if cursor is inside a layout
            const layoutNodeWithPos = findParentNodeClosestToPos(
              selection.$from,
              node => node.type?.name === TIPTAP_LAYOUT_TYPE
            );

            if (!layoutNodeWithPos) {
              return false;
            }

            layoutNode = layoutNodeWithPos.node;
            layoutPos = layoutNodeWithPos.pos;
          } else {
            // Selection is a range, not a cursor or node selection
            return false;
          }

          // Check if all cells in the layout are empty
          // A cell is considered empty if it only contains a single empty paragraph
          let allCellsEmpty = true;

          layoutNode.forEach(cell => {
            if (cell.type.name === TIPTAP_LAYOUT_CELL_TYPE) {
              // Check if cell has more than one child or if the single child is not an empty paragraph
              if (cell.childCount > 1) {
                allCellsEmpty = false;
              } else if (cell.childCount === 1) {
                const child = cell.firstChild;
                // Cell is not empty if the child is not a paragraph or if the paragraph has content
                if (child?.type.name !== 'PARAGRAPH' || child.childCount > 0) {
                  allCellsEmpty = false;
                }
              }
            }
          });

          // If the layout has content, don't delete it
          if (!allCellsEmpty) {
            return false;
          }

          // Delete the entire layout
          const tr = state.tr.deleteRange(layoutPos, layoutPos + layoutNode.nodeSize);
          view.dispatch(tr);
          return true;
        };

        return {
          Backspace: deleteEmptyLayout,
          Delete: deleteEmptyLayout,
        };
      },
      addProseMirrorPlugins() {
        return [
          layoutSelectionDecorationPlugin(),
          createCellNormalizingTransactionPlugin(this.editor),
          createBannerDropPreventionPlugin(),
          createBannerUniquenessPlugin(),
        ];
      },
    };
  },
});
