import type { ModalService } from './../../ricos-modals/index.js';
import type { EditorView } from './../../tiptap/pm/view.js';

// Treat the editor as focused whenever any modal is open. Modals (e.g. layout
// settings, cell settings, inline AI prompt) steal browser focus from the
// editor, but the user is still working within the editor context. Layout
// selection chrome should remain visible during that time.
export const isEditorOrModalActive = (
  view: EditorView,
  modals: ModalService | undefined
): boolean => {
  if (view.hasFocus()) {
    return true;
  }
  return !!modals && modals.getOpenModals().length > 0;
};
