import type { LayoutData_Backdrop, LayoutData_Background } from './../../ricos-schema/legacy/wix/rich_content/v1/index.js';
import { TRANSPARENT_HEX_COLOR } from './../../_shared/colors.js';
import type { PmLayoutNode } from './../../_shared/pm-node-types.js';

import { tryParseJson } from './shared.js';

export type LayoutFill = PmLayoutNode['attrs']['background'];
export type LayoutFillKey = 'background' | 'backdrop';
type LayoutFillColor = Extract<NonNullable<LayoutFill>, { type: 'COLOR' }>['color'];
type LayoutFillGradient = Extract<NonNullable<LayoutFill>, { type: 'GRADIENT' }>['gradient'];
type LegacyLayoutFill =
  | Pick<LayoutData_Background, 'type' | 'color' | 'gradient'>
  | Pick<LayoutData_Backdrop, 'type' | 'color' | 'gradient'>;
type LayoutFillInput = LayoutFill | LegacyLayoutFill;

const isLayoutFillObject = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null;

const isLayoutFillGradient = (value: unknown): value is LayoutFillGradient =>
  isLayoutFillObject(value);

const isNormalizedLayoutFill = (value: LayoutFillInput): value is NonNullable<LayoutFill> =>
  value?.type === 'COLOR'
    ? typeof value.color === 'string' && !!value.color
    : value?.type === 'GRADIENT'
      ? isLayoutFillGradient(value.gradient)
      : false;

const parseLayoutFill = (value: unknown): LayoutFill => {
  if (!isLayoutFillObject(value)) {
    return undefined;
  }

  if (typeof value.color === 'string' && value.color) {
    return { type: 'COLOR', color: value.color };
  }

  if (isLayoutFillGradient(value.gradient)) {
    return { type: 'GRADIENT', gradient: value.gradient };
  }

  return undefined;
};

export const toLayoutFill = (
  value: { color?: LayoutFillColor; gradient?: LayoutFillGradient } | undefined
): LayoutFill => {
  if (value?.gradient) {
    return { type: 'GRADIENT', gradient: value.gradient };
  }

  if (value?.color) {
    return { type: 'COLOR', color: value.color };
  }

  return undefined;
};

export const getLegacyLayoutFillColorKey = (fillKey: LayoutFillKey) =>
  fillKey === 'background' ? 'backgroundColor' : 'backdropColor';

export function resolveLayoutFill(fill: LayoutFillInput, legacyColor?: string | null): LayoutFill {
  if (isNormalizedLayoutFill(fill)) {
    return fill;
  }

  const gradient = getLayoutFillGradient(fill);
  if (gradient) {
    return { type: 'GRADIENT', gradient };
  }

  const color = getLayoutFillColor(fill);
  if (color !== undefined) {
    return { type: 'COLOR', color };
  }

  if (typeof legacyColor === 'string') {
    return { type: 'COLOR', color: legacyColor };
  }

  return undefined;
}

export const getLayoutFillColor = (fill: LayoutFillInput): string | undefined =>
  fill && 'color' in fill && typeof fill.color === 'string' ? fill.color || undefined : undefined;

export const getLayoutFillGradient = (fill: LayoutFillInput): LayoutFillGradient | undefined =>
  fill && 'gradient' in fill && isLayoutFillGradient(fill.gradient) ? fill.gradient : undefined;

export const getResolvedLayoutFillColor = (
  fill: LayoutFillInput,
  legacyColor?: string
): string | undefined => getLayoutFillColor(resolveLayoutFill(fill, legacyColor));

export const getResolvedLayoutFillGradient = (fill: LayoutFillInput, legacyColor?: string) =>
  getLayoutFillGradient(resolveLayoutFill(fill, legacyColor));

export const hasVisibleLayoutFill = (fill: LayoutFillInput): boolean => {
  if (getLayoutFillGradient(fill)) {
    return true;
  }

  const color = getLayoutFillColor(fill);
  return !!color && color !== TRANSPARENT_HEX_COLOR;
};

export const isTransparentOrEmptyLayoutFill = (fill: LayoutFillInput): boolean =>
  !fill || getLayoutFillColor(fill) === TRANSPARENT_HEX_COLOR;

export const clearTransparentLayoutFill = (fill: LayoutFill): LayoutFill => {
  if (!fill || isTransparentOrEmptyLayoutFill(fill)) {
    return undefined;
  }

  return fill;
};

export const getLayoutFillPatch = (
  fillKey: LayoutFillKey,
  fill: LayoutFill
): Partial<PmLayoutNode['attrs']> =>
  ({
    [fillKey]: fill,
    [getLegacyLayoutFillColorKey(fillKey)]: undefined,
  }) as Partial<PmLayoutNode['attrs']>;

export const parseLayoutFillHtmlAttr = (
  serializedFill: string | null,
  legacyColor: string | null,
  defaultColor: string | null
): {
  fill: LayoutFill;
  legacyColor: string | undefined;
} => {
  const fill = parseLayoutFill(tryParseJson(serializedFill));

  return {
    fill,
    legacyColor:
      getLayoutFillColor(fill) ??
      (fill?.type === 'GRADIENT'
        ? (defaultColor ?? undefined)
        : (legacyColor ?? defaultColor ?? undefined)),
  };
};

export const getLayoutFillHtmlAttrs = ({
  fill,
  legacyColor,
  fillKey,
}: {
  fill: LayoutFill;
  legacyColor?: string;
  fillKey: LayoutFillKey;
}): Record<string, string> => {
  const serializedFillKey = `data-layout-${fillKey}`;
  const serializedColorKey = `data-layout-${fillKey}-color`;
  const resolvedLegacyColor = getLayoutFillColor(fill) ?? (fill ? undefined : legacyColor);

  return {
    ...(fill ? { [serializedFillKey]: JSON.stringify(fill) } : {}),
    ...(resolvedLegacyColor !== undefined ? { [serializedColorKey]: resolvedLegacyColor } : {}),
  };
};
