import { definePmNodeConverter } from './../../pm-converters/types.js';
import type { LayoutCellNode } from './../../ricos-schema/next-schema/index.js';
import { Node_Type } from './../../ricos-schema/next-schema/index.js';

import { getNormalizedColSpans } from './get-normalized-col-spans.js';
import { getLayoutFillColor, resolveLayoutFill } from './layout-fill.js';
import { LAYOUT_DEFAULTS, normalizePadding } from './shared-with-viewer.js';

export const layoutConverter = definePmNodeConverter({
  toPm: {
    types: [Node_Type.LAYOUT],
    convert: (node, visit) => {
      const normalizedColSpans = getNormalizedColSpans(
        (node.nodes as LayoutCellNode[]).map(cell => cell.layoutCellData?.colSpan ?? 0)
      );
      const background = resolveLayoutFill(
        node.layoutData?.background,
        node.layoutData?.backgroundColor
      );
      const backdrop = resolveLayoutFill(node.layoutData?.backdrop, node.layoutData?.backdropColor);

      return {
        type: Node_Type.LAYOUT,
        attrs: {
          id: node.id,
          containerData: node.layoutData?.containerData,
          background,
          backdrop,
          backgroundColor: getLayoutFillColor(background) ?? LAYOUT_DEFAULTS.backgroundColor,
          backdropColor: getLayoutFillColor(backdrop) ?? LAYOUT_DEFAULTS.backdropColor,
          backgroundImage: node.layoutData?.backgroundImage ?? LAYOUT_DEFAULTS.backgroundImage,
          borderColor: node.layoutData?.borderColor ?? LAYOUT_DEFAULTS.borderColor,
          borderWidth: node.layoutData?.borderWidth ?? LAYOUT_DEFAULTS.borderWidth,
          borderRadius: node.layoutData?.borderRadius ?? LAYOUT_DEFAULTS.borderRadius,
          backdropImage: node.layoutData?.backdropImage ?? LAYOUT_DEFAULTS.backdropImage,
          backdropPaddingTop:
            node.layoutData?.backdropPaddingTop ?? LAYOUT_DEFAULTS.backdropPaddingTop,
          backdropPaddingBottom:
            node.layoutData?.backdropPaddingBottom ?? LAYOUT_DEFAULTS.backdropPaddingBottom,
          gap: node.layoutData?.gap ?? LAYOUT_DEFAULTS.gap,
          responsivenessBehaviour:
            node.layoutData?.responsivenessBehaviour ?? LAYOUT_DEFAULTS.responsivenessBehaviour,
          responsivenessBreakpoint:
            node.layoutData?.responsivenessBreakpoint ?? LAYOUT_DEFAULTS.responsivenessBreakpoint,
          cellPadding: normalizePadding(node.layoutData?.cellPadding, [
            ...LAYOUT_DEFAULTS.cellPadding,
          ]),
          cellVerticalAlignment:
            node.layoutData?.cellVerticalAlignment ?? LAYOUT_DEFAULTS.cellVerticalAlignment,
          designTarget: node.layoutData?.designTarget ?? LAYOUT_DEFAULTS.designTarget,
          banner: node.layoutData?.banner ?? LAYOUT_DEFAULTS.banner,
          animation: node.layoutData?.animation ?? null,
        },
        content: (node.nodes as LayoutCellNode[]).map((cell: LayoutCellNode, index: number) => {
          return {
            type: Node_Type.LAYOUT_CELL,
            attrs: {
              id: cell.id,
              colSpan: normalizedColSpans[index],
            },
            content: visit?.(cell) ?? [],
          };
        }),
      };
    },
  },
  fromPm: {
    types: [Node_Type.LAYOUT],
    convert: (node, visit) => {
      const { attrs = {} } = node;
      const {
        id,
        containerData,
        background,
        backdrop,
        backgroundColor,
        backgroundImage,
        borderColor,
        borderWidth,
        borderRadius,
        backdropColor,
        backdropImage,
        backdropPaddingTop,
        backdropPaddingBottom,
        gap,
        cellPadding,
        cellVerticalAlignment,
        responsivenessBehaviour,
        responsivenessBreakpoint,
        designTarget,
        banner,
        animation,
      } = attrs;

      const areAllColSpansSame = node.content?.every(
        cell => cell.attrs?.colSpan === node.content?.[0].attrs?.colSpan
      );

      const nodeToVisit = areAllColSpansSame
        ? {
            ...node,
            content: node.content?.map(cell => ({
              ...cell,
              ...('attrs' in cell ? { attrs: { ...cell.attrs, colSpan: undefined } } : {}),
            })),
          }
        : node;

      const resolvedBackground = resolveLayoutFill(background, backgroundColor);
      const resolvedBackdrop = resolveLayoutFill(backdrop, backdropColor);

      return {
        type: Node_Type.LAYOUT,
        id,
        layoutData: {
          containerData: Object.keys(containerData ?? {}).length ? containerData : undefined,
          background: resolvedBackground,
          backdrop: resolvedBackdrop,
          backgroundImage:
            backgroundImage === LAYOUT_DEFAULTS.backgroundImage ? undefined : backgroundImage,
          borderColor: borderColor === LAYOUT_DEFAULTS.borderColor ? undefined : borderColor,
          borderWidth: borderWidth === LAYOUT_DEFAULTS.borderWidth ? undefined : borderWidth,
          borderRadius: borderRadius === LAYOUT_DEFAULTS.borderRadius ? undefined : borderRadius,
          backdropImage:
            backdropImage === LAYOUT_DEFAULTS.backdropImage ? undefined : backdropImage,
          backdropPaddingTop:
            backdropPaddingTop === LAYOUT_DEFAULTS.backdropPaddingTop
              ? undefined
              : backdropPaddingTop,
          backdropPaddingBottom:
            backdropPaddingBottom === LAYOUT_DEFAULTS.backdropPaddingBottom
              ? undefined
              : backdropPaddingBottom,
          gap: gap === LAYOUT_DEFAULTS.gap ? undefined : gap,
          responsivenessBehaviour:
            responsivenessBehaviour === LAYOUT_DEFAULTS.responsivenessBehaviour
              ? undefined
              : responsivenessBehaviour,
          responsivenessBreakpoint:
            responsivenessBreakpoint === LAYOUT_DEFAULTS.responsivenessBreakpoint
              ? undefined
              : responsivenessBreakpoint,
          cellPadding:
            cellPadding?.length === 4 &&
            cellPadding?.every(
              (p: number, index: number) => p === LAYOUT_DEFAULTS.cellPadding[index]
            )
              ? undefined
              : cellPadding,
          cellVerticalAlignment:
            cellVerticalAlignment === LAYOUT_DEFAULTS.cellVerticalAlignment
              ? undefined
              : cellVerticalAlignment,
          designTarget: designTarget === LAYOUT_DEFAULTS.designTarget ? undefined : designTarget,
          banner: banner ?? undefined,
          ...(animation ? { animation } : {}),
        },
        nodes: visit?.(nodeToVisit) ?? [],
      };
    },
  },
});
