import { Add, AddSmall } from '@wix/wix-ui-icons-common/lazy';
import type { FC } from 'react';
import React, { useContext, useState } from 'react';

import { RicosContext } from './../../../ricos-context/index.js';
import {
  getIsModalOpen,
  useModalService,
  useModalState,
} from './../../../ricos-modals/modal-service-provider.js';
import type { IToolbarItem } from './../../../ricos-types/index.js';
import { DropdownButton } from './../../../_shared/dropdown-button.js';
import { DropdownModal } from './../../../_shared/dropdown-modal/dropdown-modal.js';
import { ListItemSelect } from './../../../_shared/list-item-select/list-item-select.js';

import {
  LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_AFTER_BUTTON,
  LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_BEFORE_BUTTON,
} from '../data-hooks.js';

const MODAL_ID = 'AddCellDropdown.modal';

interface Props {
  toolbarItem: IToolbarItem;
  dataHook?: string;
  attributes: {
    canAddLeftCell: boolean;
    canAddRightCell: boolean;
    disabled: boolean;
  };
}

export const AddCellDropdownButton: FC<Props> = ({ dataHook, toolbarItem }) => {
  const { t, isMobile } = useContext(RicosContext) || {};
  const modalService = useModalService();
  const isModalOpen = useModalState(getIsModalOpen(MODAL_ID));
  const [referenceElement, setReferenceElement] = useState<HTMLElement | null>(null);

  const onClick = (position: 'left' | 'right') => {
    toolbarItem.commands?.click({ position });
    closeModal();
  };

  const closeModal = () => modalService.closeModal(MODAL_ID);

  const openAddCellDropdownPanel = () => {
    const isModalOpen = modalService.isModalOpen(MODAL_ID);

    if (isModalOpen) {
      closeModal();
      return;
    }

    modalService.openModal({
      id: MODAL_ID,
      Component: AddCellPanel,
      componentProps: {
        onClick,
        closeModal,
        canAddLeftCell: toolbarItem.attributes.canAddLeftCell,
        canAddRightCell: toolbarItem.attributes.canAddRightCell,
      },
      layout: isMobile ? 'drawer' : 'floating',
      positioning: { referenceElement, placement: 'bottom' },
    });
  };

  return (
    <DropdownButton
      disabled={toolbarItem.attributes.disabled}
      dataHook={dataHook}
      active={isModalOpen}
      onClick={openAddCellDropdownPanel}
      ref={setReferenceElement}
      icon={Add}
      tooltip={t('Toolbar_AddCellDropdown_Tooltip')}
    />
  );
};

type AddCellPanelProps = {
  onClick: (position: 'left' | 'right') => void;
  canAddLeftCell: boolean;
  canAddRightCell: boolean;
  closeModal: () => void;
};

export const AddCellPanel: React.FC<AddCellPanelProps> = ({
  onClick,
  canAddLeftCell,
  canAddRightCell,
  closeModal,
}) => {
  const { t } = useContext(RicosContext) || {};

  const dropdownOptions = [
    <ListItemSelect
      key={LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_BEFORE_BUTTON}
      dataHook={LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_BEFORE_BUTTON}
      prefix={<AddSmall />}
      title={t('Toolbar_AddCellDropdown_AddBefore_Tooltip')}
      onSelect={() => onClick('left')}
      disabled={!canAddLeftCell}
    />,
    <ListItemSelect
      key={LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_AFTER_BUTTON}
      dataHook={LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_AFTER_BUTTON}
      prefix={<AddSmall />}
      title={t('Toolbar_AddCellDropdown_AddAfter_Tooltip')}
      onSelect={() => onClick('right')}
      disabled={!canAddRightCell}
    />,
  ];

  return (
    <DropdownModal
      options={dropdownOptions}
      title={t('Toolbar_AddCellDropdown_Tooltip')}
      onCloseButtonClick={closeModal}
    />
  );
};
