import classNames from 'classnames';

import type { ModalService } from './../../ricos-modals/index.js';
import { getHorizontalHandleIcon } from './../../_shared/drag-handle-icons.js';
import type { NodeViewRenderer, NodeViewRendererProps } from './../../tiptap/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';

import { LAYOUT_CELL_HANDLE } from './data-hooks.js';
import { setAttr, setChild, setClass } from './idempotent-dom.js';
import { isEditorOrModalActive } from './is-editor-or-modal-active.js';
import styles from './layouts-scss.js';

type CellNodeViewOptions = {
  modals?: ModalService;
};

export const cellNodeView =
  ({ modals }: CellNodeViewOptions): NodeViewRenderer =>
  ({ node, getPos, editor }) => {
    const cellElement = document.createElement('div');

    // Cell handle must be wrapped in a div with contenteditable=false to prevent setting selection inside contentElement
    // on pointerdown
    const cellHandleWrapper = document.createElement('div');
    cellHandleWrapper.setAttribute('contenteditable', 'false');

    const cellHandle = document.createElement('button');
    cellHandle.classList.add(styles.columnHandlerContainer);
    cellHandle.setAttribute('type', 'button');
    cellHandle.innerHTML = getHorizontalHandleIcon();

    cellHandleWrapper.append(cellHandle);

    const resizeHandleWrapper = document.createElement('div');
    resizeHandleWrapper.setAttribute('contenteditable', 'false');
    const resizeHandle = document.createElement('div');
    resizeHandle.classList.add(styles.resizeHandler);
    resizeHandleWrapper.append(resizeHandle);

    const contentElement = document.createElement('div');
    contentElement.setAttribute('data-layout-cell-content', '');
    contentElement.classList.add(styles.cellContent);

    cellElement.append(cellHandleWrapper, contentElement);

    updateCellView({
      cellElement,
      cellHandle,
      resizeHandle,
      resizeHandleWrapper,
      node,
      getPos,
      editor,
      modals,
    });

    cellHandle.addEventListener('click', event => {
      const cell = (event.target as HTMLElement)?.closest(`[data-layout-cell]`) as HTMLElement;
      const cellId = cell?.getAttribute('data-layout-cell');

      if (cellId) {
        editor.chain().selectCell(cellId).focus().run();
      }
    });

    const runCellUpdate = () =>
      updateCellView({
        cellElement,
        cellHandle,
        resizeHandle,
        resizeHandleWrapper,
        node,
        getPos,
        editor,
        modals,
      });

    const onFocus = () => {
      runCellUpdate();
    };

    const onBlur = ({ event }: { event: FocusEvent }) => {
      if (event.relatedTarget && cellElement.contains(event.relatedTarget as Node)) {
        return;
      }
      runCellUpdate();
    };

    editor.on('selectionUpdate', runCellUpdate);
    editor.on('focus', onFocus);
    editor.on('blur', onBlur);

    // Refresh chrome when a modal opens/closes — opening a settings modal blurs
    // the editor before the modal mount, and we want the selection to stay
    // visible while the modal is up. The modal service's pub/sub wiring is
    // attached after the editor is constructed, so defer to a microtask.
    let modalSubsCancelled = false;
    let modalSubs: { cancel: () => void }[] = [];
    queueMicrotask(() => {
      if (modalSubsCancelled || !modals) {
        return;
      }
      modalSubs = [modals.onModalOpened(runCellUpdate), modals.onModalClosed(runCellUpdate)];
    });

    return {
      dom: cellElement,
      contentDOM: contentElement,
      ignoreMutation: (mutation: MutationRecord | { type: 'selection'; target: Node }) => {
        // Ignore attribute mutations on the cell element itself (class changes from selection)
        const isMutatingCellAttribute =
          mutation.target === cellElement && mutation.type === 'attributes';
        // Ignore mutations to cell handle and resize handle wrappers (contenteditable=false decorations)
        const isMutatingCellHandleWrapper =
          mutation.target === cellHandleWrapper || mutation.target === cellHandle;
        const isMutatingResizeHandle =
          mutation.target === resizeHandleWrapper || mutation.target === resizeHandle;
        // Ignore childList mutations on cellElement (resize handle append/remove)
        const isMutatingCellChildren =
          mutation.target === cellElement && mutation.type === 'childList';

        return (
          isMutatingCellAttribute ||
          isMutatingCellHandleWrapper ||
          isMutatingResizeHandle ||
          isMutatingCellChildren
        );
      },
      update: (newNode: PmNode) => {
        if (newNode.type !== node.type) {
          return false;
        }
        // oxlint-disable-next-line no-param-reassign
        node = newNode;
        updateCellView({
          cellElement,
          cellHandle,
          resizeHandle,
          resizeHandleWrapper,
          node: newNode,
          getPos,
          editor,
          modals,
        });
        return true;
      },
      destroy: () => {
        editor.off('selectionUpdate', runCellUpdate);
        editor.off('focus', onFocus);
        editor.off('blur', onBlur);
        modalSubsCancelled = true;
        modalSubs.forEach(s => s.cancel());
      },
    };
  };

const updateCellView = ({
  cellElement,
  resizeHandle,
  resizeHandleWrapper,
  cellHandle,
  node,
  getPos,
  editor,
  modals,
}: Pick<NodeViewRendererProps, 'node' | 'getPos' | 'editor'> & {
  cellElement: HTMLDivElement;
  cellHandle: HTMLButtonElement;
  resizeHandle: HTMLDivElement;
  resizeHandleWrapper: HTMLDivElement;
  modals?: ModalService;
}) => {
  const { $to, $from } = editor.state.selection;
  const pos = getPos();

  if (pos === undefined) {
    return;
  }

  const isSelected =
    isEditorOrModalActive(editor.view, modals) &&
    pos === $from.pos &&
    pos + node.nodeSize === $to.pos;
  const isFirst = !editor.state.doc.resolve(pos).nodeBefore;

  setAttr(cellElement, 'data-layout-cell', node.attrs.id);
  setClass(
    cellElement,
    classNames({
      [styles.cell]: true,
      [styles.cellSelected]: isSelected,
    })
  );

  setAttr(cellHandle, 'data-layout-cell-handle', node.attrs.id);
  setAttr(cellHandle, 'data-hook', `${LAYOUT_CELL_HANDLE}-${node.attrs.id}`);
  setAttr(resizeHandle, 'data-layout-cell-resize-handle', node.attrs.id);

  setChild(cellElement, resizeHandleWrapper, !isFirst);
};
