import { TIPTAP_CARD_TYPE, TIPTAP_LAYOUT_TYPE } from './../../ricos-content/index.js';
import { findChildren } from './../../tiptap/index.js';
import type { Node as PmNode } from './../../tiptap/pm/model.js';
import type { EditorState } from './../../tiptap/pm/state.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';

const isBannerLayout = (node: PmNode): boolean =>
  node.type.name === TIPTAP_LAYOUT_TYPE && !!node.attrs?.banner;

type Position = 'TOP' | 'BOTTOM';

/**
 * Identifies the scope (doc or a specific CARD) that a banner layout
 * belongs to. Uniqueness is enforced *within* a scope: at most one
 * banner=TOP and one banner=BOTTOM per CARD (the CARD's schema already
 * caps this, but a stray banner LAYOUT inside CARD_CONTENT would slip
 * through), and at most one of each at doc level when no card wraps.
 */
const scopeForLayout = (doc: PmNode, layoutPos: number): string => {
  const $pos = doc.resolve(layoutPos);
  for (let depth = $pos.depth; depth > 0; depth--) {
    const ancestor = $pos.node(depth);
    if (ancestor.type.name === TIPTAP_CARD_TYPE) {
      return `card:${ancestor.attrs?.id ?? layoutPos}`;
    }
  }
  return 'doc';
};

/**
 * Strip `banner` attrs from duplicate banner LAYOUTs so each scope ends
 * with at most one TOP and one BOTTOM banner.
 *
 * Resolution rule when more than one exists in a scope:
 *  - TOP: keep the first in document order (banners belong at the start).
 *  - BOTTOM: keep the last in document order (footers belong at the end).
 *
 * The demoted ones become plain layouts in place — they don't move, just
 * lose their banner role. This is the same demotion the toolbar's
 * "set as banner / footer" toggle performs.
 */
const buildUniquenessTr = (state: EditorState) => {
  const banners = findChildren(state.doc, isBannerLayout);
  if (banners.length === 0) {
    return null;
  }

  // For each (scope, position) key, remember which banner to keep.
  // We walk twice — first collect candidates, then decide which to keep.
  type Candidate = { pos: number; position: Position };
  const byKey = new Map<string, Candidate[]>();

  for (const { node, pos } of banners) {
    const position = node.attrs?.banner?.position as Position | undefined;
    if (position !== 'TOP' && position !== 'BOTTOM') {
      continue;
    }
    const scope = scopeForLayout(state.doc, pos);
    const key = `${scope}:${position}`;
    const list = byKey.get(key) ?? [];
    list.push({ pos, position });
    byKey.set(key, list);
  }

  const toDemote: number[] = [];
  for (const [, candidates] of byKey) {
    if (candidates.length <= 1) {
      continue;
    }
    const position = candidates[0].position;
    // TOP keeps the first occurrence; BOTTOM keeps the last.
    const keepPos = position === 'TOP' ? candidates[0].pos : candidates[candidates.length - 1].pos;
    for (const candidate of candidates) {
      if (candidate.pos !== keepPos) {
        toDemote.push(candidate.pos);
      }
    }
  }

  if (toDemote.length === 0) {
    return null;
  }

  const tr = state.tr;
  for (const pos of toDemote) {
    const node = tr.doc.nodeAt(pos);
    if (node && isBannerLayout(node)) {
      tr.setNodeAttribute(pos, 'banner', null);
    }
  }
  return tr;
};

export const createBannerUniquenessPlugin = (): Plugin => {
  return new Plugin({
    key: new PluginKey('banner-uniqueness'),
    appendTransaction: (_, oldState, newState) => {
      if (newState.doc.eq(oldState.doc)) {
        return;
      }
      return buildUniquenessTr(newState);
    },
    // Initial doc may already contain duplicate banners (e.g., from a
    // converter or external content) — sweep on mount so the very first
    // user action sees a normalized doc.
    view(editorView) {
      const tr = buildUniquenessTr(editorView.state);
      if (tr) {
        editorView.dispatch(tr);
      }
      return {};
    },
  });
};
