import {
  Add,
  ArrowLeft,
  ArrowLeftSmall,
  ArrowRight,
  ArrowRightSmall,
} from '@wix/wix-ui-icons-common/lazy';
import React, { useContext } from 'react';

import { TIPTAP_LAYOUT_CELL_TYPE } from './../../ricos-content/index.js';
import { RicosContext } from './../../ricos-context/index.js';
import type { EditorPlugin, IToolbarItem, RicosServices } from './../../ricos-types/index.js';
import { RicosPluginToolbarNames } from './../../ricos-types/index.js';
import { createDeleteButton } from './../../_shared/plugin-toolbar/create-delete-button.js';
import { createSeparator } from './../../_shared/plugin-toolbar/separator/create-separator.js';
import { getNodeInSelection } from './../../_shared/resolvers/get-node-in-selection.js';
import { isAlwaysVisible } from './../../_shared/resolvers/is-always-visible.js';
import { ToolbarButton } from './../../_shared/toolbar-button/toolbar-button.js';
import { NodeSelection } from './../../tiptap/pm/state.js';

import { cellConverter } from './cell-converter.js';
import { cellExtension } from './cell-extension.js';
import {
  LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_BUTTON,
  LAYOUT_CELL_TOOLBAR_MOVE_LEFT_BUTTON,
  LAYOUT_CELL_TOOLBAR_MOVE_RIGHT_BUTTON,
} from './data-hooks.js';
import { getToolbarReferenceElement, type LayoutEditorConfig } from './shared.js';
import { AddCellDropdownButton } from './toolbar-buttons/add-cell-dropdown-button.js';

export const pluginCell = (
  config: LayoutEditorConfig = { showInQuickActions: false, showInToolbars: false }
): EditorPlugin => ({
  type: TIPTAP_LAYOUT_CELL_TYPE,
  config,
  pmMarkConverters: [],
  pmNodeConverters: [cellConverter],
  tiptapExtensions: [cellExtension],
  toolbar: {
    names: [RicosPluginToolbarNames.LAYOUT_CELL],
    resolveReferenceElement: tiptapEditor => getToolbarReferenceElement(tiptapEditor),
    getButtons: (_, services: RicosServices) =>
      services.context.isMobile
        ? []
        : config.showInQuickActions || config.showInToolbars
          ? [
              {
                id: 'layoutCellAddCellDropdown',
                type: 'toggle',
                dataHook: LAYOUT_CELL_TOOLBAR_ADD_CELL_DROPDOWN_BUTTON,
                tooltip: 'Layouts_AddCell_Tooltip',
                icon: Add,
                command: ({ position, tiptapEditor, attributes: { selectedNode } }: any) => {
                  if (position === 'left') {
                    tiptapEditor.commands.addCellLeft(selectedNode.attrs.id);
                  } else {
                    tiptapEditor.commands.addCellRight(selectedNode.attrs.id);
                  }
                },
                attributes: {
                  selectedNode: getNodeInSelection,
                  alwaysVisible: isAlwaysVisible,
                  canAddLeftCell: (_, __, editor) => {
                    const selection = editor?.state.selection;
                    if (editor && selection instanceof NodeSelection) {
                      const id = selection.node?.attrs.id;
                      return editor.can().addCellLeft(id);
                    }
                    return false;
                  },
                  canAddRightCell: (_, __, editor) => {
                    const selection = editor?.state.selection;
                    if (editor && selection instanceof NodeSelection) {
                      const id = selection.node?.attrs.id;
                      return editor.can().addCellRight(id);
                    }
                    return false;
                  },
                  disabled: (_, __, editor) => {
                    const selection = editor?.state.selection;
                    if (editor && selection instanceof NodeSelection) {
                      const id = selection.node?.attrs.id;
                      return !editor.can().addCellLeft(id) && !editor.can().addCellRight(id);
                    }
                    return true;
                  },
                },
                renderer: toolbarItem => (
                  <AddCellDropdownButton
                    toolbarItem={toolbarItem}
                    attributes={toolbarItem.attributes as any}
                  />
                ),
              },
              {
                id: 'moveCellLeft',
                type: 'toggle',
                dataHook: LAYOUT_CELL_TOOLBAR_MOVE_LEFT_BUTTON,
                tooltip: 'Layouts_CellMoveLeft_Tooltip',
                icon: ArrowLeft,
                attributes: {
                  alwaysVisible: isAlwaysVisible,
                  disabled: (_, __, editor) => {
                    const selection = editor?.state.selection;
                    if (editor && selection instanceof NodeSelection) {
                      const id = selection.node?.attrs.id;
                      return !editor.can().moveCellLeft(id);
                    }
                    return true;
                  },
                  selectedNode: getNodeInSelection,
                },
                command: ({ tiptapEditor, attributes }) => {
                  tiptapEditor.commands.moveCellLeft(attributes.selectedNode.attrs.id);
                },
                renderer: toolbarItem => <MoveCellLeftButton toolbarItem={toolbarItem} />,
              },
              {
                id: 'moveCellRight',
                type: 'toggle',
                dataHook: LAYOUT_CELL_TOOLBAR_MOVE_RIGHT_BUTTON,
                tooltip: 'Layouts_CellMoveRight_Tooltip',
                icon: ArrowRight,
                attributes: {
                  selectedNode: getNodeInSelection,
                  alwaysVisible: isAlwaysVisible,
                  disabled: (_, __, editor) => {
                    const selection = editor?.state.selection;
                    if (editor && selection instanceof NodeSelection) {
                      const id = selection.node?.attrs.id;
                      return !editor.can().moveCellRight(id);
                    }
                    return true;
                  },
                },
                command: ({ tiptapEditor, attributes }) => {
                  tiptapEditor.commands.moveCellRight(attributes.selectedNode.attrs.id);
                },
                renderer: toolbarItem => <MoveCellRightButton toolbarItem={toolbarItem} />,
              },
              createSeparator(),
              createDeleteButton({
                tooltip: 'Layouts_CellDelete_Tooltip',
                attributes: {
                  selectedNode: getNodeInSelection,
                },
                command: ({ tiptapEditor, attributes }) => {
                  tiptapEditor.commands.deleteCell(attributes.selectedNode.attrs.id);
                },
              }),
            ]
          : [],
  },
});

const MoveCellLeftButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  return (
    <ToolbarButton
      prefix={ArrowLeftSmall}
      onClick={() => {
        // @ts-expect-error
        toolbarItem.tiptapEditor.commands.moveCellLeft(
          toolbarItem.attributes.selectedNode.attrs.id
        );
      }}
      dataHook={LAYOUT_CELL_TOOLBAR_MOVE_LEFT_BUTTON}
      tooltip={t('Layouts_CellMoveLeft_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

const MoveCellRightButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  return (
    <ToolbarButton
      prefix={ArrowRightSmall}
      onClick={() => {
        // @ts-expect-error
        toolbarItem.tiptapEditor.commands.moveCellRight(
          toolbarItem.attributes.selectedNode.attrs.id
        );
      }}
      dataHook={LAYOUT_CELL_TOOLBAR_MOVE_RIGHT_BUTTON}
      tooltip={t('Layouts_CellMoveRight_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};
