import {
  TIPTAP_CARD_FOOTER_TYPE,
  TIPTAP_CARD_HEADER_TYPE,
  TIPTAP_LAYOUT_CELL_TYPE,
  TIPTAP_LAYOUT_TYPE,
} from './../../ricos-content/index.js';
import { findChildren } from './../../tiptap/index.js';
import type { Node as ProseMirrorNode, ResolvedPos } from './../../tiptap/pm/model.js';
import { Plugin, PluginKey } from './../../tiptap/pm/state.js';

const bannerDropPreventionPluginKey = new PluginKey('banner-drop-prevention');

type BannerOriginalSnapshot = {
  id: string;
  position: 'TOP' | 'BOTTOM' | undefined;
  wasValid: boolean;
};

const isBannerLayout = (node: ProseMirrorNode): boolean =>
  node.type.name === TIPTAP_LAYOUT_TYPE && !!node.attrs?.banner;

/**
 * The locations a banner layout may legitimately occupy. Used by
 * `filterTransaction` to reject transactions that move a banner away from
 * its allowed slot. CARD_HEADER / CARD_FOOTER slots are also schema-pinned
 * by CARD's content rule (`CARD_HEADER? CARD_CONTENT CARD_FOOTER?`).
 */
const isValidBannerLocation = (
  newNode: ProseMirrorNode,
  $pos: ResolvedPos,
  position: 'TOP' | 'BOTTOM' | undefined
): boolean => {
  // Master shipped legacy top banners as `banner: { origin }` without an
  // explicit position; treat the missing position as TOP.
  const effective = position ?? 'TOP';
  const parentType = $pos.parent.type.name;

  if (effective === 'TOP') {
    if (parentType === TIPTAP_CARD_HEADER_TYPE) {
      return true;
    }
    // Doc-level top banner — must remain the doc's first child.
    if ($pos.depth === 0 && $pos.doc.firstChild === newNode) {
      return true;
    }
    return false;
  }

  // BOTTOM
  if (parentType === TIPTAP_CARD_FOOTER_TYPE) {
    return true;
  }
  // Doc-level BOTTOM banners can't be reliably enforced because the
  // trailing-node extension parks an empty paragraph after the banner.
  // Fall back to the schema and drag/dragstart handlers above.
  return true;
};

/**
 * Checks if the resolved position is immediately before the first cell of a top banner layout
 */
export const isBeforeFirstBannerCell = ($pos: ResolvedPos): boolean => {
  const nodeAfter = $pos.nodeAfter;
  return (
    nodeAfter?.type.name === TIPTAP_LAYOUT_CELL_TYPE &&
    $pos.parent.attrs?.banner?.position === 'TOP' &&
    $pos.index() === 0
  );
};

/**
 * Checks if the resolved position is immediately after the last cell of a bottom banner layout
 */
export const isAfterLastFooterCell = ($pos: ResolvedPos): boolean => {
  const nodeBefore = $pos.nodeBefore;
  return (
    nodeBefore?.type.name === TIPTAP_LAYOUT_CELL_TYPE &&
    $pos.parent.attrs?.banner?.position === 'BOTTOM' &&
    $pos.index() === $pos.parent.childCount
  );
};

/**
 * Checks if the drop position is at the start of the document and the first node is a top banner
 */
const isDropBeforeTopBanner = ($pos: ResolvedPos): boolean => {
  const doc = $pos.doc;
  const firstChild = doc.firstChild;

  if (
    firstChild?.type.name === TIPTAP_LAYOUT_TYPE &&
    firstChild.attrs?.banner?.position === 'TOP'
  ) {
    if ($pos.pos <= 1) {
      return true;
    }
  }

  return false;
};

/**
 * Checks if the drop position is at the end of the document and the last node is a bottom banner
 */
const isDropAfterBottomBanner = ($pos: ResolvedPos): boolean => {
  const doc = $pos.doc;
  const lastChild = doc.lastChild;

  if (
    lastChild?.type.name === TIPTAP_LAYOUT_TYPE &&
    lastChild.attrs?.banner?.position === 'BOTTOM'
  ) {
    if ($pos.pos >= doc.content.size - 1) {
      return true;
    }
  }

  return false;
};

/**
 * Plugin that prevents nodes from being dropped before a top banner layout
 * and prevents the banner itself from being moved.
 *
 * Note: Keyboard/text/paste handling before banner is unnecessary because
 * GapCursor.valid() in gap-cursor-selection.ts already prevents cursor
 * placement before top banner layouts.
 */
export const createBannerDropPreventionPlugin = (): Plugin => {
  return new Plugin({
    key: bannerDropPreventionPluginKey,
    props: {
      handleDrop: (view, event) => {
        if (!event) {
          return false;
        }

        const coordinates = view.posAtCoords({
          left: event.clientX,
          top: event.clientY,
        });

        if (!coordinates) {
          return false;
        }

        try {
          const $pos = view.state.doc.resolve(coordinates.pos);

          // Prevent dropping before the first cell inside a top banner layout
          if (isBeforeFirstBannerCell($pos)) {
            event.preventDefault();
            return true;
          }

          // Prevent dropping after the last cell inside a bottom banner layout
          if (isAfterLastFooterCell($pos)) {
            event.preventDefault();
            return true;
          }

          // Prevent dropping anything above/before the top banner
          if (isDropBeforeTopBanner($pos)) {
            event.preventDefault();
            return true;
          }

          // Prevent dropping anything below/after the bottom banner
          if (isDropAfterBottomBanner($pos)) {
            event.preventDefault();
            return true;
          }
        } catch {
          return false;
        }

        return false;
      },

      // Block dragstart on banner layout chrome and cell shells/handles; allow
      // prose and inner nodes inside [data-layout-cell-content]. #text targets
      // are resolved via parentElement (see cell-node-view.ts DOM structure).
      handleDOMEvents: {
        dragstart: (_view, event) => {
          const raw = event.target;
          const element =
            raw instanceof Element ? raw : raw instanceof Text ? raw.parentElement : null;
          if (!element?.closest('[data-layout-banner]')) {
            return false;
          }

          if (element.closest('[data-layout-cell-content]')) {
            return false;
          }

          event.preventDefault();
          return true;
        },
      },
    },

    // Filter transactions to prevent banner movement (but allow deletion).
    //
    // Walks the original doc's descendants for all banner LAYOUTs (not just
    // doc.firstChild / doc.lastChild) so banners nested inside CARD_HEADER /
    // CARD_FOOTER are protected symmetrically with legacy doc-level banners.
    //
    // For each banner that still exists in the new doc with its banner attr
    // intact, the new location must be one of:
    //   - inside `CARD_HEADER` (TOP) or `CARD_FOOTER` (BOTTOM) — the schema
    //     pins these slots at the card's first/last child;
    //   - the doc-level first child (legacy doc-level TOP banner).
    // Demoted banners (banner attr cleared) are allowed anywhere — the
    // demote-then-re-insert flow used by `/banner` and `setLayoutBanner`
    // relies on this.
    filterTransaction: (tr, state) => {
      if (!tr.docChanged) {
        return true;
      }

      const originalBanners: BannerOriginalSnapshot[] = findChildren(state.doc, isBannerLayout).map(
        ({ node, pos }) => {
          const position = node.attrs.banner?.position as 'TOP' | 'BOTTOM' | undefined;

          return {
            id: node.attrs.id,
            position,
            wasValid: isValidBannerLocation(node, state.doc.resolve(pos), position),
          };
        }
      );

      for (const original of originalBanners) {
        // Documents authored outside the editor (AI services, converters) can arrive
        // with a banner already outside its allowed slot. Enforcing the slot on those
        // would reject every transaction and leave the document permanently
        // uneditable, so only banners that started out valid are held in place.
        if (!original.wasValid) {
          continue;
        }
        const inNewDoc = findChildren(tr.doc, n => n.attrs?.id === original.id)[0];
        if (!inNewDoc) {
          continue;
        }
        // `isBannerLayout` returns false when the banner attr was cleared
        // (the demote path); in that case the layout can land anywhere.
        if (!isBannerLayout(inNewDoc.node)) {
          continue;
        }
        const $newPos = tr.doc.resolve(inNewDoc.pos);
        if (!isValidBannerLocation(inNewDoc.node, $newPos, original.position)) {
          return false;
        }
      }

      return true;
    },
  });
};
