const isBannerLayoutNode = (node?: ProseMirrorNode) =>
  node?.type.name === TIPTAP_LAYOUT_TYPE && !!node.attrs?.banner;

const isEmptyTextBlock = (node: ProseMirrorNode) => node.isTextblock && node.content.size === 0;

/**
 * Walk doc.content from the matching edge (TOP = forwards from start,
 * BOTTOM = backwards from end). Skip over empty paragraphs the trailing-node
 * extension parks at the edges. Returns the first banner layout encountered,
 * or `null` if a non-banner block appears first.
 */
const findEdgeBannerInDoc = (
  doc: ProseMirrorNode,
  isTop: boolean
): { node: ProseMirrorNode; pos: number } | null => {
  const children: { node: ProseMirrorNode; pos: number }[] = [];
  doc.forEach((node, pos) => children.push({ node, pos }));
  const ordered = isTop ? children : children.reverse();
  for (const { node, pos } of ordered) {
    if (isEmptyTextBlock(node)) {
      continue;
    }
    return isBannerLayoutNode(node) ? { node, pos } : null;
  }
  return null;
};

/**
 * Insertion position for a doc-level BOTTOM banner. Sits just before any
 * trailing empty paragraphs so the trailing-node extension can keep parking
 * its empty P at the very end without ending up between two banners.
 */
const findBottomInsertionPos = (doc: ProseMirrorNode): number => {
  let pos = doc.content.size;
  const children: { node: ProseMirrorNode; pos: number }[] = [];
  doc.forEach((node, p) => children.push({ node, pos: p }));
  for (let i = children.length - 1; i >= 0; i--) {
    if (isEmptyTextBlock(children[i].node)) {
      pos = children[i].pos;
    } else {
      break;
    }
  }
  return pos;
};

const createRegularLayoutNode = (node: ProseMirrorNode) => {
  const { banner: _banner, ...attrs } = node.attrs;

  return {
    type: TIPTAP_LAYOUT_TYPE,
    attrs,
    content: node.content.toJSON(),
  };
};

const insertQuickActionBanner = (position: 'TOP' | 'BOTTOM') => (editor: Editor) => {
  const isTop = position === 'TOP';
  const wrapperType = isTop ? TIPTAP_CARD_HEADER_TYPE : TIPTAP_CARD_FOOTER_TYPE;

  editor
    .chain()
    .focus()
    .command(({ tr, dispatch, state }) => {
      const { headingId, layoutNode } = createQuickActionBannerLayout(position);
      const cardId = findParentCardId(tr.doc, tr.selection.from);

      if (cardId) {
        // Inside a card, banners live in CARD_HEADER / CARD_FOOTER (dedicated
        // PM children of CARD that each wrap a single LAYOUT). Wrap the new
        // layout in the right slot and replace any existing one, or insert a
        // fresh slot at CARD's start (TOP) / end (BOTTOM).
        const card = findNodeById(tr, cardId)[0];
        if (!card) {
          return false;
        }

        const newWrapper = state.schema.nodeFromJSON({
          type: wrapperType,
          content: [layoutNode],
        });

        let existingPos = -1;
        let existingSize = -1;
        card.node.forEach((child, offset) => {
          if (child.type.name === wrapperType && existingPos < 0) {
            existingPos = card.pos + 1 + offset;
            existingSize = child.nodeSize;
          }
        });

        if (existingPos >= 0) {
          tr.replaceWith(existingPos, existingPos + existingSize, newWrapper);
        } else {
          const insertPos = isTop ? card.pos + 1 : card.pos + card.node.nodeSize - 1;
          tr.insert(insertPos, newWrapper);
        }
      } else {
        // No parent card: keep the legacy doc-level banner behavior —
        // demote any existing edge banner into a regular layout, then
        // insert the new banner at doc top (TOP) / bottom (BOTTOM). The
        // trailing-node extension may park an empty paragraph at doc
        // end, so walk doc.content from the matching edge past empty
        // paragraphs to find the actual edge banner (if any).
        const edge = findEdgeBannerInDoc(tr.doc, isTop);
        const demotedBanner = edge ? createRegularLayoutNode(edge.node) : undefined;

        // Capture the insertion point relative to the pre-delete doc so
        // the new banner ends up at the same edge (and inside any
        // trailing/leading empty paragraphs the auto-node extension
        // parks there). Map through tr.mapping after the delete.
        const preDeleteInsertPos = isTop ? 0 : findBottomInsertionPos(tr.doc);

        if (edge && demotedBanner) {
          tr.deleteRange(edge.pos, edge.pos + edge.node.nodeSize);
        }
        const nodesToInsert = isTop
          ? [layoutNode, ...(demotedBanner ? [demotedBanner] : [])]
          : [...(demotedBanner ? [demotedBanner] : []), layoutNode];
        const fragment = Fragment.fromArray(
          nodesToInsert.map(node => state.schema.nodeFromJSON(node))
        );
        tr.insert(tr.mapping.map(preDeleteInsertPos), fragment);
      }

      const headingNode = findNodeById(tr, headingId)[0];
      if (headingNode) {
        tr.setSelection(TextSelection.create(tr.doc, headingNode.pos + 1));
      }

      if (dispatch) {
        dispatch(tr.scrollIntoView());
      }

      return true;
    })
    .run();
};

export const pluginLayout = (
  config: LayoutEditorConfig = {
    showInQuickActions: false,
    showInToolbars: false,
  }
): EditorPlugin => ({
  type: TIPTAP_LAYOUT_TYPE,
  config,
  pmMarkConverters: [],
  pmNodeConverters: [layoutConverter],
  tiptapExtensions: [layoutExtension],
  textButtons: [],
  toolbar: {
    names: [RicosPluginToolbarNames.LAYOUT],
    isVisible: isToolbarVisible,
    resolveReferenceElement: tiptapEditor => getToolbarReferenceElement(tiptapEditor),
    getButtons: (_, services: RicosServices) => [
      createSettingsButton({
        modalId: LAYOUT_SETTINGS_MODAL_ID,
        showLabel: true,
        attributes: {
          selectedNode: selectedNodeResolver,
        },
        command: ({ isMobile, referenceElement, attributes: { selectedNode } }) => {
          services.modals?.togglePluginPanel({
            id: LAYOUT_SETTINGS_MODAL_ID,
            Component: Settings,
            componentProps: {
              referenceElement: referenceElement!,
              nodeId: selectedNode.attrs.id,
              config,
            },
            positioning: {
              referenceElement:
                referenceElement!.closest(`[data-hook~=${FLOATING_PLUGIN_TOOLBAR}]`) ??
                referenceElement,
              placement: 'right-start',
            },
            onClickOutside: {
              on: 'pointerup',
              handler: () => {},
            },
            focusReturnElement: referenceElement,
            isMobile,
          });
        },
        buttonId: 'layoutSettings',
      }),
      createSeparator(),
      {
        id: 'layoutSetAsBanner',
        type: 'toggle',
        tooltip: null,
        label: 'Layouts_LayoutSetAsBanner_Tooltip',
        icon: Banner,
        attributes: {
          selectedNode: selectedNodeResolver,
          visible: canSetAsBanner,
          active: isLayoutSetAsBannerActive,
        },
        dataHook: PLUGIN_TOOLBAR_SET_AS_HEADER_BUTTON,
        renderer: toolbarItem => <LayoutSetAsHeaderButton toolbarItem={toolbarItem} />,
        command: ({ tiptapEditor, attributes: { selectedNode } }) => {
          const isTopBanner = selectedNode?.attrs?.banner?.position === 'TOP';
          tiptapEditor.commands.setLayoutBanner(
            selectedNode.attrs.id,
            isTopBanner ? undefined : { position: 'TOP', origin: 'LAYOUT' }
          );
        },
      },
      {
        id: 'layoutSetAsFooter',
        type: 'toggle',
        tooltip: null,
        label: 'Layouts_LayoutSetAsFooter_Tooltip',
        icon: Footer,
        attributes: {
          selectedNode: selectedNodeResolver,
          visible: canSetAsFooter,
          active: isLayoutSetAsFooterActive,
        },
        dataHook: PLUGIN_TOOLBAR_SET_AS_FOOTER_BUTTON,
        renderer: toolbarItem => <LayoutSetAsFooterButton toolbarItem={toolbarItem} />,
        command: ({ tiptapEditor, attributes: { selectedNode } }) => {
          const isBottomBanner = selectedNode?.attrs?.banner?.position === 'BOTTOM';
          tiptapEditor.commands.setLayoutBanner(
            selectedNode.attrs.id,
            isBottomBanner ? undefined : { position: 'BOTTOM', origin: 'LAYOUT' }
          );
        },
      },
      createPluginToolbarButton({
        id: 'layoutVerticalAlignment',
        type: 'dropdown',
        tooltip: 'Layouts_LayoutCellVerticalAlignment_Tooltip',
        dataHook: LAYOUT_TOOLBAR_VERTICAL_ALIGNMENT_BUTTON,
        Component: VerticalAlignmentDropdown,
        getComponentProps: ({ tiptapEditor, modals, attributes }) => {
          return {
            onSelect: verticalAlignment => {
              tiptapEditor
                .chain()
                .focus()
                .setLayoutCellsVerticalAlignment(
                  attributes.selectedNode.attrs.id,
                  verticalAlignment
                )
                .run();
            },
            dropdownOptions: Object.values(VERTICAL_ALIGNMENT_BUTTONS).map(item => ({
              id: item.commandKey,
              dataHook: item.dataHook,
              label: services.t(item.tooltip),
              icon: item.iconSmall,
              iconMobile: item.icon,
            })),
            closeModal: () => modals.closeModal(VERTICAL_ALIGNMENT_MODAL_ID),
            selectedId:
              attributes.selectedNode.attrs.cellVerticalAlignment ||
              LAYOUT_DEFAULTS.cellVerticalAlignment,
          };
        },
        command: ({
          tiptapEditor,
          modals,
          referenceElement,
          attributes,
          getComponentProps,
          publicCommands,
        }) => {
          const closeModal = () => modals.closeModal(VERTICAL_ALIGNMENT_MODAL_ID);
          const isModalOpen = modals.isModalOpen(VERTICAL_ALIGNMENT_MODAL_ID);

          if (isModalOpen) {
            closeModal();
            return;
          }

          const componentProps = getComponentProps?.({
            tiptapEditor,
            attributes,
            publicCommands,
            t: services.t,
            modals,
            languageDir: services.context.languageDir,
          });

          if (!componentProps) {
            return;
          }

          modals.openModal({
            id: VERTICAL_ALIGNMENT_MODAL_ID,
            Component: VerticalAlignmentDropdown,
            componentProps,
            layout: services.context.isMobile ? 'drawer' : 'floating',
            positioning: { referenceElement, placement: 'bottom' },
          });
        },
        attributes: {
          selectedNode: selectedNodeResolver,
          verticalAlignment: getVerticalAlignmentResolver,
        },
        renderer: toolbarItem => <VerticalAlignmentButton toolbarItem={toolbarItem} />,
        getIcon: ({ attributes }) => {
          const verticalAlignment: 'TOP' | 'MIDDLE' | 'BOTTOM' =
            attributes.selectedNode.attrs?.cellVerticalAlignment ||
            LAYOUT_DEFAULTS.cellVerticalAlignment;
          return verticalAlignmentIcons[verticalAlignment];
        },
      }),
      {
        id: 'addCellToTheEnd',
        type: 'toggle',
        dataHook: LAYOUT_PLUGIN_TOOLBAR_ADD_CELL_BUTTON,
        tooltip: 'Layouts_LayoutAddCell_Tooltip',
        icon: Add,
        attributes: {
          selectedNode: selectedNodeResolver,
          alwaysVisible: isAlwaysVisible,
          disabled: (_, __, editor) => {
            const selection = editor?.state?.selection;
            if (!selection) {
              return true;
            }
            const closest =
              selection instanceof NodeSelection && selection.node?.type.name === TIPTAP_LAYOUT_TYPE
                ? selection
                : findParentNodeClosestToPos(
                    selection.$from,
                    node => node.type.name === TIPTAP_LAYOUT_TYPE
                  );

            return closest?.node.lastChild && editor
              ? !editor.can().addCellRight(closest.node.lastChild.attrs.id)
              : true;
          },
        },
        command: ({ tiptapEditor, attributes: { selectedNode } }) => {
          tiptapEditor.commands.addCellRight(selectedNode.lastChild.attrs.id);
        },
        renderer: toolbarItem => <AddCellButton toolbarItem={toolbarItem} />,
      },
      // the layout toolbar also shows for text selections inside the layout —
      // resolve the layout like the other buttons, not just NodeSelections
      createAnimationButton(services, selectedNodeResolver),
      createSeparator(),
      createDeleteButton({
        tooltip: 'Layouts_LayoutDelete_Tooltip',
        attributes: {
          selectedNode: selectedNodeResolver,
        },
        command: ({ tiptapEditor, attributes }) => {
          const layoutId = attributes.selectedNode.attrs.id;
          const layoutWithPos = findNodeById(tiptapEditor.state.tr, layoutId)[0];
          if (!layoutWithPos) {
            return;
          }

          const $layoutPos = tiptapEditor.state.doc.resolve(layoutWithPos.pos);
          const parentTypeName = $layoutPos.parent.type.name;
          const isInCardWrapper =
            parentTypeName === TIPTAP_CARD_HEADER_TYPE ||
            parentTypeName === TIPTAP_CARD_FOOTER_TYPE;

          if (isInCardWrapper) {
            // CARD_HEADER/CARD_FOOTER schema requires exactly one LAYOUT child,
            // so deleting just the layout would leave PM to auto-fill an empty
            // layout. Delete the wrapper itself instead.
            const wrapperFrom = $layoutPos.before($layoutPos.depth);
            const wrapperTo = $layoutPos.after($layoutPos.depth);
            tiptapEditor
              .chain()
              .focus()
              .command(({ tr }) => {
                tr.delete(wrapperFrom, wrapperTo);
                return true;
              })
              .run();
            return;
          }

          tiptapEditor.commands.deleteNode(layoutId);
        },
      }),
    ],
  },
  getAddButtons: (_config, services) =>
    config.showInToolbars
      ? [
          {
            id: `${TIPTAP_LAYOUT_TYPE}.insert`,
            label: INSERT_PLUGIN_BUTTONS.LAYOUT,
            dataHook: INSERT_LAYOUT_BUTTON,
            icon: LayoutThreeColumns,
            tooltip: 'Layout_InsertButton_Tooltip',
            toolbars: toolbarsToAddIn,
            command: ({ referenceElement }) => {
              services.modals?.togglePluginPanel({
                id: LAYOUT_INSERT_MODAL_ID,
                Component: LayoutInsertModal,
                componentProps: {},
                isMobile: services.context.isMobile,
                positioning: {
                  referenceElement,
                  placement: 'bottom',
                },
                mobileLayout: 'drawer',
              });

              return true;
            },
            menuConfig: {
              tags: 'Layout_InsertButton',
              group: 'basic',
            },
          },
        ]
      : [],
  getQuickActions: ({ pluginServices }) =>
    config.showInQuickActions
      ? [
          {
            id: 'banner',
            title: 'QuickActionsPlugin_ActionTitle_Banner',
            tags: ['header', 'banner', 'cover', 'layout'],
            icon: Banner,
            section: quickActionsModalSections.FormatLayout,
            command: ({ editor }) => {
              insertQuickActionBanner('TOP')(editor);
            },
          },
          {
            id: 'footer',
            title: 'QuickActionsPlugin_ActionTitle_Footer',
            tags: ['footer', 'banner', 'layout'],
            icon: Footer,
            section: quickActionsModalSections.FormatLayout,
            isVisible: editor => !!editor.state.schema.nodes[TIPTAP_CARD_TYPE],
            command: ({ editor }) => {
              insertQuickActionBanner('BOTTOM')(editor);
            },
          },
          {
            id: 'twoColumns',
            title: 'QuickActionsPlugin_ActionTitle_TwoColumns',
            tags: ['layout', 'grid', 'cell'],
            icon: pluginServices?.context.isMobile ? LayoutTwoColumns : LayoutTwoColumnsSmall,
            section: quickActionsModalSections.FormatLayout,
            command: ({ publicCommands }) => {
              publicCommands.insertBlockWithBlankLines(
                RICOS_LAYOUT_TYPE,
                createBlankLayoutData(2),
                {
                  updateSelection: 'text',
                  skipBlankLineBefore: false,
                  skipBlankLineAfter: false,
                }
              );
            },
          },
          {
            id: 'threeColumns',
            title: 'QuickActionsPlugin_ActionTitle_ThreeColumns',
            tags: ['layout', 'grid', 'cell'],
            icon: pluginServices?.context.isMobile ? LayoutThreeColumns : LayoutThreeColumnsSmall,
            section: quickActionsModalSections.FormatLayout,
            command: ({ publicCommands }) => {
              publicCommands.insertBlockWithBlankLines(
                RICOS_LAYOUT_TYPE,
                createBlankLayoutData(3),
                {
                  updateSelection: 'text',
                  skipBlankLineBefore: false,
                  skipBlankLineAfter: false,
                }
              );
            },
          },
          {
            id: 'layoutPresets',
            title: 'QuickActionsPlugin_ActionTitle_Presets',
            tags: ['layout', 'grid', 'cell', 'presets'],
            icon: pluginServices?.context.isMobile ? Catalog : CatalogSmall,
            section: quickActionsModalSections.FormatLayout,
            command: ({ editor, referenceElement }) => {
              const isMobile = pluginServices.context.isMobile;
              pluginServices.modals?.togglePluginPanel({
                id: LAYOUT_INSERT_MODAL_ID,
                Component: LayoutInsertModal,
                componentProps: {},
                isMobile,
                positioning: {
                  referenceElement: referenceElement ?? {
                    getBoundingClientRect: () =>
                      posToDOMRect(
                        editor.view,
                        editor.view.state.selection.from,
                        editor.view.state.selection.to
                      ),
                  },
                  placement: isMobile ? 'bottom' : 'bottom-start',
                },
                mobileLayout: 'drawer',
              });
            },
          },
        ]
      : [],
});

const getVerticalAlignmentResolver: Resolver<string | undefined> = content => {
  if (Array.isArray(content) && content.length > 0) {
    const cellNode = content.find(node => node.type.name === TIPTAP_LAYOUT_TYPE);

    return cellNode?.attrs?.cellVerticalAlignment;
  }
  return undefined;
};

const selectedNodeResolver: Resolver<ProseMirrorNode | undefined> = (_, __, editor) => {
  if (!editor) {
    return undefined;
  }
  const { selection } = editor.state;
  const node = selection instanceof NodeSelection ? selection.node : undefined;
  const closest = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_LAYOUT_TYPE
  );
  if (closest || node) {
    return closest?.node ?? node;
  }
  return undefined;
};

// Active iff the *selected* layout carries the matching banner attribute.
// Scoped to selection (not doc-wide) so toggles don't light up across cards.
const isLayoutSetAsBannerActive: Resolver<boolean> = (content, services, editor) => {
  const node = selectedNodeResolver(content, services, editor) as ProseMirrorNode | undefined;
  return node?.attrs?.banner?.position === 'TOP';
};

const isLayoutSetAsFooterActive: Resolver<boolean> = (content, services, editor) => {
  const node = selectedNodeResolver(content, services, editor) as ProseMirrorNode | undefined;
  return node?.attrs?.banner?.position === 'BOTTOM';
};

const AddCellButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  return (
    <ToolbarButton
      disabled={toolbarItem.attributes.disabled}
      prefix={AddSmall}
      onClick={() => {
        // @ts-expect-error
        toolbarItem.tiptapEditor.commands.addCellRight(
          toolbarItem.attributes.selectedNode.lastChild.attrs.id
        );
      }}
      dataHook={LAYOUT_PLUGIN_TOOLBAR_ADD_CELL_BUTTON}
      tooltip={t('Layouts_LayoutAddCell_Tooltip')}
      tabIndex={toolbarItem.presentation.tabIndex}
    />
  );
};

const LayoutSetAsHeaderButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  const onClick = toolbarItem.commands.click;
  const isActive = !!toolbarItem.attributes.active;

  return (
    <ToolbarButton
      prefix={Banner}
      onClick={() => onClick?.()}
      dataHook={PLUGIN_TOOLBAR_SET_AS_HEADER_BUTTON}
      label={t(toolbarItem.presentation.label)}
      tabIndex={toolbarItem.presentation.tabIndex}
      active={isActive}
    />
  );
};

const LayoutSetAsFooterButton: React.FC<{
  toolbarItem: IToolbarItem;
}> = ({ toolbarItem }) => {
  const { t } = useContext(RicosContext) || {};

  const onClick = toolbarItem.commands.click;
  const isActive = !!toolbarItem.attributes.active;

  return (
    <ToolbarButton
      prefix={Footer}
      onClick={() => onClick?.()}
      dataHook={PLUGIN_TOOLBAR_SET_AS_FOOTER_BUTTON}
      label={t(toolbarItem.presentation.label)}
      tabIndex={toolbarItem.presentation.tabIndex}
      active={isActive}
    />
  );
};

const isToolbarVisible = (selection: Selection | NodeSelection): boolean => {
  const isVisibleInSelection =
    'node' in selection && selection.node?.type.name === TIPTAP_LAYOUT_TYPE;

  if (isVisibleInSelection) {
    return true;
  }

  if ('node' in selection) {
    return false;
  }

  // Defer to nested plugins that own their own subtree toolbar (e.g. collapsible list).
  // If a nested container is closer to the selection than the layout, that plugin wins.
  const closestContainer = findParentNodeClosestToPos(
    selection.$from,
    node => node.type.name === TIPTAP_LAYOUT_TYPE || node.type.name === TIPTAP_COLLAPSIBLE_LIST_TYPE
  );

  return closestContainer?.node.type.name === TIPTAP_LAYOUT_TYPE;
};
